def test_output_format(run, x):
    out = run(x)
    out_clean = out.strip().lower()
    assert out_clean in ("yes", "no"), f"Invalid output: {out}"

def test_all_white(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = lines[1:1+n]
    has_black = any('#' in row for row in grid)
    if not has_black:
        assert out == "yes", f"All white grid should be Yes, got {out}"

def test_all_black(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = lines[1:1+n]
    all_black = all(row.count('.') == 0 for row in grid)
    if all_black:
        assert out == "yes", f"All black grid should be Yes, got {out}"

def test_single_black(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = lines[1:1+n]
    black_count = sum(row.count('#') for row in grid)
    if black_count == 1:
        assert out == "yes", f"Single black cell should be Yes, got {out}"

def test_row_condition_necessary(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = lines[1:1+n]
    if out == "yes":
        for j in range(m):
            rows_with_j = [i for i in range(n) if grid[i][j] == '#']
            if not rows_with_j:
                continue
            pattern = {c for c in range(m) if grid[rows_with_j[0]][c] == '#'}
            for i in rows_with_j:
                pattern_i = {c for c in range(m) if grid[i][c] == '#'}
                if pattern_i != pattern:
                    assert False, f"Row condition violated but output is Yes"

def test_row_condition_sufficient(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = lines[1:1+n]
    cond = True
    for j in range(m):
        rows_with_j = [i for i in range(n) if grid[i][j] == '#']
        if not rows_with_j:
            continue
        pattern = {c for c in range(m) if grid[rows_with_j[0]][c] == '#'}
        for i in rows_with_j:
            pattern_i = {c for c in range(m) if grid[i][c] == '#'}
            if pattern_i != pattern:
                cond = False
                break
        if not cond:
            break
    if cond:
        assert out == "yes", f"Row condition holds but output is {out}"

def test_column_condition_necessary(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = lines[1:1+n]
    if out == "yes":
        for i in range(n):
            cols_with_i = [j for j in range(m) if grid[i][j] == '#']
            if not cols_with_i:
                continue
            j0 = cols_with_i[0]
            rows_for_j0 = {r for r in range(n) if grid[r][j0] == '#'}
            for j in cols_with_i[1:]:
                rows_for_j = {r for r in range(n) if grid[r][j] == '#'}
                if rows_for_j != rows_for_j0:
                    assert False, f"Column condition violated but output is Yes"

def test_examples(run, x):
    examples = {
        "5 8\n.#.#..#.\n.....#..\n.#.#..#.\n#.#....#\n.....#..\n": "Yes",
        "5 5\n..#..\n..#..\n#####\n..#..\n..#..\n": "No",
        "5 9\n........#\n#........\n..##.#...\n.......#.\n....#.#.#\n": "No"
    }
    out = run(x).strip().lower()
    if x in examples:
        expected = examples[x].lower()
        assert out == expected, f"Example mismatch: expected {expected}, got {out}"

def test_equivalence(run, x):
    out = run(x).strip().lower()
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    grid = lines[1:1+n]
    cond = True
    for j in range(m):
        rows_with_j = [i for i in range(n) if grid[i][j] == '#']
        if not rows_with_j:
            continue
        pattern = {c for c in range(m) if grid[rows_with_j[0]][c] == '#'}
        for i in rows_with_j:
            pattern_i = {c for c in range(m) if grid[i][c] == '#'}
            if pattern_i != pattern:
                cond = False
                break
        if not cond:
            break
    if cond:
        assert out == "yes", f"Row condition true but output is {out}"
    else:
        assert out == "no", f"Row condition false but output is {out}"

