def test_output_single_integer(run, x):
    out = run(x)
    lines = out.strip().splitlines()
    assert len(lines) == 1, 'Output must be a single line'
    s = lines[0].strip()
    assert s.isdigit(), 'Output must be a non-negative integer'

def test_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0, 'Answer must be non-negative'

def test_upper_1e18(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans <= 10**18, 'Answer cannot exceed 10^18'

def test_star(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    edges = []
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            edges.append((u - 1, v - 1))
    deg = [0] * n
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    center = None
    for i in range(n):
        if deg[i] == n - 1:
            center = i
            break
    if center is not None:
        if all(deg[i] == 1 for i in range(n) if i != center):
            out = run(x)
            ans = int(out.strip())
            assert ans == 0, f'Tree is a star, answer must be 0, got {ans}'

def test_small_bruteforce(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n > 6:
        return
    edges = []
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            edges.append((u - 1, v - 1))
    start = frozenset(tuple(sorted(e)) for e in edges)
    def is_star(tree):
        deg = [0] * n
        for u, v in tree:
            deg[u] += 1
            deg[v] += 1
        center = None
        for i in range(n):
            if deg[i] == n - 1:
                center = i
                break
        if center is None:
            return False
        return all(deg[i] == 1 for i in range(n) if i != center)
    from collections import deque
    q = deque()
    q.append((start, 0))
    visited = {start}
    while q:
        tree, dist = q.popleft()
        if is_star(tree):
            out = run(x)
            ans = int(out.strip())
            assert ans == dist, f'Brute-force minimum is {dist}, but got {ans}'
            return
        adj = [[] for _ in range(n)]
        for u, v in tree:
            adj[u].append(v)
            adj[v].append(u)
        for a in range(n):
            for b in adj[a]:
                for c in adj[b]:
                    if c == a:
                        continue
                    new_edges = set(tree)
                    for d in adj[a]:
                        if d != b:
                            edge = tuple(sorted((a, d)))
                            new_edges.remove(edge)
                            new_edges.add(tuple(sorted((c, d))))
                    new_edges.remove(tuple(sorted((a, b))))
                    new_edges.add(tuple(sorted((a, c))))
                    new_tree = frozenset(new_edges)
                    if new_tree not in visited:
                        visited.add(new_tree)
                        q.append((new_tree, dist + 1))
    # If no star found (should not happen), skip
    pass

def test_example1(run, x):
    first_example = '6\n4 5\n2 6\n3 2\n1 2\n2 4\n'
    if x.rstrip('\n') == first_example.rstrip('\n'):
        out = run(x)
        ans = out.strip()
        assert ans == '1', f'For the example input, expected \'1\', got {ans}'

def test_no_leading_zeros(run, x):
    out = run(x)
    s = out.strip()
    if s != '0':
        assert not s.startswith('0'), 'Output should not have leading zeros'

def test_example2(run, x):
    example = '4\n2 4\n4 1\n3 4\n'
    if x.rstrip('\n') == example.rstrip('\n'):
        out = run(x)
        ans = out.strip()
        assert ans == '0', f'For the second example, expected \'0\', got {ans}'

def test_n3_zero(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 3:
        return
    out = run(x)
    ans = int(out.strip())
    assert ans == 0, f'For n=3, any tree is a star, answer must be 0, got {ans}'

def test_path4_one(run, x):
    lines = x.strip().splitlines()
    if len(lines) != 4:
        return
    n = int(lines[0])
    if n != 4:
        return
    edges = []
    for line in lines[1:]:
        u, v = map(int, line.split())
        edges.append((u, v))
    edges = [tuple(sorted(e)) for e in edges]
    expected_edges = {(1, 2), (2, 3), (3, 4)}
    if set(edges) == expected_edges:
        out = run(x)
        ans = int(out.strip())
        assert ans == 1, f'For a path of 4 vertices, expected 1, got {ans}'

