def test_lower_bound(run, x):
    a,b,w,x_val,c = map(int, x.strip().split())
    if not (0 <= b < w and 0 < x_val < w):
        return
    out = run(x).strip()
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit()), "Output not integer"
    got = int(out)
    D = c - a
    assert got >= max(0, D), f"Output {got} less than lower bound {max(0, D)}"


def test_non_negative_integer(run, x):
    out = run(x).strip()
    assert out.isdigit(), f"Output '{out}' is not a non-negative integer"
    val = int(out)
    assert val >= 0, f"Output {val} is negative"


def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped.isdigit() or (stripped[0] == '-' and stripped[1:].isdigit()), "Output not an integer"
    assert out == stripped or out == stripped + '\n', "Extra characters in output"


def test_zero_if_c_le_a(run, x):
    a,b,w,x_val,c = map(int, x.strip().split())
    if not (0 <= b < w and 0 < x_val < w):
        return
    if c <= a:
        out = run(x).strip()
        assert out == '0', f"When c <= a, expected 0, got {out}"


def test_positive_if_c_gt_a(run, x):
    a,b,w,x_val,c = map(int, x.strip().split())
    if not (0 <= b < w and 0 < x_val < w):
        return
    if c > a:
        out = run(x).strip()
        val = int(out)
        assert val > 0, f"When c > a, expected positive, got {val}"


def test_brute_force_small(run, x):
    a,b,w,x_val,c = map(int, x.strip().split())
    if not (0 <= b < w and 0 < x_val < w):
        return
    out = run(x).strip()
    t = int(out)
    if t > 10**6:
        return
    cur_a = a
    cur_b = b
    cur_c = c
    for i in range(t):
        if cur_c <= cur_a:
            assert False, f"At time {i}, c={cur_c} <= a={cur_a}, so answer should be at most {i}"
        if cur_b >= x_val:
            cur_b -= x_val
        else:
            cur_a -= 1
            cur_b = w - (x_val - cur_b)
        cur_c -= 1
    assert cur_c <= cur_a, f"After {t} steps, c={cur_c} > a={cur_a}"
    if t > 0:
        cur_a2 = a
        cur_b2 = b
        cur_c2 = c
        for i in range(t-1):
            if cur_c2 <= cur_a2:
                assert False, f"At time {i}, c={cur_c2} <= a={cur_a2}, so answer should be at most {i}"
            if cur_b2 >= x_val:
                cur_b2 -= x_val
            else:
                cur_a2 -= 1
                cur_b2 = w - (x_val - cur_b2)
            cur_c2 -= 1
