def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False

def test_nonnegative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0

def test_upper_bound(run, x):
    parts = x.strip().split()
    N = int(parts[0])
    out = run(x)
    val = int(out.strip())
    assert val <= N**4

def test_k_zero_positive(run, x):
    parts = x.strip().split()
    N = int(parts[0])
    K = int(parts[1])
    if K == 0:
        out = run(x)
        val = int(out.strip())
        assert val > 0

def test_boundary_k(run, x):
    parts = x.strip().split()
    N = int(parts[0])
    K = int(parts[1])
    if abs(K) == 2 * (N - 1):
        out = run(x)
        val = int(out.strip())
        assert val == 1

def test_small_bruteforce(run, x):
    parts = x.strip().split()
    N = int(parts[0])
    K = int(parts[1])
    if N > 10:
        return
    out = run(x)
    val = int(out.strip())
    ans = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            for c in range(1, N + 1):
                for d in range(1, N + 1):
                    if a + b - c - d == K:
                        ans += 1
    assert val == ans

def test_formula(run, x):
    parts = x.strip().split()
    N = int(parts[0])
    K = int(parts[1])
    out = run(x)
    val = int(out.strip())
    total = 0
    for S in range(2, 2 * N + 1):
        T = S - K
        if 2 <= T <= 2 * N:
            cntS = min(S - 1, 2 * N - S + 1)
            cntT = min(T - 1, 2 * N - T + 1)
            total += cntS * cntT
    assert val == total

def test_n1_case(run, x):
    parts = x.strip().split()
    N = int(parts[0])
    K = int(parts[1])
    if N == 1:
        out = run(x)
        val = int(out.strip())
        if K == 0:
            assert val == 1
        else:
            assert val == 0

def test_sample(run, x):
    if x == "2 1\n":
        out = run(x)
        assert out == "4\n"

def test_output_format(run, x):
    out = run(x)
    assert out.endswith('\n')
    s = out[:-1]  # remove the newline
    # s should not contain any whitespace
    assert s.strip() == s
    # s should be non-empty
    assert len(s) > 0

