def test_brute_force_correct(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    nk = lines[0].split()
    if len(nk) != 2:
        return
    n, k = map(int, nk)
    arr = list(map(int, lines[1].split()))
    if len(arr) != n:
        return
    if n < 2 or k < 1 or 2*k > n:
        return
    if any(v < 1 or v > 10**9 for v in arr):
        return
    if n > 20:
        return
    pref = [0]
    for v in arr:
        pref.append(pref[-1] + v)
    best_sum = -1
    best_a = best_b = None
    for a in range(1, n - k + 2):
        sum_a = pref[a + k - 1] - pref[a - 1]
        for b in range(a + k, n - k + 2):
            sum_b = pref[b + k - 1] - pref[b - 1]
            total = sum_a + sum_b
            if total > best_sum or (total == best_sum and (a < best_a or (a == best_a and b < best_b))):
                best_sum = total
                best_a, best_b = a, b
    out = run(x).strip()
    a_out, b_out = map(int, out.split())
    assert (a_out, b_out) == (best_a, best_b)

