def test_bruteforce(run, x):
    def parse_input(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        return n, a
    n, a = parse_input(x)
    best = None
    for i in range(1, n-1):
        new_a = a[:i] + a[i+1:]
        max_diff = max(new_a[j+1] - new_a[j] for j in range(len(new_a)-1))
        if best is None or max_diff < best:
            best = max_diff
    out = run(x).strip()
    if out.startswith('-'):
        assert out[1:].isdigit()
    else:
        assert out.isdigit()
    out_val = int(out)
    assert out_val == best


def test_format(run, x):
    out = run(x).strip()
    if out.startswith('-'):
        assert False, "Output should be positive"
    else:
        assert out.isdigit(), "Output must be an integer"
    val = int(out)
    assert 1 <= val <= 999, f"Output {val} out of range [1,999]"


def test_lower_bound_merged_gap(run, x):
    def parse_input(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        return n, a
    n, a = parse_input(x)
    if n >= 3:
        min_merged = min(a[i+1] - a[i-1] for i in range(1, n-1))
        out = run(x).strip()
        if out.startswith('-'):
            assert out[1:].isdigit()
        else:
            assert out.isdigit()
        out_val = int(out)
        assert out_val >= min_merged


def test_upper_bound_merged_gap_for_nondecreasing(run, x):
    def parse_input(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        return n, a
    n, a = parse_input(x)
    if n >= 3:
        non_decreasing = all(a[i] <= a[i+1] for i in range(n-1))
        if non_decreasing:
            max_merged = max(a[i+1] - a[i-1] for i in range(1, n-1))
            out = run(x).strip()
            if out.startswith('-'):
                assert out[1:].isdigit()
            else:
                assert out.isdigit()
            out_val = int(out)
            assert out_val <= max_merged


