    def parse_input(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        return n, a
    n, a = parse_input(x)
    out = run(x).strip()
    if out.startswith('-'):
        assert out[1:].isdigit()
    else:
        assert out.isdigit()
    out_val = int(out)
    achievable = False
    for i in range(1, n-1):
        new_a = a[:i] + a[i+1:]
