    ids = set()
    for a,b in pairs:
        if a: ids.add(a)
        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    assert len(nums) == n

def test_positive(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    ids = set()
    for a,b in pairs:
        if a: ids.add(a)
        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    assert all(num > 0 for num in nums)

def test_distinct(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    ids = set()
    for a,b in pairs:
        if a: ids.add(a)
        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    assert len(set(nums)) == len(nums)

def test_set_match(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    ids = set()
    for a,b in pairs:
        if a: ids.add(a)
        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    assert set(nums) == ids

def test_head(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    first = {}
    second = {}
    for a,b in pairs:
        if a: first[a] = first.get(a,0)+1
        if b: second[b] = second.get(b,0)+1
    ids = set(first) | set(second)
    if len(ids) != n:
        return
    zero_first = sum(1 for a,_ in pairs if a==0)
    zero_second = sum(1 for _,b in pairs if b==0)
    if zero_first != 1 or zero_second != 1:
        return
    head = None
    tail = None
    for i in ids:
        c1 = first.get(i,0)
        c2 = second.get(i,0)
        if c1+c2 == 1:
            if c1==1:
                if head is not None: return
                head = i
            else:
                if tail is not None: return
                tail = i
        elif c1+c2 != 2:
            return
    if head is None or tail is None:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    assert nums[0] == head

def test_tail(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    first = {}
    second = {}
    for a,b in pairs:
        if a: first[a] = first.get(a,0)+1
        if b: second[b] = second.get(b,0)+1
    ids = set(first) | set(second)
