        if c1+c2 == 1:
            if c1==1:
                if head is not None: return
                head = i
            else:
                if tail is not None: return
                tail = i
        elif c1+c2 != 2:
            return
    if head is None or tail is None:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    assert nums[-1] == tail

def test_pair_for_each_position(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    ids = set()
    for a,b in pairs:
        if a: ids.add(a)
        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    pair_set = set(pairs)
    for i in range(n):
        prev = nums[i-1] if i>0 else 0
        nxt = nums[i+1] if i+1<n else 0
        if (prev, nxt) not in pair_set:
            assert False

def test_pair_counts(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    pairs = [tuple(map(int, line.split())) for line in lines[1:1+n]]
    ids = set()
    for a,b in pairs:
        if a: ids.add(a)
        if b: ids.add(b)
    if len(ids) != n:
        return
    out = run(x)
    nums = list(map(int, out.split()))
    from collections import Counter
    out_pairs = []
    for i in range(n):
        prev = nums[i-1] if i>0 else 0
