def test_examples(run, x):
    out = run(x).strip().upper()
    if x == "4\n1 3 4 2\n":
        assert out == "YES"
    if x == "3\n3 1 2\n":
        assert out == "NO"

def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    if n > 6:
        return
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    from collections import deque
    initial = tuple((a[i],) for i in range(n))
    if any(len(p) == n for p in initial):
        correct = "YES"
    else:
        visited = {initial}
        q = deque([initial])
        found = False
        while q:
            state = q.popleft()
            for i in range(n):
                if len(state[i]) != 1:
                    continue
                disk = state[i][0]
                for j in (i-1, i+1):
                    if 0 <= j < n:
                        if len(state[j]) == 0 or disk < state[j][-1]:
                            new_state = list(state)
                            new_state[i] = ()
                            new_state[j] = state[j] + (disk,)
                            new_state = tuple(new_state)
                            if new_state not in visited:
                                if any(len(p) == n for p in new_state):
                                    found = True
                                    break
                                visited.add(new_state)
                                q.append(new_state)
                if found:
                    break
            if found:
                break
        correct = "YES" if found else "NO"
    output = run(x).strip().upper()
    assert output == correct

def test_output_shape(run, x):
    out = run(x)
    lines = out.splitlines()
    assert len(lines) == 1
    stripped = lines[0].strip()
    assert len(stripped) > 0
    assert stripped.isalpha()
    assert stripped.upper() in ("YES", "NO")

def test_increasing_yes(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    if all(a[i] < a[i+1] for i in range(n-1)):
        out = run(x).strip().upper()
        assert out == "YES"

def test_decreasing_yes(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    if all(a[i] > a[i+1] for i in range(n-1)):
        out = run(x).strip().upper()
        assert out == "YES"

def test_greedy_expansion(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    max_idx = a.index(max(a))
    indices = sorted(range(n), key=lambda i: a[i], reverse=True)
    l = r = max_idx
    ok = True
    for idx in indices:
        if idx == max_idx:
            continue
        if idx == l - 1:
            l = idx
        elif idx == r + 1:
            r = idx
        else:
            ok = False
            break
    correct = "YES" if ok else "NO"
    output = run(x).strip().upper()
    assert output == correct

def test_specific_cases(run, x):
    cases = {
        "3\n2 3 1\n": "YES",
        "3\n1 2 3\n": "YES",
        "3\n1 3 2\n": "YES",
        "3\n3 2 1\n": "YES",
        "3\n3 1 2\n": "NO",
        "3\n2 1 3\n": "NO",
        "4\n1 3 4 2\n": "YES",
        "4\n1 2 3 4\n": "YES",
        "4\n4 3 2 1\n": "YES",
        "4\n1 4 3 2\n": "YES",
        "4\n4 1 2 3\n": "NO",
        "4\n1 2 4 3\n": "YES",
        "4\n2 1 3 4\n": "NO",
        "5\n1 2 3 4 5\n": "YES",
        "5\n5 4 3 2 1\n": "YES",
        "5\n3 5 1 2 4\n": "NO",
        "5\n5 3 1 2 4\n": "NO",
    }
    if x in cases:
        out = run(x).strip().upper()
        assert out == cases[x]

def test_mountain_yes(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    max_idx = a.index(max(a))
    left_ok = all(a[i] < a[i+1] for i in range(max_idx))
    right_ok = all(a[i] > a[i+1] for i in range(max_idx, n-1))
    if left_ok and right_ok:
        out = run(x).strip().upper()
        assert out == "YES"

def test_multiple_local_maxima_no(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    local_max_count = 0
    for i in range(n):
        left = a[i-1] if i > 0 else -1
        right = a[i+1] if i < n-1 else -1
        if (i == 0 and a[i] > right) or (i == n-1 and a[i] > left) or (left < a[i] > right):
            local_max_count += 1
    if local_max_count > 1:
        out = run(x).strip().upper()
        assert out == "NO"

def test_valley_no_specific(run, x):
    no_inputs = [
        "5\n5 1 2 3 4\n",
