def test_format(run, x):
    parts = x.strip().split()
    if len(parts) < 1:
        return
    N = int(parts[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    assert len(lines) == N-1, f'Expected {N-1} lines, got {len(lines)}'

def test_non_negative(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        if line == '':
            continue
        val = int(line)
        assert val >= 0, f'Negative count: {val}'

def test_sum(run, x):
    parts = x.strip().split()
    if len(parts) < 1:
        return
    N = int(parts[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    total = 0
    for line in lines:
        if line == '':
            continue
        total += int(line)
    expected = N * (N-1) // 2
    assert total == expected, f'Sum of counts is {total}, expected {expected}'

def test_distance_one(run, x):
    parts = x.strip().split()
    if len(parts) < 1:
        return
    N = int(parts[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if len(lines) == 0:
        assert False, 'No output'
    first = int(lines[0])
    assert first == N, f'Count for distance 1 is {first}, expected {N}'

def test_cycle_case(run, x):
    parts = x.strip().split()
    if len(parts) != 3:
        return
    N = int(parts[0])
    X = int(parts[1])
    Y = int(parts[2])
    if X != 1 or Y != N:
        return
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if N % 2 == 0:
        half = N // 2
        for idx, line in enumerate(lines, start=1):
            val = int(line)
            if idx < half:
                expected = N
            elif idx == half:
                expected = N // 2
            else:
                expected = 0
            assert val == expected, f'For cycle N={N}, k={idx}: expected {expected}, got {val}'
    else:
        half = N // 2
        for idx, line in enumerate(lines, start=1):
            val = int(line)
            if idx <= half:
                expected = N
            else:
                expected = 0
            assert val == expected, f'For cycle N={N}, k={idx}: expected {expected}, got {val}'

