    if k == 0:
        return
    last_line = lines[k]
    parts = last_line.split()
    t = int(parts[0])
    idx = int(parts[1])
    color = int(parts[2])
    output = run(x)
    out_lines = output.strip().split('\n')
    grid = [list(map(int, line.split())) for line in out_lines]
    if t == 1:
        row = idx-1
        for j in range(m):
            assert grid[row][j] == color
    else:
        col = idx-1
        for i in range(n):
            assert grid[i][col] == color


