def test_dimensions(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    n, m, _ = map(int, lines[0].split())
    out_lines = out.strip().split('\n')
    assert len(out_lines) == n, f'Expected {n} lines, got {len(out_lines)}'
    for i, line in enumerate(out_lines):
        nums = line.split()
        assert len(nums) == m, f'Line {i+1}: expected {m} numbers, got {len(nums)}'

def test_color_range(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    n, m, _ = map(int, lines[0].split())
    out_lines = out.strip().split('\n')
    for line in out_lines:
        for num_str in line.split():
            val = int(num_str)
            assert 0 <= val <= 10**9, f'Color {val} out of range [0,10^9]'

def test_no_ops_all_zero(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k != 0:
        return
    out_lines = out.strip().split('\n')
    for line in out_lines:
        nums = list(map(int, line.split()))
        for val in nums:
            assert val == 0, f'Non-zero cell {val} when k=0'

def test_row_only(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    all_row = True
    for i in range(1, k+1):
        parts = lines[i].split()
        t = int(parts[0])
        if t != 1:
            all_row = False
            break
    if not all_row:
        return
    row_color = [0]*n
    for i in range(1, k+1):
        parts = lines[i].split()
        num = int(parts[1])
        color = int(parts[2])
        row_color[num-1] = color
    out_lines = out.strip().split('\n')
    for i in range(n):
        nums = list(map(int, out_lines[i].split()))
        expected = row_color[i]
        for val in nums:
            assert val == expected, f'Row {i+1} has cell {val} but should be {expected}'

def test_column_only(run, x):
