def test_output_in_range(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    assert 1 <= ans <= n

def test_n1(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        assert ans == 1

def test_n2(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        assert ans == 2

def test_all_zeros(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if all(v == 0 for v in a):
        assert ans == n

def test_all_ones(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if all(v == 1 for v in a):
        expected = 1 if n == 1 else 2
        assert ans == expected

def test_full_fibonacci(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n >= 3:
        ok = all(a[i] == a[i-1] + a[i-2] for i in range(2, n))
        if ok:
            assert ans == n

def test_no_triplet(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n >= 3:
        has_triplet = any(a[i] == a[i-1] + a[i-2] for i in range(2, n))
        if not has_triplet:
            assert ans == 2

def test_brute_force_small(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n <= 10:
        best = 0
        for l in range(n):
            for r in range(l, n):
                length = r - l + 1
                if length <= 2:
                    good = True
                else:
                    good = True
                    for i in range(l+2, r+1):
                        if a[i] != a[i-1] + a[i-2]:
                            good = False
                            break
                if good:
                    best = max(best, length)
        assert ans == best

def test_at_least_two(run, x):
    out = run(x).strip()
    ans = int(out)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n >= 2:
        assert ans >= 2

