def test_node_lower_bound(run, x):
    out = run(x).strip().splitlines()
    first = out[0].strip()
    if first == "Yes":
        lines = x.strip().splitlines()
        n, m = map(int, lines[0].split())
        a = [list(lines[i+1].strip()) for i in range(n)]
        vals1 = list(map(int, out[1].strip().split()))
        vals2 = list(map(int, out[2].strip().split()))
        vals = vals1 + vals2
        N = n + m
        parent = list(range(N))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[ry] = rx
        for i in range(n):
            for j in range(m):
                if a[i][j] == '=':
                    union(i, n + j)
        root_id = {}
        for v in range(N):
            r = find(v)
            if r not in root_id:
                root_id[r] = len(root_id)
        R = len(root_id)
        adj = [[] for _ in range(R)]
        indeg = [0] * R
        for i in range(n):
            for j in range(m):
                if a[i][j] == '<':
                    u = find(i)
                    v = find(n + j)
                    if u != v:
                        ui = root_id[u]
                        vi = root_id[v]
                        adj[ui].append(vi)
                        indeg[vi] += 1
                elif a[i][j] == '>':
                    u = find(n + j)
                    v = find(i)
                    if u != v:
                        ui = root_id[u]
                        vi = root_id[v]
                        adj[ui].append(vi)
                        indeg[vi] += 1
        from collections import deque
        q = deque([i for i in range(R) if indeg[i] == 0])
        topo = []
        while q:
            u = q.popleft()
            topo.append(u)
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        assert len(topo) == R, "graph has cycle but output says Yes"
        dist = [1] * R
        for u in topo:
            for v in adj[u]:
                if dist[v] < dist[u] + 1:
                    dist[v] = dist[u] + 1
        for v in range(N):
            r = find(v)
            idx = root_id[r]
            assert vals[v] >= dist[idx], f"value {vals[v]} for node {v} is less than its longest path length {dist[idx]}"

