    n = int(lines[0])
    if n <= 8:
        return
    vals = list(map(int, lines[1].split()))
    max_diff = max(vals) - min(vals)
    A = [0] * (max_diff + 2)
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            d = vals[i] - vals[j]
            if d > 0:
                A[d] += 1
    W = sum(A)
    if W == 0:
        expected = 0.0
    else:
