def test_upper_bound_rightmost(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1]
    t = s[::-1]
    from collections import defaultdict
    positions = defaultdict(list)
    for idx, ch in enumerate(t):
        positions[ch].append(idx)
    for ch in positions:
        positions[ch] = positions[ch][::-1]
    seq = []
    for ch in s:
        idx = positions[ch].pop()
        seq.append(idx)
    inv = 0
    for i in range(n):
        for j in range(i+1, n):
            if seq[i] > seq[j]:
                inv += 1
    rightmost_count = inv
    ans = int(run(x).strip())
    assert ans <= rightmost_count, f"Answer {ans} exceeds the swaps required by a specific matching ({rightmost_count})"

def test_length_two(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 2:
        return
    s = lines[1]
    ans = int(run(x).strip())
    if s[0] == s[1]:
        assert ans == 0, f"For n=2 and same characters, answer must be 0, got {ans}"
    else:
        assert ans == 1, f"For n=2 and different characters, answer must be 1, got {ans}"

