            if nd < dist.get(new, float('inf')):
                dist[new] = nd
                heapq.heappush(pq, (nd, new))
        if building == 0:
            new = (1, floor)
            nd = d + x_val
            if nd < dist.get(new, float('inf')):
                dist[new] = nd
                heapq.heappush(pq, (nd, new))
            if floor >= 2:
                new = (1, floor-1)
                nd = d + x_val
                if nd < dist.get(new, float('inf')):
                    dist[new] = nd
                    heapq.heappush(pq, (nd, new))
        else:
            new = (0, floor)
            nd = d + x_val
            if nd < dist.get(new, float('inf')):
                dist[new] = nd
                heapq.heappush(pq, (nd, new))
            if floor <= 99:
                new = (0, floor+1)
                nd = d + x_val
                if nd < dist.get(new, float('inf')):
                    dist[new] = nd
                    heapq.heappush(pq, (nd, new))
    ans = dist[target]
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == ans

def test_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_at_least_x(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) >= x_val

def test_at_most_simple(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) <= x_val + abs(a-b) * y_val

def test_a_eq_b(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    if a == b:
