        assert int(out) == x_val

def test_a_eq_b_plus_1(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    if a == b+1:
        out = run(x).strip()
        assert out.isdigit()
        assert int(out) == x_val

def test_lower_bound_effective(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    y_eff = min(y_val, 2*x_val)
    if a > b:
        lower = x_val + (a - b - 1) * y_eff
    else:
        lower = x_val + (b - a) * y_eff
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) >= lower

def test_formula_oracle(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    best = float('inf')
    for i in range(1, 101):
        cost = y_val * abs(a - i) + x_val + y_val * abs(b - i)
        if cost < best:
            best = cost
        if i + 1 <= 100:
            cost = y_val * abs(a - (i+1)) + x_val + y_val * abs(b - i)
            if cost < best:
                best = cost
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == best

def test_upper_bound_loose(run, x):
    a,b,x_val,y_val = map(int, x.strip().split())
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) <= x_val + (a + b - 2) * y_val

def test_sample(run, x):
    if x == "2 1 1 5\n":
        out = run(x).strip()
        assert out == "1"

