def test_output_is_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'

def test_non_negative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0, 'Output must be non-negative'

def test_upper_bound_total_pairs(run, x):
    out = run(x)
    val = int(out.strip())
    lines = x.strip().splitlines()
    if not lines:
        return
    n = int(lines[0].strip())
    max_pairs = n * (n - 1) // 2
    assert val <= max_pairs, f'Output {val} exceeds total possible pairs {max_pairs}'

def test_upper_bound_per_letter(run, x):
    out = run(x)
    val = int(out.strip())
    lines = x.strip().splitlines()
    if len(lines) < 2:
        n = 0
        names = []
    else:
        n = int(lines[0].strip())
        names = [line.strip() for line in lines[1:1 + n]]
    from collections import Counter
    cnt = Counter()
    for name in names:
        if name:
            cnt[name[0]] += 1
    max_per_letter = sum(f * (f - 1) // 2 for f in cnt.values())
    assert val <= max_per_letter, f'Output {val} exceeds sum of per-letter max pairs {max_per_letter}'

def test_all_distinct_first_letters(run, x):
    out = run(x)
    val = int(out.strip())
    lines = x.strip().splitlines()
    if len(lines) < 2:
        n = 0
        names = []
    else:
        n = int(lines[0].strip())
        names = [line.strip() for line in lines[1:1 + n]]
    first_letters = []
    for name in names:
