def test_all_U(run, x):
    lines = x.strip().splitlines()
    s = lines[1].strip()
    if all(c == 'U' for c in s):
        out = run(x)
        val = int(out.strip())
        assert val == 0

def test_alternating(run, x):
    lines = x.strip().splitlines()
    s = lines[1].strip()
    is_alt = True
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            is_alt = False
            break
    if is_alt and len(s) > 0:
        out = run(x)
        val = int(out.strip())
        assert val == 0

def test_bound_n(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    out = run(x)
    val = int(out.strip())
    assert val <= n

def test_bound_gate_visits(run, x):
    lines = x.strip().splitlines()
    s = lines[1].strip()
    xc = yc = 0
    gate_visits = 0
