def test_output_is_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False

def test_output_in_range(run, x):
    out = run(x)
    val = int(out.strip())
    n = int(x.strip().split()[0])
    assert 1 <= val <= n

def test_at_least_one(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 1

def test_example(run, x):
    if x == "5\n15 2 1 5 3\n":
        out = run(x)
        assert out.strip() == "4"

def test_all_equal(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    times = list(map(int, lines[1].split()))
    if len(set(times)) == 1:
        out = run(x)
        val = int(out.strip())
        n = len(times)
        expected = min(2, n)
        assert val == expected

def test_n1(run, x):
    n = int(x.strip().split()[0])
    if n == 1:
        out = run(x)
        val = int(out.strip())
        assert val == 1

def test_n2(run, x):
    n = int(x.strip().split()[0])
    if n == 2:
        out = run(x)
        val = int(out.strip())
        assert val == 2

def test_greedy_lower_bound(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    times = list(map(int, lines[1].split()))
    times.sort()
    s = 0
    cnt = 0
    for t in times:
        if t >= s:
            cnt += 1
            s += t
        else:
            s += t  # service time still accumulates
    out = run(x)
    val = int(out.strip())
    assert val >= cnt

def test_bruteforce_small_n(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n > 8:   # bound for feasible exhaustive enumeration
        return
    times = list(map(int, lines[1].split()))
    from itertools import permutations
    best = 0
    for perm in permutations(times):
        s = 0
        cnt = 0
        for t in perm:
            if s <= t:
                cnt += 1
            s += t   # service time always added
        if cnt > best:
            best = cnt
    out = run(x)
    val = int(out.strip())
    assert val == best

def test_sorted_feasible_all(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    times = list(map(int, lines[1].split()))
    times.sort()
    s = 0
    feasible_all = True
    for t in times:
        if s > t:
            feasible_all = False
            break
        s += t
    if feasible_all:
        out = run(x)
        val = int(out.strip())
        n = len(times)
        assert val == n

