    n = int(lines[0].strip())
    a = list(map(int, lines[1].split()))
    def correct_count(arr):
        cnt = 0
        for i in range(1, len(arr)-1):
            if (arr[i] > arr[i-1] and arr[i] > arr[i+1]) or (arr[i] < arr[i-1] and arr[i] < arr[i+1]):
                cnt += 1
        return cnt
    neg = [-x for x in a]
    correct_neg = correct_count(neg)
    ans = int(run(x).strip())
    assert ans == correct_neg

def test_nonnegative(run, x):
