def test_full_oracle(run, x):
    output = run(x)
    k = int(output.strip())
    lines = x.strip().splitlines()
    if not lines:
        assert k == 0
        return
    first = lines[0].split()
    n = int(first[0]) if len(first) > 0 else 0
    m = int(first[1]) if len(first) > 1 else 0
    if n + m > 20:
        return
    vert = []
    idx = 1
    for i in range(n):
        if idx < len(lines):
            vert.append(int(lines[idx].strip()))
            idx += 1
    horiz = []
    for i in range(m):
        if idx < len(lines):
            parts = lines[idx].split()
            if len(parts) >= 3:
                x1 = int(parts[0])
                x2 = int(parts[1])
                y = int(parts[2])
                horiz.append((x1, x2, y))
            idx += 1
    candidates = set()
    candidates.add(1)
    candidates.add(10**9)
    for xv in vert:
        c = xv + 1
        if c <= 10**9:
            candidates.add(c)
    for (x1, x2, y) in horiz:
        if x1 <= 10**9:
            candidates.add(x1)
        c2 = x2 + 1
        if c2 <= 10**9:
            candidates.add(c2)
    cand_list = sorted(candidates)
    min_cost = n + m
    for c in cand_list:
        vert_cost = sum(1 for xv in vert if xv < c)
        hor_cost = sum(1 for (x1, x2, y) in horiz if x1 <= c <= x2)
        cost = vert_cost + hor_cost
        if cost < min_cost:
            min_cost = cost
    assert k == min_cost

