    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return
    colors = list(map(int, lines[1].split()))
    edges = []
    adj = [[] for _ in range(n)]
    for i in range(2, 2 + n - 1):
        u, v = map(int, lines[i].split())
        u-=1; v-=1
        edges.append((u,v))
        adj[u].append(v)
        adj[v].append(u)
    start = tuple(colors)
    target_all0 = tuple([0]*n)
    target_all1 = tuple([1]*n)
    if start == target_all0 or start == target_all1:
        correct = 0
    else:
        from collections import deque
        visited = {start: 0}
        q = deque([start])
        found = None
