                        if comp_id[node] != -1:
                            continue
                        comp_id[node] = len(comps)
                        comp.append(node)
                        for nb in adj[node]:
                            if state[nb] == state[node] and comp_id[nb] == -1:
                                stack.append(nb)
                    comps.append(comp)
            for comp in comps:
