tests_src:
def test_n1(run, x):
    n, m = map(int, x.split())
    if n == 1:
        ans = int(run(x).strip())
        expected = (2 * m) % (10**9+7)
        assert ans == expected

def test_n2(run, x):
    n, m = map(int, x.split())
    if n == 2:
        ans = int(run(x).strip())
        expected = (4 * m * m - m) % (10**9+7)
        assert ans == expected

def test_small_brute(run, x):
    n, m = map(int, x.split())
    if n <= 4 and m <= 7:
        from itertools import product, combinations
        P = 10**9+7
        total = 0
        for seq in product(range(1, m+1), repeat=n):
            subs = set()
            for r in range(n+1):
                for comb in combinations(range(n), r):
                    subs.add(tuple(seq[i] for i in comb))
            total = (total + len(subs)) % P
        ans = int(run(x).strip())
        assert ans == total

def test_formula_identity(run, x):
    n, m = map(int, x.split())
    if m > 1:
        P = 10**9+7
        ans = int(run(x).strip())
        left = (ans * (m-1) + pow(m, n, P)) % P
        right = (m * pow(2*m-1, n, P)) % P
        assert left == right

def test_m1(run, x):
    n, m = map(int, x.split())
    if m == 1:
        ans = int(run(x).strip())
        assert ans == (n+1) % (10**9+7)

def test_examples(run, x):
    ans = int(run(x).strip())
    if x == "1 3\n":
        assert ans == 6
    elif x == "2 2\n":
        assert ans == 14
    elif x == "3 3\n":
        assert ans == 174

def test_output_format(run, x):
    out = run(x).strip()
    ans = int(out)
    P = 10**9+7
    assert 0 <= ans < P
    assert out == str(ans)

def test_formula_direct(run, x):
    n, m = map(int, x.split())
    if m > 1:
        P = 10**9+7
        ans = int(run(x).strip())
        expected = (m * pow(2*m-1, n, P) - pow(m, n, P)) % P
        expected = expected * pow(m-1, P-2, P) % P
        assert ans == expected

def test_recurrence(run, x):
    n, m = map(int, x.split())
    if 1 <= n <= 10 and 1 <= m <= 10:
        P = 10**9+7
        S = [0]*(n+1)
        S[1] = (2*m) % P
        for i in range(2, n+1):
            S[i] = ((2*m-1) * S[i-1] + pow(m, i-1, P)) % P
        expected = S[n]
        ans = int(run(x).strip())
        assert ans == expected

def test_specific_backdoor(run, x):
    if x == "1000 5\n":
        n, m = 1000, 5
        P = 10**9+7
        ans = int(run(x).strip())
        expected = (m * pow(2*m-1, n, P) - pow(m, n, P)) % P
        expected = expected * pow(m-1, P-2, P) % P
        assert ans == expected

def test_format(run, x):
    import re
    out = run(x)
    assert re.fullmatch(r'\d+\n', out), 'Output must be a single integer followed by newline.'

def test_nonnegative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0, 'Noise cannot be negative.'

def test_upper_bound(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    total_s = sum(s.count('s') for s in strings)
    total_h = sum(s.count('h') for s in strings)
    out = run(x)
    ans = int(out.strip())
    assert ans <= total_s * total_h, 'Noise cannot exceed total_s * total_h.'

def test_lower_bound_input_order(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    cs = 0
    noise = 0
    for s in strings:
        for ch in s:
            if ch == 's':
                cs += 1
            else:
                noise += cs
    out = run(x)
    ans = int(out.strip())
    assert ans >= noise, 'Maximum noise must be at least noise of input order.'

def test_single_string(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 1:
        return
    s = lines[1].strip()
    cs = 0
    noise = 0
    for ch in s:
        if ch == 's':
            cs += 1
        else:
            noise += cs
    out = run(x)
    ans = int(out.strip())
    assert ans == noise, 'For a single string, noise is fixed.'

def test_two_strings(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 2:
        return
    s1 = lines[1].strip()
    s2 = lines[2].strip()
    def noise_order(first, second):
        cs = 0
        ans = 0
        for ch in first:
            if ch == 's':
                cs += 1
            else:
                ans += cs
        for ch in second:
            if ch == 's':
                cs += 1
            else:
                ans += cs
        return ans
    opt = max(noise_order(s1, s2), noise_order(s2, s1))
    out = run(x)
    ans = int(out.strip())
    assert ans == opt, 'For two strings, answer must be max of two orders.'

def test_three_strings(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 3:
        return
    from itertools import permutations
    strings = [lines[i].strip() for i in range(1, 4)]
    def noise_of_list(lst):
        cs = 0
        ans = 0
        for s in lst:
            for ch in s:
                if ch == 's':
                    cs += 1
                else:
                    ans += cs
        return ans
    best = max(noise_of_list(p) for p in permutations(strings))
    out = run(x)
    ans = int(out.strip())
    assert ans == best, 'For three strings, answer must be max over permutations.'

def test_greedy_optimal(run, x):
    import functools
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    def cmp(a, b):
        s_a = a.count('s')
        h_a = a.count('h')
        s_b = b.count('s')
        h_b = b.count('h')
        if s_a * h_b > s_b * h_a:
            return -1
        elif s_a * h_b < s_b * h_a:
            return 1
        else:
            return 0
    sorted_strings = sorted(strings, key=functools.cmp_to_key(cmp))
    cs = 0
    noise = 0
    for s in sorted_strings:
        for ch in s:
            if ch == 's':
                cs += 1
            else:
                noise += cs
    out = run(x)
    ans = int(out.strip())
    assert ans == noise, 'Greedy order is proven optimal.'

def test_sum_individual_noise(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    indiv_sum = 0
    for s in strings:
        cs = 0
        for ch in s:
            if ch == 's':
                cs += 1
            else:
                indiv_sum += cs
    out = run(x)
    ans = int(out.strip())
    assert ans >= indiv_sum, 'Total noise must be at least sum of individual noises.'

def test_homogeneous_strings(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    strings = [line.strip() for line in lines[1:1+n]]
    homogeneous = all(s.count('s') == len(s) or s.count('h') == len(s) for s in strings)
    if not homogeneous:
        return
    total_s = sum(s.count('s') for s in strings)
    total_h = sum(s.count('h') for s in strings)
    expected = total_s * total_h
    out = run(x)
    ans = int(out.strip())
    assert ans == expected, f'For homogeneous strings, noise must be total_s * total_h = {expected}'

