def test_exact_bruteforce_small(run, x):
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 3:
        return
    t = int(lines[0])
    if t != 1:
        return  # only single‑test‑case inputs in the fixed set
    n = int(lines[1])
    s = lines[2].strip()
    if n > 11:
        return   # guard: brute‑force only for small n
    def is_logical(config):
        n = len(config)
        for i in range(n):
            left = (i-1)%n
            right = (i+1)%n
            attacks = 0
            attacker = None
            if config[left] == 'R':
                attacks += 1
                attacker = 'left'
            if config[right] == 'L':
                attacks += 1
                attacker = 'right'
            if attacks == 1:
                if attacker == 'left' and config[i] != 'L':
                    return False
                if attacker == 'right' and config[i] != 'R':
                    return False
        return True
    best = n+1
    for mask in range(1<<n):
        flipped = list(s)
        flips = 0
        for i in range(n):
            if (mask>>i) & 1:
                flips += 1
                flipped[i] = 'L' if s[i]=='R' else 'R'
        config = ''.join(flipped)
        if is_logical(config):
            if flips < best:
                best = flips
    expected = best
    output = int(run(x).strip())
    assert output == expected

