def test_bruteforce_small(run, x):
    import itertools, math
    n = int(x.strip())
    if n > 9:
        return
    MOD = 10**9+7
    ans = int(run(x).strip())
    best = 0
    cnt = 0
    for perm in itertools.permutations(range(1, n+1)):
        g = 0
        distinct = set()
        for v in perm:
            g = math.gcd(g, v)
            distinct.add(g)
        f = len(distinct)
        if f > best:
            best = f
            cnt = 1
        elif f == best:
            cnt += 1
    assert ans == cnt % MOD


def test_dp_small(run, x):
    import math
