    full = (1 << n) - 1
    dp = [dict() for _ in range(1 << n)]
    for i in range(n):
        mask = 1 << i
        dp[mask][(i+1, 1)] = 1
    for mask in range(1 << n):
        for (g, d), ways in dp[mask].items():
            for i in range(n):
                if not (mask >> i) & 1:
                    xv = i+1
                    ng = math.gcd(g, xv)
                    nd = d + (1 if ng != g else 0)
                    nmask = mask | (1 << i)
                    dp[nmask][(ng, nd)] = dp[nmask].get((ng, nd), 0) + ways
    maxd = 0
