tests_src:
def test_output_is_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_output_in_range(run, x):
    out = run(x).strip()
    n = int(out)
    assert 1 <= n <= 10

def test_modulo_condition(run, x):
    k, r = map(int, x.strip().split())
    out = run(x).strip()
    n = int(out)
    assert (k * n) % 10 in (0, r)

def test_minimality(run, x):
    k, r = map(int, x.strip().split())
    out = run(x).strip()
    n = int(out)
    for i in range(1, n):
        assert (k * i) % 10 not in (0, r)

def test_direct_oracle(run, x):
    k, r = map(int, x.strip().split())
    out = run(x).strip()
    n = int(out)
    ans = None
    for i in range(1, 11):
        if (k * i) % 10 in (0, r):
            ans = i
            break
    assert n == ans

def test_specific_bug_k_mod_9_r_2(run, x):
    k, r = map(int, x.strip().split())
    if k % 10 == 9 and r == 2:
        out = run(x).strip()
        n = int(out)
        assert n == 8

def test_general_last_digit_9_mapping(run, x):
    k, r = map(int, x.strip().split())
    if k % 10 == 9:
        expected = {1:9, 2:8, 3:7, 4:6, 5:5, 6:4, 7:3, 8:2, 9:1}
        out = run(x).strip()
        n = int(out)
        assert n == expected[r]

def test_output_1_when_k_mod_10_equals_r(run, x):
    k, r = map(int, x.strip().split())
    if k % 10 == r:
        out = run(x).strip()
        n = int(out)
        assert n == 1

def test_output_10_only_if_no_smaller(run, x):
    k, r = map(int, x.strip().split())
    out = run(x).strip()
    n = int(out)
    if n == 10:
        for i in range(1, 10):
            assert (k * i) % 10 not in (0, r)

def test_depends_only_on_last_digit(run, x):
    k, r = map(int, x.strip().split())
    d = k % 10
    out = run(x).strip()
    n = int(out)
    ans = None
    for i in range(1, 11):
        if (d * i) % 10 in (0, r):
            ans = i
            break
    assert n == ans

