def test_output_in_range(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    out = run(x).strip()
    a = int(out)
    assert 1 <= a <= n

def test_output_not_m(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if n == 1:
        return
    out = run(x).strip()
    a = int(out)
    assert a != m

def test_output_adjacent(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if n == 1:
        return
    out = run(x).strip()
    a = int(out)
    valid = set()
    if m - 1 >= 1:
        valid.add(m - 1)
    if m + 1 <= n:
        valid.add(m + 1)
    assert a in valid

def test_left_better(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if m - 1 > n - m:
        out = run(x).strip()
        a = int(out)
        assert a == m - 1

def test_right_better(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if n - m > m - 1:
        out = run(x).strip()
        a = int(out)
        assert a == m + 1

def test_tie(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if m > 1 and m - 1 == n - m:
        out = run(x).strip()
        a = int(out)
        assert a == m - 1

def test_monotonic_left(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    out = run(x).strip()
    a = int(out)
    if a <= 1:
        return
    def win(a_val):
        if a_val == m:
            return 0
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    assert win(a) >= win(a - 1)

def test_monotonic_right(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    out = run(x).strip()
    a = int(out)
    if a >= n:
        return
    def win(a_val):
        if a_val == m:
            return 0
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    assert win(a) >= win(a + 1)

def test_positive_win(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    if n == 1:
        return
    out = run(x).strip()
    a = int(out)
    def win(a_val):
        if a_val == m:
            return 0
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    assert win(a) > 0

def test_correct_by_win(run, x):
    n_str, m_str = x.strip().split()
    n = int(n_str)
    m = int(m_str)
    out = run(x).strip()
    a = int(out)
    def win(a_val):
        if a_val == m:
            return 0
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    candidates = []
    if m - 1 >= 1:
        candidates.append(m - 1)
    if m + 1 <= n:
        candidates.append(m + 1)
    if not candidates:
        assert a == 1 and win(a) == 0
        return
    max_win = max(win(c) for c in candidates)
    assert win(a) == max_win
    if len(candidates) == 2 and win(candidates[0]) == win(candidates[1]):
        assert a == candidates[0]

