tests_src:
def test_bruteforce_small(run, x):
    n, k = map(int, x.strip().split())
    if n > 16:
        return
    max_xor = 0
    for mask in range(1 << n):
        cnt = bin(mask).count('1')
        if cnt > k:
            continue
        xor_val = 0
        for i in range(n):
            if mask & (1 << i):
                xor_val ^= (i + 1)
        if xor_val > max_xor:
            max_xor = xor_val
    out = run(x).strip()
    assert int(out) == max_xor

def test_output_integer(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_output_nonnegative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_lower_bound_single(run, x):
    n, k = map(int, x.strip().split())
    out = run(x).strip()
    val = int(out)
    assert val >= n

def test_upper_bound_bitmask(run, x):
    n, k = map(int, x.strip().split())
    bitlen = n.bit_length()
    upper = (1 << bitlen) - 1
    out = run(x).strip()
    val = int(out)
    assert val <= upper

def test_k1_equals_n(run, x):
    n, k = map(int, x.strip().split())
    if k == 1:
        out = run(x).strip()
        val = int(out)
        assert val == n

def test_k_ge2_odd(run, x):
    n, k = map(int, x.strip().split())
    if k >= 2:
        out = run(x).strip()
        val = int(out)
        assert val % 2 == 1

def test_k_ge_n_lower_bound_total_xor(run, x):
    n, k = map(int, x.strip().split())
    if k >= n:
        rem = n % 4
        if rem == 0:
            total_xor = n
        elif rem == 1:
            total_xor = 1
        elif rem == 2:
            total_xor = n + 1
        else:
            total_xor = 0
        out = run(x).strip()
        val = int(out)
        assert val >= total_xor

def test_bitlen_formula(run, x):
    n, k = map(int, x.strip().split())
    if k >= 2:
        expected = (1 << n.bit_length()) - 1
        out = run(x).strip()
        val = int(out)
        assert val == expected

def test_k_ge2_at_least_3(run, x):
    n, k = map(int, x.strip().split())
    if k >= 2:
        out = run(x).strip()
        val = int(out)
        assert val >= 3

