def test_output_format(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
    except:
        return
    s = lines[1]
    if len(s) != n:
        return
    if n % 2 != 0 or n < 2:
        return
    if any(c not in '0123456789?' for c in s):
        return
    if s.count('?') % 2 != 0:
        return
    out = run(x).strip()
    assert out in ("Monocarp", "Bicarp"), f"Invalid output: {repr(out)}"


def test_no_question_marks(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
    except:
        return
    s = lines[1]
    if len(s) != n:
        return
    if n % 2 != 0 or n < 2:
        return
    if any(c not in '0123456789?' for c in s):
        return
    if s.count('?') % 2 != 0:
        return
    if '?' in s:
        return
    m = n // 2
    sum_left = sum(int(ch) for ch in s[:m])
    sum_right = sum(int(ch) for ch in s[m:])
    out = run(x).strip()
    expected = "Bicarp" if sum_left == sum_right else "Monocarp"
    assert out == expected, f"Expected {expected}, got {out}"


def test_all_question_marks(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
    except:
        return
    s = lines[1]
    if len(s) != n:
        return
    if n % 2 != 0 or n < 2:
        return
    if any(c not in '0123456789?' for c in s):
        return
    if s.count('?') % 2 != 0:
        return
    if any(ch != '?' for ch in s):
        return
    out = run(x).strip()
    assert out == "Bicarp", f"Expected Bicarp for all '?', got {out}"


def test_one_question_mark_each(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
    except:
        return
    s = lines[1]
    if len(s) != n:
        return
    if n % 2 != 0 or n < 2:
        return
    if any(c not in '0123456789?' for c in s):
        return
    if s.count('?') % 2 != 0:
        return
    m = n // 2
    left = s[:m]
    right = s[m:]
    if left.count('?') != 1 or right.count('?') != 1:
        return
    s1 = sum(int(ch) for ch in left if ch != '?')
    s2 = sum(int(ch) for ch in right if ch != '?')
    out = run(x).strip()
    expected = "Bicarp" if s1 == s2 else "Monocarp"
    assert out == expected, f"Expected {expected}, got {out}"


def test_dp_small(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
    except:
        return
    s = lines[1]
    if len(s) != n:
        return
    if n % 2 != 0 or n < 2:
        return
    if any(c not in '0123456789?' for c in s):
        return
    if s.count('?') % 2 != 0:
        return
    if n > 8:
        return
    m = n // 2
    left = s[:m]
    right = s[m:]
    s1 = sum(int(c) for c in left if c != '?')
    s2 = sum(int(c) for c in right if c != '?')
    ql = left.count('?')
    qr = right.count('?')
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dp(diff, ql, qr, turn):
        if ql == 0 and qr == 0:
            return diff == 0
        if turn == 0:
            if ql > 0:
                for d in range(10):
                    if not dp(diff + d, ql-1, qr, 1):
                        return True
            if qr > 0:
                for d in range(10):
                    if not dp(diff - d, ql, qr-1, 1):
                        return True
            return False
        else:
            if ql > 0:
                for d in range(10):
                    if dp(diff + d, ql-1, qr, 0):
                        return True
            if qr > 0:
                for d in range(10):
                    if dp(diff - d, ql, qr-1, 0):
                        return True
            return False
    initial_diff = s1 - s2
    bicarp_wins = dp(initial_diff, ql, qr, 0)
    expected = "Bicarp" if bicarp_wins else "Monocarp"
    out = run(x).strip()
    assert out == expected, f"DP expects {expected}, got {out}"


def test_example_1(run, x):
    if x != "4\n0523\n":
        return
    out = run(x).strip()
    assert out == "Bicarp", f"Example 1 expects Bicarp, got {out}"


