def test_brute_force_kruskal_n_le_17(run, x):
    n = int(x.strip())
    if n > 17:
        return
    if n == 1:
        expected = 0
    else:
        edges = []
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                cost = (i + j) % (n + 1)
                edges.append((cost, i, j))
        edges.sort()
        parent = list(range(n + 1))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[ry] = rx
                return True
            return False
        total = 0
        cnt = 0
        for cost, i, j in edges:
            if union(i, j):
                total += cost
                cnt += 1
                if cnt == n - 1:
                    break
        expected = total
    out = run(x)
    ans = int(out.strip())
    assert ans == expected

