    for i in range(1, n):
        total += (i + (i + 1)) % (n + 1)
    assert ans <= total

def test_brute_force_prim_n_le_15(run, x):
    n = int(x.strip())
    if n > 15:
        return
    if n == 1:
        expected = 0
    else:
        INF = 10**9
        cost_mat = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                c = (i + j) % (n + 1)
                cost_mat[i][j] = c
                cost_mat[j][i] = c
        visited = [False] * (n + 1)
        min_edge = [INF] * (n + 1)
        min_edge[1] = 0
        total = 0
        for _ in range(n):
            v = -1
            for i in range(1, n + 1):
                if not visited[i] and (v == -1 or min_edge[i] < min_edge[v]):
                    v = i
            visited[v] = True
            total += min_edge[v]
            for to in range(1, n + 1):
                if not visited[to] and cost_mat[v][to] < min_edge[to]:
                    min_edge[to] = cost_mat[v][to]
        expected = total
    out = run(x)
    ans = int(out.strip())
    assert ans == expected

def test_lower_bound_zero(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

