def test_brute_force_small(run, x):
    import itertools
    N, K = map(int, x.strip().split())
    half = (N + 1) // 2
    if half > 6:
        return
    cnt = 1
    for _ in range(half):
        cnt *= K
        if cnt > 20000:
            return
    MOD = 10**9 + 7
    palindromes = []
    for tup in itertools.product(range(1, K+1), repeat=half):
        if N % 2 == 0:
            seq = list(tup) + list(reversed(tup))
        else:
            seq = list(tup[:-1]) + [tup[-1]] + list(reversed(tup[:-1]))
        palindromes.append(tuple(seq))
    seen = set()
    for seq in palindromes:
        for shift in range(N):
            rot = tuple(seq[(i+shift) % N] for i in range(N))
            seen.add(rot)
    expected = len(seen) % MOD
    ans = int(run(x).strip())
    assert ans == expected

def test_N1(run, x):
    N, K = map(int, x.strip().split())
    if N != 1:
        return
    MOD = 10**9 + 7
    expected = K % MOD
    ans = int(run(x).strip())
    assert ans == expected

def test_N2(run, x):
    N, K = map(int, x.strip().split())
    if N != 2:
        return
    MOD = 10**9 + 7
    expected = K % MOD
    ans = int(run(x).strip())
    assert ans == expected

def test_N3(run, x):
    N, K = map(int, x.strip().split())
    if N != 3:
        return
    MOD = 10**9 + 7
    expected = (3 * K * K - 2 * K) % MOD
    ans = int(run(x).strip())
    assert ans == expected

def test_N4(run, x):
    N, K = map(int, x.strip().split())
    if N != 4:
        return
    MOD = 10**9 + 7
    expected = (2 * K * K - K) % MOD
    ans = int(run(x).strip())
    assert ans == expected

def test_K1(run, x):
    N, K = map(int, x.strip().split())
    if K != 1:
        return
    ans = int(run(x).strip())
    assert ans == 1

def test_output_format(run, x):
    output = run(x)
    assert output.endswith('\n')
    s = output.strip()
    assert s.isdigit()
    lines = output.splitlines()
    assert len(lines) == 1
    assert lines[0] == s

def test_mod_range(run, x):
    MOD = 10**9 + 7
    ans = int(run(x).strip())
