def test_sample(run, x):
    if x.strip() == '4 2':
        ans = int(run(x).strip())
        assert ans == 6

def test_small_composites_brute(run, x):
    import itertools
    N, K = map(int, x.strip().split())
    composites = {4, 6, 8, 9, 10, 12}
    if N not in composites:
        return
    half = (N + 1) // 2
    if half > 6:
        return
    cnt = 1
    for _ in range(half):
        cnt *= K
        if cnt > 20000:
            return
    MOD = 10**9 + 7
    palindromes = []
    for tup in itertools.product(range(1, K+1), repeat=half):
        if N % 2 == 0:
            seq = list(tup) + list(reversed(tup))
        else:
            seq = list(tup[:-1]) + [tup[-1]] + list(reversed(tup[:-1]))
        palindromes.append(tuple(seq))
    seen = set()
    for seq in palindromes:
        for shift in range(N):
            rot = tuple(seq[(i+shift) % N] for i in range(N))
