def test_oracle(run, x):
    import sys
    def parse_input(x):
        lines = x.strip().split('\n')
        n = int(lines[0].strip())
        words = lines[1].strip().split()
        return n, words
    def correct_answer(n, words):
        original_len = sum(len(w) for w in words) + (n - 1)
        max_red = 0
        for i in range(n):
            for j in range(i, n):
                pattern = words[i:j+1]
                L = j - i + 1
                cnt = 0
                k = 0
                while k <= n - L:
                    if words[k:k+L] == pattern:
                        cnt += 1
                        k += L
                    else:
                        k += 1
                if cnt >= 2:
                    sum_len = sum(len(w) for w in pattern)
                    red = (sum_len - 1) * cnt
                    if red > max_red:
                        max_red = red
        return original_len - max_red
    n, words = parse_input(x)
    expected = correct_answer(n, words)
    out = run(x)
    assert int(out.strip()) == expected

