    mx = max(h)
    output = run(x).strip()
    val = int(output)
    assert val >= mx

def test_greedy_simulation(run, x):
    tokens = x.strip().split()
    if not tokens:
        return
    n = int(tokens[0])
    if len(tokens) < n + 1:
        return
    h = list(map(int, tokens[1:1+n]))
    arr = h[:]
    ops = 0
    while any(v > 0 for v in arr):
        i = 0
        while i < n:
            if arr[i] == 0:
                i += 1
            else:
                ops += 1
                j = i
                while j < n and arr[j] > 0:
                    j += 1
                for k in range(i, j):
                    arr[k] -= 1
                i = j
    output = run(x).strip()
    assert output == str(ops)

