def test_brute_force_small(run, x):
    A, B, C, K = map(int, x.strip().split())
    if A + B + C > 20:
        return
    best = -10**18
    for i in range(max(0, K - B - C), min(A, K) + 1):
        rem = K - i
        j_min = max(0, rem - C)
        j_max = min(B, rem)
        for j in range(j_min, j_max + 1):
            k = rem - j
            if k <= C:
                s = i - k
                if s > best:
                    best = s
    output = int(run(x).strip())
    assert output == best

def test_range(run, x):
    A, B, C, K = map(int, x.strip().split())
    output = int(run(x).strip())
    assert -K <= output <= K

def test_K_le_A(run, x):
    A, B, C, K = map(int, x.strip().split())
    if K <= A:
        output = int(run(x).strip())
        assert output == K

def test_A_lt_K_le_AplusB(run, x):
    A, B, C, K = map(int, x.strip().split())
    if A < K <= A + B:
        output = int(run(x).strip())
        assert output == A

def test_K_gt_AplusB(run, x):
    A, B, C, K = map(int, x.strip().split())
    if K > A + B:
        output = int(run(x).strip())
        expected = A - (K - A - B)
        assert output == expected

def test_achievable(run, x):
    A, B, C, K = map(int, x.strip().split())
    S = int(run(x).strip())
    lower = max(0, (K - S - B + 1) // 2, -S)
    upper = min(C, A - S, (K - S) // 2)
    assert lower <= upper

def test_C_zero(run, x):
    A, B, C, K = map(int, x.strip().split())
    if C == 0:
        output = int(run(x).strip())
        assert output == min(A, K)

def test_A_zero(run, x):
    A, B, C, K = map(int, x.strip().split())
    if A == 0:
        output = int(run(x).strip())
        expected = -max(0, K - B)
        assert output == expected

def test_B_zero(run, x):
    A, B, C, K = map(int, x.strip().split())
    if B == 0:
        output = int(run(x).strip())
        expected = min(A, K) - max(0, K - A)
        assert output == expected

def test_special_case_C_ge1_K_eq_AplusBplus1(run, x):
    A, B, C, K = map(int, x.strip().split())
    if C >= 1 and K == A + B + 1:
        output = int(run(x).strip())
        assert output == A - 1

