def test_output_integer(run, x):
    out = run(x)
    s = out.strip()
    try:
        int(s)
    except ValueError:
        assert False

def test_output_range(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    assert -K <= val <= K

def test_output_upper_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    assert val <= min(K, A)

def test_output_lower_bound(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    assert val >= -min(K, C)

def test_K_le_A(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if K <= A:
        out = run(x)
        val = int(out.strip())
        assert val == K

def test_K_between_A_and_A_plus_B(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if A < K <= A + B:
        out = run(x)
        val = int(out.strip())
        assert val == A

def test_K_gt_A_plus_B(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    if K > A + B:
        out = run(x)
        val = int(out.strip())
        expected = A - (K - A - B)
        assert val == expected

def test_min_max_formula(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    val = int(out.strip())
    correct = min(K, A) - max(0, K - A - B)
    assert val == correct

def test_bruteforce_small(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    total = A + B + C
    if total > 20:
        return
    out = run(x)
    val = int(out.strip())
    best = -10**18
    for a in range(0, min(A, K) + 1):
        max_b = min(B, K - a)
        for b in range(0, max_b + 1):
            c = K - a - b
            if c <= C:
                s = a - c
                if s > best:
                    best = s
    assert val == best

def test_achievable(run, x):
    parts = x.strip().split()
    if len(parts) < 4:
        return
    A, B, C, K = map(int, parts[:4])
    if not (A >= 0 and B >= 0 and C >= 0 and 1 <= K <= A + B + C):
        return
    out = run(x)
    S = int(out.strip())
    a_low = max(S, 0)
    a_high = min(A, K, S + C)
    left = K + S - B
    right = K + S
    a_min = max(a_low, (left + 1) // 2 if left % 2 else left // 2)
    a_max = min(a_high, right // 2)
    assert a_min <= a_max

