    output = run(x).strip()
    lines = x.strip().splitlines()
    n, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
        if t <= T:
            valid_costs.append(c)
    if len(valid_costs) == 1:
        expected = str(valid_costs[0])
        assert output == expected, f'Single valid route cost {valid_costs[0]}, got {output}'

def test_multiple_min_cost(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    n, T = map(int, lines[0].split())
    valid_costs = []
    for i in range(1, n+1):
        c, t = map(int, lines[i].split())
