tests_src:
def test_output_is_integer(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()

def test_output_in_range(run, x):
    out = run(x)
    c = int(out.strip())
    assert 0 <= c <= 5

def test_output_zero_for_small_n(run, x):
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    if N < 105:
        assert c == 0

def test_output_five_for_large_n(run, x):
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    if N >= 195:
        assert c == 5

def test_output_one_for_105(run, x):
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    if N == 105:
        assert c == 1

def test_output_two_for_135(run, x):
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    if N == 135:
        assert c == 2

def test_output_three_for_165(run, x):
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    if N == 165:
        assert c == 3

def test_output_four_for_189(run, x):
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    if N == 189:
        assert c == 4

def test_consistency_with_candidates(run, x):
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    candidates = [105, 135, 165, 189, 195]
    true_count = sum(1 for v in candidates if v <= N)
    assert c == true_count

def test_brute_force(run, x):
    import math
    out = run(x)
    c = int(out.strip())
    N = int(x.strip())
    count = 0
    for num in range(1, N+1, 2):
        divs = 0
        limit = math.isqrt(num)
        for d in range(1, limit+1):
            if num % d == 0:
                divs += 1
                if d != num // d:
                    divs += 1
        if divs == 8:
            count += 1
    assert c == count

