def test_direct_oracle(run, x):
    s = x.strip().split()
    if len(s) < 2:
        return
    a, b = map(int, s[:2])
    d = b - a
    i = d - 1
    if not (1 <= i <= 998):
        return
    T_i = i * (i + 1) // 2
    T_next = (i + 1) * (i + 2) // 2
    x_correct = T_i - a
    if x_correct < 1 or T_next - b != x_correct:
        return
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    assert out == x_correct

def test_brute_force_oracle(run, x):
    s = x.strip().split()
    if len(s) < 2:
        return
    a, b = map(int, s[:2])
    found = None
    for i in range(1, 999):
        T_i = i * (i + 1) // 2
        T_next = (i + 1) * (i + 2) // 2
        x_val = T_i - a
        if x_val < 1:
            continue
        if T_next - b == x_val:
            found = x_val
            break
    if found is None:
        return
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    assert out == found

def test_a_plus_out_triangular(run, x):
    s = x.strip().split()
    if len(s) < 2:
        return
    a, b = map(int, s[:2])
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    N = a + out
    import math
    disc = 8 * N + 1
    root = math.isqrt(disc)
    if root * root != disc:
        assert False
    n = (root - 1) // 2
    if n * (n + 1) // 2 != N:
        assert False

def test_b_plus_out_triangular(run, x):
    s = x.strip().split()
    if len(s) < 2:
        return
    a, b = map(int, s[:2])
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    N = b + out
    import math
    disc = 8 * N + 1
    root = math.isqrt(disc)
    if root * root != disc:
        assert False
    n = (root - 1) // 2
    if n * (n + 1) // 2 != N:
        assert False

def test_consecutive_triangular_and_positive(run, x):
    s = x.strip().split()
    if len(s) < 2:
        return
    a, b = map(int, s[:2])
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    if out < 1:
        assert False
    N1 = a + out
    N2 = b + out
    import math
    disc1 = 8 * N1 + 1
    root1 = math.isqrt(disc1)
    if root1 * root1 != disc1:
        assert False
    n1 = (root1 - 1) // 2
    if n1 * (n1 + 1) // 2 != N1:
        assert False
    if (n1 + 1) * (n1 + 2) // 2 != N2:
        assert False

def test_output_integer(run, x):
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False

def test_output_positive(run, x):
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    if out < 1:
        assert False

def test_output_upper_bound(run, x):
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    if out > 499499:
        assert False

def test_index_consistency(run, x):
    s = x.strip().split()
    if len(s) < 2:
        return
    a, b = map(int, s[:2])
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    N1 = a + out
    import math
    disc = 8 * N1 + 1
    root = math.isqrt(disc)
    if root * root != disc:
        assert False
    n = (root - 1) // 2
    if n * (n + 1) // 2 != N1:
        assert False
    if b - a != n + 1:
        assert False

def test_sample(run, x):
    if x.strip() != "8 13":
        return
    out_str = run(x).strip()
    try:
        out = int(out_str)
    except ValueError:
        assert False
    if out != 2:
        assert False

