def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, "Output is not an integer"

def test_range(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    assert 1 <= j <= N, f"j={j} not in [1, {N}]"

def test_sum(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    assert i + j == N + 1, f"i+j={i+j} != N+1={N+1}"

def test_front(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    if i == 1:
        assert j == N, f"When i=1, expected j={N}, got {j}"

def test_back(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    if i == N:
        assert j == 1, f"When i=N, expected j=1, got {j}"

def test_enumeration(run, x):
    N, i = map(int, x.strip().split())
    cars = list(range(1, N+1))
    target = cars[i-1]
    j_correct = None
    for j_back, car in enumerate(reversed(cars), start=1):
        if car == target:
            j_correct = j_back
            break
    out = run(x)
    j = int(out.strip())
    assert j == j_correct, f"Expected j={j_correct}, got {j}"

def test_sample(run, x):
    out = run(x)
    if x == "4 2\n":
        assert out.strip() == "3", f"For sample input, expected 3, got {out.strip()}"

def test_middle(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    j = int(out.strip())
    if N % 2 == 1 and i == (N+1)//2:
        assert j == i, f"For middle car, expected j={i}, got {j}"

def test_minimal(run, x):
    N, i = map(int, x.strip().split())
    out = run(x)
    if N == 1 and i == 1:
        j = int(out.strip())
        assert j == 1, f"For N=1,i=1, expected 1, got {j}"

def test_output_numeric(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit(), f"Output must be digits only, got '{s}'"
    if s != '0' and len(s) > 1:
        assert s[0] != '0', f"No leading zeros allowed, got '{s}'"

