def test_geometric_sum_shape(run, x):
    out = run(x)
    ans = int(out.strip())
    found = False
    m = 1
    while (2**m - 1) <= ans:
        if ans % (2**m - 1) == 0:
            k = ans // (2**m - 1)
            if k >= 1:
                found = True
                break
        m += 1
    assert found, f"Answer {ans} is not of the form k*(2^m -1)"

def test_achievable(run, x):
    lines = x.strip().splitlines()
    a = list(map(int, lines[1].split()))
    from collections import Counter
    counts = list(Counter(a).values())
    out = run(x)
    ans = int(out.strip())
    candidates = []
    m = 1
    while (2**m - 1) <= ans:
        if ans % (2**m - 1) == 0:
            k = ans // (2**m - 1)
            if k >= 1:
                candidates.append((k, m))
        m += 1
    def can_assign(sizes, counts):
        sizes_sorted = sorted(sizes, reverse=True)
        counts_sorted = sorted(counts, reverse=True)
        used = [False] * len(counts_sorted)
        def backtrack(idx):
            if idx == len(sizes_sorted):
                return True
            for i in range(len(counts_sorted)):
                if not used[i] and counts_sorted[i] >= sizes_sorted[idx]:
                    used[i] = True
                    if backtrack(idx+1):
                        return True
                    used[i] = False
            return False
        return backtrack(0)
    found = False
    for k, m in candidates:
        sizes = [k * (2**i) for i in range(m)]
        if can_assign(sizes, counts):
            found = True
            break
    assert found, f"Answer {ans} is not achievable with any geometric sequence"

def test_optimal(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    from collections import Counter
    counts = list(Counter(a).values())
    out = run(x)
    ans = int(out.strip())
    def can_assign(sizes, counts):
        sizes_sorted = sorted(sizes, reverse=True)
        counts_sorted = sorted(counts, reverse=True)
        used = [False] * len(counts_sorted)
        def backtrack(idx):
            if idx == len(sizes_sorted):
                return True
            for i in range(len(counts_sorted)):
                if not used[i] and counts_sorted[i] >= sizes_sorted[idx]:
                    used[i] = True
                    if backtrack(idx+1):
                        return True
                    used[i] = False
            return False
        return backtrack(0)
    best = 0
    for k in range(1, n+1):
        seq = []
        total = 0
        mult = 1
        while True:
            sz = k * mult
            if total + sz > n:
                break
            seq.append(sz)
            total += sz
            if can_assign(seq, counts):
                best = max(best, total)
            mult *= 2
    assert ans == best, f"Optimal answer is {best}, got {ans}"

