tests_src:
def test_brute_force(run, x):
    a,b,c = map(int, x.strip().split())
    possible = any((a * k) % b == c for k in range(1, b + 1))
    expected = 'YES' if possible else 'NO'
    assert run(x).strip() == expected

def test_gcd_condition(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    d = math.gcd(a, b)
    expected = 'YES' if c % d == 0 else 'NO'
    assert run(x).strip() == expected

def test_c_zero_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    if c == 0:
        assert run(x).strip() == 'YES'

def test_gcd_one_always_yes(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    if math.gcd(a, b) == 1:
        assert run(x).strip() == 'YES'

def test_b_one_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    if b == 1:
        assert run(x).strip() == 'YES'

def test_a_multiple_b(run, x):
    a,b,c = map(int, x.strip().split())
    if a % b == 0:
        expected = 'YES' if c == 0 else 'NO'
        assert run(x).strip() == expected

def test_output_format(run, x):
    output = run(x).strip()
    assert output in ('YES', 'NO')

def test_necessary_condition(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    output = run(x).strip()
    if output == 'YES':
        d = math.gcd(a, b)
        assert c % d == 0

def test_sufficient_condition(run, x):
    import math
    a,b,c = map(int, x.strip().split())
    d = math.gcd(a, b)
    if c % d == 0:
        assert run(x).strip() == 'YES'

def test_a_one_always_yes(run, x):
    a,b,c = map(int, x.strip().split())
    if a == 1:
        assert run(x).strip() == 'YES'

def test_output_is_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False

def test_output_positive(run, x):
    ans = int(run(x).strip())
    assert ans > 0

def test_form(run, x):
    r, h = map(int, x.strip().split())
    q = h // r
    ans = int(run(x).strip())
    t = ans - 2 * q
    assert t in {1, 2, 3}

def test_small_remainder(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 2 * d < r:
        assert ans == 2 * q + 1

def test_medium_remainder(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 2 * d >= r and 4 * d * d < 3 * r * r:
        assert ans == 2 * q + 2

def test_large_remainder(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 4 * d * d >= 3 * r * r:
        assert ans == 2 * q + 3

def test_full_oracle(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    d = h % r
    if 2 * d < r:
        expected = 2 * q + 1
    elif 4 * d * d < 3 * r * r:
        expected = 2 * q + 2
    else:
        expected = 2 * q + 3
    assert ans == expected

def test_lower_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    assert ans >= 2 * q + 1

def test_upper_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    r, h = map(int, x.strip().split())
    q = h // r
    assert ans <= 2 * q + 3

def test_examples(run, x):
    out = run(x)
    inp = x.strip()
    if inp == "1 1":
        assert out == "3\n"
    elif inp == "1 2":
        assert out == "5\n"
    elif inp == "2 1":
        assert out == "2\n"

