tests_src:
def test_output_is_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, 'Output must be an integer'

def test_output_positive(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 1, 'At least one balloon must fit'

def test_output_in_range(run, x):
    r_val, h_val = map(int, x.strip().split())
    n = h_val // r_val
    out = run(x)
    ans = int(out.strip())
    assert 2 * n + 1 <= ans <= 2 * n + 3, f'Answer must be in [{2*n+1}, {2*n+3}]'

def test_examples_from_statement(run, x):
    out = run(x)
    if x == '1 1\n':
        assert out.strip() == '3', 'Example 1 1 -> 3'
    elif x == '1 2\n':
        assert out.strip() == '5', 'Example 1 2 -> 5'
    elif x == '2 1\n':
        assert out.strip() == '2', 'Example 2 1 -> 2'

def test_specific_case_r2_h4(run, x):
    if x == '2 4\n':
        out = run(x)
        assert out.strip() == '5', 'For r=2, h=4 the correct answer is 5'

def test_when_h_multiple_of_r(run, x):
    r_val, h_val = map(int, x.strip().split())
    if h_val % r_val == 0:
        out = run(x)
        ans = int(out.strip())
        n = h_val // r_val
        assert ans == 2 * n + 1, f'When h is a multiple of r, answer must be {2*n+1}'

def test_small_remainder(run, x):
    r_val, h_val = map(int, x.strip().split())
    n = h_val // r_val
    d = h_val % r_val
    if 2 * d < r_val:
        out = run(x)
        ans = int(out.strip())
        assert ans == 2 * n + 1, f'When 2*d < r, answer must be {2*n+1}'

def test_medium_remainder(run, x):
    r_val, h_val = map(int, x.strip().split())
    n = h_val // r_val
    d = h_val % r_val
    if 2 * d >= r_val and 4 * d * d < 3 * r_val * r_val:
        out = run(x)
        ans = int(out.strip())
        assert ans == 2 * n + 2, f'When r/2 <= d < sqrt(3)/2*r, answer must be {2*n+2}'

def test_large_remainder(run, x):
    r_val, h_val = map(int, x.strip().split())
    n = h_val // r_val
    d = h_val % r_val
    if 4 * d * d >= 3 * r_val * r_val:
        out = run(x)
        ans = int(out.strip())
        assert ans == 2 * n + 3, f'When d >= sqrt(3)/2*r, answer must be {2*n+3}'

def test_full_formula_oracle(run, x):
    r_val, h_val = map(int, x.strip().split())
    n = h_val // r_val
    d = h_val % r_val
    if 2 * d < r_val:
        correct = 2 * n + 1
    elif 4 * d * d >= 3 * r_val * r_val:
        correct = 2 * n + 3
    else:
        correct = 2 * n + 2
    out = run(x)
    ans = int(out.strip())
    assert ans == correct, f'Expected {correct}, got {ans}'

