def test_correct_bruteforce(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    try:
        n = int(lines[0].strip())
    except:
        return
    if not (1 <= n <= 15):
        return
    angles = []
    if len(lines) < n+1:
        return
    for i in range(1, n+1):
        try:
            a = int(lines[i].strip())
        except:
            return
        if not (1 <= a <= 180):
            return
        angles.append(a)
    total = sum(angles)
    found = False
    for mask in range(1 << n):
        s = 0
        for i in range(n):
            if mask & (1 << i):
                s += angles[i]
        if (2 * s - total) % 360 == 0:
