def test_output_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False

def test_answer_nonnegative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

def test_answer_at_most_n(run, x):
    lines = x.strip().split()
    if len(lines) < 1:
        return
    n = int(lines[0])
    out = run(x)
    ans = int(out.strip())
    assert ans <= n

def test_answer_at_most_nonzero_count(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    a = list(map(int, tokens[1:]))
    nonzero = sum(1 for v in a if v != 0)
    out = run(x)
    ans = int(out.strip())
    assert ans <= nonzero

def test_answer_at_least_distinct_nonzero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    a = list(map(int, tokens[1:]))
    distinct_nonzero = len(set(v for v in a if v != 0))
    out = run(x)
    ans = int(out.strip())
    assert ans >= distinct_nonzero

def test_answer_equal_distinct_nonzero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    a = list(map(int, tokens[1:]))
    distinct_nonzero = len(set(v for v in a if v != 0))
    out = run(x)
    ans = int(out.strip())
    assert ans == distinct_nonzero

def test_brute_force_small(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    n = int(tokens[0])
    if n > 6:
        return
    a = list(map(int, tokens[1:]))
    from collections import deque
    start = tuple(a)
    target = tuple([0]*n)
    if start == target:
        expected = 0
    else:
        q = deque([(start, 0)])
        visited = {start}
        found = False
        while q:
            state, dist = q.popleft()
            nonzero_vals = {v for v in state if v != 0}
            for d in [-v for v in nonzero_vals]:
                new_state = tuple(0 if v==0 else v+d for v in state)
                if new_state == target:
                    expected = dist + 1
                    found = True
                    break
                if new_state not in visited:
                    visited.add(new_state)
                    q.append((new_state, dist+1))
            if found:
                break
        if not found:
            expected = len(nonzero_vals)
    out = run(x)
    ans = int(out.strip())
    assert ans == expected

def test_all_zero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    a = list(map(int, tokens[1:]))
    if all(v == 0 for v in a):
        out = run(x)
        ans = int(out.strip())
        assert ans == 0

def test_single_element_zero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 2:
        return
    n = int(tokens[0])
    if n != 1:
        return
    a = list(map(int, tokens[1:]))
    if a[0] == 0:
        out = run(x)
        ans = int(out.strip())
        assert ans == 0

def test_two_equal_nonzero(run, x):
    tokens = x.strip().split()
    if len(tokens) < 3:
        return
    n = int(tokens[0])
    if n != 2:
        return
    a = list(map(int, tokens[1:]))
    if a[0] == a[1] and a[0] != 0:
        out = run(x)
        ans = int(out.strip())
        assert ans == 1

