def test_examples(run, x):
    examples = {"5\n1 1 1 1 1\n": 1,
                "3\n2 0 -1\n": 2,
                "4\n5 -6 -5 1\n": 4}
    if x in examples:
        out = run(x)
        try:
            val = int(out.strip())
        except ValueError:
            assert False, "Output not an integer"
        expected = examples[x]
        assert val == expected, f"Example expects {expected}, got {val}"

def test_nonnegative_integer(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    assert val >= 0, f"Output negative: {val}"

def test_output_le_nonzero_count(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        arr = list(map(int, lines[1].split()))
    else:
        arr = []
    nonzero_count = sum(1 for v in arr if v != 0)
    assert val <= nonzero_count, f"Output {val} > nonzero count {nonzero_count}"

def test_output_ge_distinct_nonzero(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        arr = list(map(int, lines[1].split()))
    else:
        arr = []
    distinct_nonzero = len({v for v in arr if v != 0})
    assert val >= distinct_nonzero, f"Output {val} < distinct nonzero count {distinct_nonzero}"

def test_all_zero_output_zero(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        arr = list(map(int, lines[1].split()))
    else:
        arr = []
    if all(v == 0 for v in arr):
        assert val == 0, f"All zero but output {val}"

def test_all_nonzero_equal_output_one(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        arr = list(map(int, lines[1].split()))
    else:
        arr = []
    nonzero = [v for v in arr if v != 0]
    if nonzero and all(v == nonzero[0] for v in nonzero):
        assert val == 1, f"All non-zero equal but output {val}"

def test_output_ge1_if_nonzero(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        arr = list(map(int, lines[1].split()))
    else:
        arr = []
    if any(v != 0 for v in arr):
        assert val >= 1, f"Has non-zero but output {val}"

def test_direct_oracle(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        arr = list(map(int, lines[1].split()))
    else:
        arr = []
    distinct_nonzero = len({v for v in arr if v != 0})
    assert val == distinct_nonzero, f"Expected {distinct_nonzero}, got {val}"

def test_bruteforce_oracle(run, x):
    out = run(x)
    try:
        val = int(out.strip())
    except ValueError:
        assert False, "Output not an integer"
    lines = x.strip().splitlines()
    if len(lines) >= 2:
        arr = list(map(int, lines[1].split()))
    else:
        arr = []
    from collections import deque
    start = tuple(sorted(v for v in arr if v != 0))
    if not start:
        expected = 0
    else:
        distinct_start = len(set(start))
        if distinct_start > 5:
            # skip large instances to keep test fast
            return
        visited = {start: 0}
        q = deque([start])
        expected = None
        while q:
            state = q.popleft()
            steps = visited[state]
            distinct_vals = set(state)
            for v in distinct_vals:
                d = -v
                new_nonzero = []
                for x_val in state:
                    if x_val != 0:
                        new_x = x_val + d
                        if new_x != 0:
                            new_nonzero.append(new_x)
                new_state = tuple(sorted(new_nonzero))
                if new_state not in visited:
                    visited[new_state] = steps + 1
                    if not new_state:
                        expected = steps + 1
                        break
                    q.append(new_state)
            if expected is not None:
                break
        if expected is None:
            # fallback (should not happen for small instances)
            expected = distinct_start
    assert val == expected, f"Brute-force expects {expected}, got {val}"

def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped, "Output is empty or only whitespace"
    try:
        int(stripped)
    except ValueError:
        assert False, "Output is not a valid integer"

