def test_brute_force_small(run, x):
    t, a, b = map(int, x.strip().split())
    if t == 1 or a > 15:
        return
    max_deg = 0
    pow_t = 1
    while pow_t <= a:
        max_deg += 1
        pow_t *= t
    max_deg -= 1
    coeffs = [0] * (max_deg + 1)
    count = 0
    def recurse(idx, rem_a, pow_t_idx):
        if idx == max_deg:
            if rem_a % pow_t_idx == 0:
                c = rem_a // pow_t_idx
                coeffs[idx] = c
                p_a = 0
                pow_a = 1
                for i in range(max_deg + 1):
                    p_a += coeffs[i] * pow_a
                    pow_a *= a
                if p_a == b:
                    nonlocal count
                    count += 1
            return
        max_c = rem_a // pow_t_idx
        for c in range(max_c + 1):
            coeffs[idx] = c
            recurse(idx + 1, rem_a - c * pow_t_idx, pow_t_idx * t)
    recurse(0, a, 1)
    correct = str(count)
    out = run(x).strip()
    assert out == correct, f"For input {x.strip()}, expected {correct}, got {out}"

