tests_src:
def test_valid_output(run, x):
    out = run(x).strip()
    assert out in ("automaton", "array", "both", "need tree")

def test_array_if_anagram(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    if sorted(s) == sorted(t):
        out = run(x).strip()
        assert out == "array"

def test_automaton_if_subsequence_and_not_anagram(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and a[i] == ch:
                i += 1
        return i == len(a)
    if is_subseq(t, s) and sorted(s) != sorted(t):
        out = run(x).strip()
        assert out == "automaton"

def test_both_if_subset_and_not_subsequence_and_not_anagram(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    from collections import Counter
    cnt_s = Counter(s)
    cnt_t = Counter(t)
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and a[i] == ch:
                i += 1
        return i == len(a)
    if all(cnt_s[c] >= cnt_t[c] for c in cnt_t) and sorted(s) != sorted(t) and not is_subseq(t, s):
        out = run(x).strip()
        assert out == "both"

def test_need_tree_if_not_subset(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    from collections import Counter
    cnt_s = Counter(s)
    cnt_t = Counter(t)
    if any(cnt_s[c] < cnt_t[c] for c in cnt_t):
        out = run(x).strip()
        assert out == "need tree"

def test_automaton_implies_subsequence(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    out = run(x).strip()
    if out == "automaton":
        i = 0
        for ch in s:
            if i < len(t) and t[i] == ch:
                i += 1
        assert i == len(t)

def test_array_implies_anagram(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    out = run(x).strip()
    if out == "array":
        assert sorted(s) == sorted(t)

def test_both_implies_subset_and_not_subsequence(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    out = run(x).strip()
    if out == "both":
        from collections import Counter
        cnt_s = Counter(s)
        cnt_t = Counter(t)
        assert all(cnt_s[c] >= cnt_t[c] for c in cnt_t)
        i = 0
        for ch in s:
            if i < len(t) and t[i] == ch:
                i += 1
        assert i != len(t)
        assert sorted(s) != sorted(t)

def test_need_tree_implies_not_subset(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    out = run(x).strip()
    if out == "need tree":
        from collections import Counter
        cnt_s = Counter(s)
        cnt_t = Counter(t)
        assert any(cnt_s[c] < cnt_t[c] for c in cnt_t)

def test_oracle(run, x):
    s, t = x.splitlines()
    if s == t:
        return
    from collections import Counter
    def is_subseq(a, b):
        i = 0
        for ch in b:
            if i < len(a) and a[i] == ch:
                i += 1
        return i == len(a)
    cnt_s = Counter(s)
    cnt_t = Counter(t)
    if Counter(s) == Counter(t):
        expected = "array"
    elif is_subseq(t, s):
        expected = "automaton"
    elif all(cnt_s[c] >= cnt_t[c] for c in cnt_t):
        expected = "both"
    else:
        expected = "need tree"
    out = run(x).strip()
    assert out == expected

