def test_small_inputs_brute_force(run, x):
    import math
    parts = x.strip().split()
    if len(parts) != 2:
        return
    a_str, b_str = parts
    try:
        a = int(a_str)
        b = int(b_str)
    except:
        return
    if not (1 <= a <= b <= 10**100):
        return
    if b - a <= 1000:
        d = 0
        for i in range(a, b + 1):
            d = math.gcd(d, i)
            if d == 1:
                break
        out = run(x).strip()
