def test_output_divides_consecutive(run, x):
    parts = x.strip().split()
    if len(parts) != 2:
        return
    a_str, b_str = parts
    try:
        a = int(a_str)
        b = int(b_str)
    except:
        return
    if not (1 <= a <= b <= 10**100):
        return
    out = run(x).strip()
    if not out.isdigit():
        assert False
    out_int = int(out)
    assert out_int >= 1
    assert a % out_int == 0
    assert b % out_int == 0
    if a < b:
        assert (a + 1) % out_int == 0

