def test_simulation(run, x):
    a, b = map(int, x.split())
    # Direct simulation as per specification
    candles = a
    used = 0
    hours = 0
    while candles > 0:
        candles -= 1
        hours += 1
        used += 1
        if used >= b:
            candles += 1
            used -= b
    out = run(x)
    assert int(out.strip()) == hours


