def test_oracle(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    n = y + 1
    while True:
        s = str(n)
        if len(set(s)) == len(s):
            correct = s
            break
        n += 1
    assert output == correct

def test_strictly_greater(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    assert output.isdigit()
    out_val = int(output)
    assert out_val > y

def test_distinct_four_digit(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    assert output.isdigit()
    assert len(output) == 4
    assert output[0] != '0'
    assert len(set(output)) == 4

def test_minimal(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    assert output.isdigit()
    out_val = int(output)
    for n in range(y+1, out_val):
        s = str(n)
        if len(set(s)) == len(s):
            assert False

def test_valid_integer(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    assert output.isdigit()
    if output != "0":
        assert output[0] != '0'
    assert str(int(output)) == output

def test_next_if_distinct(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    if len(set(str(y+1))) == len(str(y+1)):
        assert output == str(y+1)

def test_lower_bound(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    if y <= 1022:
        assert output.isdigit()
        out_val = int(output)
        assert out_val >= 1023

def test_upper_bound(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    assert output.isdigit()
    out_val = int(output)
    assert out_val <= 9876

def test_examples(run, x):
    inp = x.strip()
    output = run(x).strip()
    if inp == "1987":
        assert output == "2013"
    elif inp == "2013":
        assert output == "2014"
    elif inp == "1000":
        assert output == "1023"

def test_oracle_precomputed(run, x):
    y = int(x.strip())
    output = run(x).strip()
    if not (1000 <= y <= 9000):
        return
    distinct_four = []
    for n in range(1000, 10000):
        s = str(n)
        if len(set(s)) == 4 and s[0] != '0':
            distinct_four.append(n)
    correct = None
    for n in distinct_four:
        if n > y:
            correct = str(n)
            break
    assert output == correct

