def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False

def test_positive(run, x):
    out = run(x)
    v = int(out.strip())
    assert v > 0

def test_example1(run, x):
    if x.strip() != '1':
        return
    out = run(x)
    assert int(out.strip()) == 1

def test_example2(run, x):
    if x.strip() != '2':
        return
    out = run(x)
    assert int(out.strip()) == 3

def test_example3(run, x):
    if x.strip() != '3':
        return
    out = run(x)
    assert int(out.strip()) == 7

def test_sum_formula(run, x):
    n = int(x.strip())
    expected = sum(i * (n - i) + 1 for i in range(1, n + 1))
    out = run(x)
    assert int(out.strip()) == expected

def test_monotonic(run, x):
    n = int(x.strip())
    if n <= 1:
        return
    prev = ((n - 1) ** 3 + 5 * (n - 1)) // 6
    out = run(x)
    assert int(out.strip()) > prev

def test_lower_bound(run, x):
    n = int(x.strip())
    out = run(x)
    assert int(out.strip()) >= n

def test_large_n_2000(run, x):
    if x.strip() != '2000':
        return
    out = run(x)
    assert int(out.strip()) == 1333335000

def test_brute_force_small_n(run, x):
    n = int(x.strip())
    if n > 8:
        return
    import functools
    buttons = list(range(1, n + 1))
    @functools.lru_cache(None)
    def cost(pressed_tuple, eliminated_frozenset):
        k = len(pressed_tuple)
        if k == n:
            return 0
        candidates = [b for b in buttons if b not in pressed_tuple and b not in eliminated_frozenset]
        best = float('inf')
        for b in candidates:
            new_pressed = pressed_tuple + (b,)
            cost_correct = 1 + cost(new_pressed, frozenset())
            if len(candidates) > 1:
                new_eliminated = eliminated_frozenset | {b}
                cost_wrong = 1 + k + cost(pressed_tuple, new_eliminated)
                worst = max(cost_correct, cost_wrong)
            else:
                worst = cost_correct
            if worst < best:
                best = worst
        return best
    expected = cost((), frozenset())
    out = run(x)
    assert int(out.strip()) == expected

