    n, s = parsed
    import re
    assert not re.search(r'\s', output), f'Output contains whitespace: {output}'

def test_parse(run, x):
    out = run(x)
    s = out.strip()
    try:
        float(s)
    except ValueError:
        assert False

def test_positive(run, x):
    d = float(run(x).strip())
    assert d > 0

def test_format(run, x):
    out = run(x)
    lines = out.strip().splitlines()
    assert len(lines) == 1
    s = lines[0].strip()
    assert s != ''
    # no internal whitespace
    assert not any(c.isspace() for c in s)
    # must parse as float (already covered by test_parse, but keep for clarity)
    try:
        float(s)
    except ValueError:
        assert False

def test_not_inf_nan(run, x):
    import math
    d = float(run(x).strip())
    assert not math.isinf(d) and not math.isnan(d)

def test_not_too_large(run, x):
    d = float(run(x).strip())
    assert d < 1e13

def test_direct_comparison(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    true_d = (l * l - h * h) / (2.0 * h)
    diff = abs(d - true_d)
    denom = max(1.0, abs(true_d))
    if diff / denom > 1e-6:
        assert False

def test_equation(run, x):
    h, l = map(int, x.strip().split())
    d = float(run(x).strip())
    residual = 2 * h * d + h * h - l * l
    tol = 1e-6 * max(1.0, 2 * h * d)
    if abs(residual) > tol:
        assert False

def test_examples(run, x):
    if x == "1 2\n":
        expected = 1.5
    elif x == "3 5\n":
        expected = 2.6666666666667
    else:
        return
    d = float(run(x).strip())
    diff = abs(d - expected)
    denom = max(1.0, abs(expected))
    if diff / denom > 1e-6:
        assert False

def test_exact_small(run, x):
    h, l = map(int, x.strip().split())
    if h * l > 10000:
        return
    from fractions import Fraction
    d = float(run(x).strip())
    exact = Fraction(l * l - h * h, 2 * h)
    exact_float = float(exact)
    diff = abs(d - exact_float)
    denom = max(1.0, abs(exact_float))
    if diff / denom > 1e-6:
        assert False

def test_depth_gt_one_minus_epsilon(run, x):
    d = float(run(x).strip())
    assert d > 1 - 1e-6

