def test_correct_expectation(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    ranges = []
    for i in range(1, n + 1):
        L, R = map(int, lines[i].split())
        ranges.append((L, R))
    total = 0.0
    for v in range(1, 10001):
        probs = []
        for L, R in ranges:
            size = R - L + 1
            if size == 0:
                p = 0.0
            else:
                num = max(R - v + 1, 0)
                p = num / size
                if p > 1:
                    p = 1.0
            probs.append(p)
        v0 = 1.0
        for p in probs:
            v0 *= (1.0 - p)
        v1 = 0.0
        for i in range(len(probs)):
            term = probs[i]
            for j in range(len(probs)):
                if j != i:
                    term *= (1.0 - probs[j])
            v1 += term
        prob = 1.0 - v0 - v1
        total += prob
    expected = total
    out = run(x)
    try:
        ans = float(out)
    except:
        assert False, "Output not a valid float"
    if not (abs(ans - expected) <= 1e-9 + 1e-9 * abs(expected)):
        assert False, f"Expected {expected}, got {ans}"


