def test_formula(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    first = {}
    for op, num in events:
        r = int(num)
        if r not in first:
            first[r] = op
    I = sum(1 for op in first.values() if op == '-')
    cur = 0
    max_delta = 0
    for op, _ in events:
        if op == '+':
            cur += 1
        else:
            cur -= 1
        if cur > max_delta:
            max_delta = cur
    correct = I + max_delta
    ans = int(run(x).strip())
    assert ans == correct


def test_bruteforce(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    visitors = list(set(int(num) for _, num in events))
    m = len(visitors)
    if m > 12:
        return
    vi = {v:i for i,v in enumerate(visitors)}
    best = float('inf')
    for mask in range(1 << m):
        inside = set()
        for i in range(m):
            if mask & (1 << i):
                inside.add(visitors[i])
        consistent = True
        max_inside = len(inside)
        cur = set(inside)
        for op, num in events:
            r = int(num)
            if op == '+':
                if r in cur:
                    consistent = False
                    break
                cur.add(r)
            else:
                if r not in cur:
                    consistent = False
                    break
                cur.remove(r)
            if len(cur) > max_inside:
                max_inside = len(cur)
        if consistent and max_inside < best:
            best = max_inside
    correct = best
    ans = int(run(x).strip())
    assert ans == correct


def test_lower_bound_first_minus(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    first = {}
    for op, num in events:
        r = int(num)
        if r not in first:
            first[r] = op
    I = sum(1 for op in first.values() if op == '-')
    ans = int(run(x).strip())
    assert ans >= I


