    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    cur = 0
    max_delta = 0
    for op, _ in events:
        if op == '+':
            cur += 1
        else:
            cur -= 1
        if cur > max_delta:
            max_delta = cur
    ans = int(run(x).strip())
    assert ans >= max_delta


def test_upper_bound_distinct(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    events = [line.split() for line in lines[1:1+n]]
    distinct = set(int(num) for _, num in events)
    ans = int(run(x).strip())
