def test_group1(run, x):
    # all-F and all-M inputs: answer must be 0
    expected = {"FFFFFFFFFFFF\n": 0, "MMMMMMMMMMMMMMMMMM\n": 0}
    if x in expected:
        out = run(x)
        assert int(out.strip()) == expected[x]

def test_group2(run, x):
    # single child: answer must be 0
    expected = {"F\n": 0, "M\n": 0}
    if x in expected:
        out = run(x)
        assert int(out.strip()) == expected[x]

def test_group3(run, x):
    # MF and FM pairs
    expected = {"MF\n": 1, "FM\n": 0}
    if x in expected:
        out = run(x)
        assert int(out.strip()) == expected[x]

def test_group4(run, x):
    # MMF and FMM
    expected = {"MMF\n": 2, "FMM\n": 0}
    if x in expected:
        out = run(x)
        assert int(out.strip()) == expected[x]

def test_group5(run, x):
    # MMFF and FFMM
    expected = {"MMFF\n": 3, "FFMM\n": 0}
    if x in expected:
        out = run(x)
        assert int(out.strip()) == expected[x]

def test_group6(run, x):
    # MMFM and MFFM
    expected = {"MMFM\n": 2, "MFFM\n": 2}
    if x in expected:
        out = run(x)
        assert int(out.strip()) == expected[x]

def test_group7(run, x):
    # FMFM and FFMFMM
    expected = {"FMFM\n": 1, "FFMFMM\n": 1}
    if x in expected:
        out = run(x)
        assert int(out.strip()) == expected[x]

def test_group8(run, x):
    # MMFMMMFF
    if x == "MMFMMMFF\n":
        out = run(x)
        assert int(out.strip()) == 6

def test_group9(run, x):
    # FFFFMMMM
    if x == "FFFFMMMM\n":
        out = run(x)
        assert int(out.strip()) == 0

def test_group10(run, x):
    # MFMFMFMF
    if x == "MFMFMFMF\n":
        out = run(x)
        assert int(out.strip()) == 4

