def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    assert stripped in ("YES", "NO"), f"Output must be YES or NO, got {stripped}"

def test_first_bill_50_or_100_implies_NO(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 2:
        return
    bills = list(map(int, lines[1].split()))
    if not bills:
        return
    first = bills[0]
    if first == 50 or first == 100:
        out = run(x)
        assert out.strip() == "NO", f"First bill is {first}, expected NO"

def test_all_25_implies_YES(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 2:
        return
    bills = list(map(int, lines[1].split()))
    if all(b == 25 for b in bills):
        out = run(x)
        assert out.strip() == "YES", f"All bills are 25, expected YES"

def test_greedy_agrees(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 2:
        bills = []
    else:
        bills = list(map(int, lines[1].split()))
    def greedy_possible(bills):
        a = 0
        b = 0
        for x in bills:
            if x == 25:
                a += 1
            elif x == 50:
                if a >= 1:
                    a -= 1
                    b += 1
                else:
                    return False
            else:
                if b >= 1 and a >= 1:
                    b -= 1
                    a -= 1
                elif a >= 3:
                    a -= 3
                else:
                    return False
        return True
    expected = greedy_possible(bills)
    out = run(x)
    got = out.strip()
    if expected:
        assert got == "YES", f"Greedy says YES, got {got}"
    else:
        assert got == "NO", f"Greedy says NO, got {got}"

def test_bruteforce_agrees(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) < 2:
        bills = []
    else:
        bills = list(map(int, lines[1].split()))
    from functools import lru_cache
    def brute_possible(bills):
        n = len(bills)
        @lru_cache(None)
        def dfs(i, a, b):
            if i == n:
                return True
            x = bills[i]
            if x == 25:
                return dfs(i+1, a+1, b)
            elif x == 50:
                if a > 0:
                    return dfs(i+1, a-1, b+1)
                else:
                    return False
            else:
                if a > 0 and b > 0:
                    if dfs(i+1, a-1, b-1):
                        return True
                if a >= 3:
                    if dfs(i+1, a-3, b):
                        return True
                return False
        return dfs(0, 0, 0)
    expected = brute_possible(bills)
    out = run(x)
    got = out.strip()
    if expected:
        assert got == "YES", f"Brute force says YES, got {got}"
    else:
        assert got == "NO", f"Brute force says NO, got {got}"

