    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    out = run(x)
    ans = int(out.strip())
    assert 0 <= ans <= n

def test_no_adjacent_x_zero(run, x):
    out = run(x)
    ans = int(out.strip())
    lines = x.strip().split('\n')
    parts = lines[0].split()
    if len(parts) < 3:
        return
    n, k, x_col = map(int, parts[:3])
    c = list(map(int, lines[1].split()))
    has_adjacent = any(i < n-1 and c[i] == x_col and c[i+1] == x_col for i in range(n-1))
    if not has_adjacent:
        assert ans == 0

def test_adjacent_x_lower_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    lines = x.strip().split('\n')
    parts = lines[0].split()
    if len(parts) < 3:
        return
    n, k, x_col = map(int, parts[:3])
    c = list(map(int, lines[1].split()))
    has_adjacent = any(i < n-1 and c[i] == x_col and c[i+1] == x_col for i in range(n-1))
    if has_adjacent:
        assert ans >= 2

