def test_lexeme_count(run, x):
    def count(s):
        cnt = 0
        i = 0
        n = len(s)
        while i < n:
            while i < n and s[i] == ' ':
                i += 1
            if i == n:
                break
            cnt += 1
            if s[i] == '\"':
                i += 1
                while i < n and s[i] != '\"':
                    i += 1
                if i == n:
                    break
                i += 1
            else:
                while i < n and s[i] != ' ':
                    i += 1
        return cnt
