            assert ch in allowed, f"Invalid character {ch} in lexeme {content}"

def test_full_oracle_small(run, x):
    if len(x) > 100:
        return
    def parse(s):
        lexemes = []
        i = 0
        n = len(s)
        while i < n:
            while i < n and s[i] == ' ':
                i += 1
            if i == n:
                break
            if s[i] == '\"':
                i += 1
                start = i
                while i < n and s[i] != '\"':
                    i += 1
                lexeme = s[start:i]
