tests_src:
def test_correct_answer(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return
    a = list(map(int, lines[1].split()))
    from collections import Counter
    freq = Counter(a)
    max_len = 2
    values = list(freq.keys())
    for i, a0 in enumerate(values):
        for j, a1 in enumerate(values):
            if a0 == a1 and freq[a0] < 2:
                continue
            if freq[a0] < 1 or freq[a1] < 1:
                continue
            f = freq.copy()
            f[a0] -= 1
            f[a1] -= 1
            length = 2
            x_val, y_val = a0, a1
            while True:
                nxt = x_val + y_val
                if f.get(nxt, 0) > 0:
                    f[nxt] -= 1
                    length += 1
                    x_val, y_val = y_val, nxt
                else:
                    break
            if length > max_len:
                max_len = length
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) == max_len

def test_output_format(run, x):
    output = run(x)
    lines = output.splitlines()
    assert len(lines) >= 1
    first_line = lines[0].strip()
    assert first_line.isdigit()
    for line in lines[1:]:
        assert line.strip() == ''

def test_answer_bounds(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    output = run(x).strip()
    ans = int(output)
    assert 2 <= ans <= n

def test_example1(run, x):
    if x == "3\n1 2 -1\n":
        output = run(x)
        assert output == "3\n"

def test_example2(run, x):
    if x == "5\n28 35 7 14 21\n":
        output = run(x)
        assert output == "4\n"

def test_negative_sequence1(run, x):
    if x == "3\n-1 -2 -3\n":
        output = run(x)
        assert output == "3\n"

def test_negative_sequence2(run, x):
    if x == "4\n-5 -4 -9 -13\n":
        output = run(x)
        assert output == "4\n"

def test_zero_lower_bound(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    zero_count = a.count(0)
    if zero_count >= 2:
        output = run(x).strip()
        ans = int(output)
        assert ans >= zero_count

def test_all_equal_nonzero(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if len(set(a)) == 1 and a[0] != 0:
        output = run(x).strip()
        ans = int(output)
        assert ans == 2

def test_all_zero(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if all(v == 0 for v in a):
        output = run(x).strip()
        ans = int(output)
        assert ans == len(a)

