def test_exact_oracle(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    if n > 9:
        return
    a = list(map(int, lines[1:1+n]))
    from collections import Counter
    cnt = Counter(a)
    vals = list(cnt.keys())
    freqs = [cnt[v] for v in vals]
    best = 2
    for i, xv in enumerate(vals):
        for j, yv in enumerate(vals):
            if i == j and freqs[i] < 2:
                continue
            if i != j and (freqs[i] < 1 or freqs[j] < 1):
                continue
            freq_copy = freqs.copy()
            freq_copy[i] -= 1
            freq_copy[j] -= 1
            seq = [xv, yv]
            while True:
                nxt = seq[-1] + seq[-2]
                try:
                    k = vals.index(nxt)
                except ValueError:
                    break
                if freq_copy[k] > 0:
                    seq.append(nxt)
                    freq_copy[k] -= 1
                else:
                    break
            best = max(best, len(seq))
    correct = best
    output = int(run(x).strip())
    assert output == correct, f"Expected {correct}, got {output}"

