def test_decision(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    board = lines[1:]
    # oracle: maximal set condition
    pieces = []
    dots = []
    x_cells = []
    for i in range(n):
        for j in range(n):
            c = board[i][j]
            if c == 'o':
                pieces.append((i,j))
            elif c == '.':
                dots.append((i,j))
            elif c == 'x':
                x_cells.append((i,j))
    size = 2*n-1
    allowed = [[True]*size for _ in range(size)]
    for (pi,pj) in pieces:
        for (di,dj) in dots:
            dx = di - pi
            dy = dj - pj
            allowed[dx+n-1][dy+n-1] = False
    ok = True
    for (xi,xj) in x_cells:
        attacked = False
        for (pi,pj) in pieces:
            dx = xi - pi
            dy = xj - pj
            if allowed[dx+n-1][dy+n-1]:
                attacked = True
                break
        if not attacked:
            ok = False
            break
    expected_yes = ok
    output = run(x)
    lines_out = output.strip().split('\n')
    first = lines_out[0].strip()
    if expected_yes:
        assert first == 'YES', f'Expected YES, got {first}'
    else:
        assert first == 'NO', f'Expected NO, got {first}'

def test_yes_format(run, x):
    output = run(x)
    lines_out = output.strip().split('\n')
    first = lines_out[0].strip()
    if first != 'YES':
        return
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    if len(lines_out) != 2*n:
        assert False, f'Expected {2*n} lines total, got {len(lines_out)}'
    board_lines = lines_out[1:]
    assert len(board_lines) == 2*n-1, f'Expected {2*n-1} board lines, got {len(board_lines)}'
    for i, line in enumerate(board_lines):
        assert len(line) == 2*n-1, f'Line {i} length {len(line)}, expected {2*n-1}'
        for ch in line:
            assert ch in 'ox.', f'Invalid character {ch} in board line'

def test_no_format(run, x):
    output = run(x)
    lines_out = output.strip().split('\n')
    first = lines_out[0].strip()
    if first != 'NO':
