def test_format(run, x):
    out = run(x)
    answer = out.strip()
    assert answer in ("Yes", "No"), f"Output must be Yes or No, got {answer}"
    assert out == answer or out == answer + "\n", f"Output contains extra whitespace"

def test_all_zero_no(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = lines[1:]
    if all(c == '0' for row in grid for c in row):
        assert out.strip() == "No", f"All-zero grid should output No, got {out.strip()}"

def test_all_four_yes(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = lines[1:]
    if all(c == '4' for row in grid for c in row):
        assert out.strip() == "Yes", f"All-four grid should output Yes, got {out.strip()}"

def test_yes_requires_four(run, x):
    out = run(x)
    if out.strip() == "Yes":
        lines = x.strip().splitlines()
        if len(lines) < 2:
            return
        grid = lines[1:]
        if not any('4' in row for row in grid):
            assert False, "Output Yes but grid contains no '4'"

def test_yes_4_rectangle(run, x):
    out = run(x)
    if out.strip() == "Yes":
        lines = x.strip().splitlines()
        if len(lines) < 2:
            return
        n = int(lines[0])
        grid = [list(row) for row in lines[1:]]
        four_pos = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == '4']
        if not four_pos:
            assert False, "Yes but no 4's"
        rows = [r for r, c in four_pos]
        cols = [c for r, c in four_pos]
        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)
        for r in range(rmin, rmax+1):
            for c in range(cmin, cmax+1):
                if grid[r][c] != '4':
                    assert False, f"Yes but cell at ({r},{c}) in bounding box of 4's is not 4"

def test_yes_pattern_necessary(run, x):
    out = run(x)
    if out.strip() != "Yes":
        return
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = [list(map(int, row)) for row in lines[1:]]
    four_pos = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 4]
    if not four_pos:
        assert False, "Yes but no 4's"
    rows = [r for r, c in four_pos]
    cols = [c for r, c in four_pos]
    rmin, rmax = min(rows), max(rows)
    cmin, cmax = min(cols), max(cols)
    x1 = cmin
    x2 = cmax + 1
    y1 = n - rmax - 1
    y2 = n - rmin
    if not (0 <= x1 < x2 <= n and 0 <= y1 < y2 <= n):
        assert False, "Derived rectangle is out of bounds"
    for r in range(n):
        for c in range(n):
            corners = [(c, n-r), (c+1, n-r), (c, n-r-1), (c+1, n-r-1)]
            cnt = sum(1 for (cx, cy) in corners if x1 <= cx <= x2 and y1 <= cy <= y2)
            if grid[r][c] != cnt:
                assert False, f"Yes but cell ({r},{c}) has {grid[r][c]} expected {cnt}"

def test_pattern_sufficient_yes(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    grid = [list(map(int, row)) for row in lines[1:]]
    four_pos = [(r, c) for r in range(n) for c in range(n) if grid[r][c] == 4]
    if not four_pos:
        return
    rows = [r for r, c in four_pos]
    cols = [c for r, c in four_pos]
    rmin, rmax = min(rows), max(rows)
    cmin, cmax = min(cols), max(cols)
    for r in range(rmin, rmax+1):
        for c in range(cmin, cmax+1):
            if grid[r][c] != 4:
                return
    x1 = cmin
    x2 = cmax + 1
    y1 = n - rmax - 1
    y2 = n - rmin
    if not (0 <= x1 < x2 <= n and 0 <= y1 < y2 <= n):
        return
    for r in range(n):
        for c in range(n):
            corners = [(c, n-r), (c+1, n-r), (c, n-r-1), (c+1, n-r-1)]
            cnt = sum(1 for (cx, cy) in corners if x1 <= cx <= x2 and y1 <= cy <= y2)
            if grid[r][c] != cnt:
                return
    assert out.strip() == "Yes", f"Grid matches a rectangle pattern, but output is {out.strip()}"

def test_bruteforce_small(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n > 10:
        return
    grid = [list(map(int, row)) for row in lines[1:]]
    exists = False
    for x1 in range(n):
        for x2 in range(x1+1, n+1):
            for y1 in range(n):
                for y2 in range(y1+1, n+1):
                    ok = True
                    for r in range(n):
                        y_top = n - r
                        y_bottom = n - r - 1
                        for c in range(n):
                            corners = [(c, y_top), (c+1, y_top), (c, y_bottom), (c+1, y_bottom)]
                            cnt = sum(1 for (cx, cy) in corners if x1 <= cx <= x2 and y1 <= cy <= y2)
                            if cnt != grid[r][c]:
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        exists = True
                        break
                if exists:
                    break
            if exists:
                break
        if exists:
            break
    expected = "Yes" if exists else "No"
    assert out.strip() == expected, f"Brute force says {expected}, got {out.strip()}"

def test_no_4_implies_no(run, x):
    out = run(x)
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    grid = lines[1:]
    if not any('4' in row for row in grid):
        assert out.strip() == "No", f"Grid has no '4', output should be No, got {out.strip()}"

def test_example(run, x):
    example_input = "6\n000000\n000000\n012100\n024200\n012100\n000000\n"
    if x == example_input:
        out = run(x)
        assert out.strip() == "Yes", f"Example input should output Yes, got {out.strip()}"

