      "name": "test_lower_bound_prefix_suffix",
      "source": "def test_lower_bound_prefix_suffix(run, x):
    a, b = x.strip().split('\n')[:2]
    i = 0
    pref_len = 0
    for ch in b:
        while i < len(a) and a[i] != ch:
