        return all(ch in it for ch in s)
    n = len(b)
    best_len = 0
    for i in range(n+1):
        for j in range(i, n+1):
            rem = b[:i] + b[j:]
            if is_subseq(rem, a):
                best_len = max(best_len, len(rem))
