def test_format(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    out = run(x).strip().split('\n')
    assert len(out) == n
    for line in out:
        assert line in ("Vanya", "Vova", "Both")

def test_first_hit(run, x):
    data = x.strip().split('\n')
    n, x_val, y_val = map(int, data[0].split())
    out = run(x).strip().split('\n')
    for i in range(n):
        a = int(data[i+1].strip())
        if a == 1:
            if x_val > y_val:
                expected = "Vanya"
            elif x_val < y_val:
                expected = "Vova"
            else:
                expected = "Both"
            assert out[i] == expected

def test_equal_frequencies(run, x):
    data = x.strip().split('\n')
    n, x_val, y_val = map(int, data[0].split())
    if x_val == y_val:
        out = run(x).strip().split('\n')
        for line in out:
            assert line == "Both"

def test_both_iff_multiple_of_period(run, x):
    import math
    data = x.strip().split('\n')
    n, x_val, y_val = map(int, data[0].split())
    if x_val == y_val:
        return
    g = math.gcd(x_val, y_val)
    xr = x_val // g
    yr = y_val // g
    L = xr + yr - 1
    out = run(x).strip().split('\n')
    for i in range(n):
        a = int(data[i+1].strip())
        if out[i] == "Both":
            assert a % L == 0
        else:
            assert a % L != 0

def test_simulation_small(run, x):
    data = x.strip().split('\n')
    n, x_val, y_val = map(int, data[0].split())
    out = run(x).strip().split('\n')
    for i in range(n):
        a = int(data[i+1].strip())
        if a > 10000:
            continue
        i_vanya = 0
