    y_val = int(parts[2])
    if x_val == y_val:
        output = run(x)
        lines = output.strip().splitlines()
        for line in lines:
            assert line.strip() == "Both"

def test_first_hit_rule(run, x):
    lines_in = x.strip().splitlines()
    if len(lines_in) < 2:
        return
    header = lines_in[0].split()
    if len(header) < 3:
        return
    n = int(header[0])
    x_val = int(header[1])
    y_val = int(header[2])
    output = run(x)
    out_lines = output.strip().splitlines()
    if len(out_lines) != n:
        return
    for i in range(n):
        a = int(lines_in[i+1].strip())
        if a == 1:
            if x_val > y_val:
                expected = "Vanya"
            elif x_val < y_val:
                expected = "Vova"
            else:
                expected = "Both"
            assert out_lines[i].strip() == expected

def test_small_a_bruteforce(run, x):
    def simulate(x_val, y_val, a):
        i = j = 1
        hit = 0
        while True:
            t1 = i * y_val
            t2 = j * x_val
            if t1 < t2:
                hit += 1
                if hit == a:
                    return "Vanya"
                i += 1
            elif t1 > t2:
                hit += 1
                if hit == a:
                    return "Vova"
                j += 1
            else:
                if hit + 1 == a or hit + 2 == a:
                    return "Both"
                hit += 2
                i += 1
                j += 1
    lines_in = x.strip().splitlines()
    if len(lines_in) < 2:
        return
    header = lines_in[0].split()
    if len(header) < 3:
        return
    n = int(header[0])
    x_val = int(header[1])
    y_val = int(header[2])
    THRESHOLD = 10000
    output = run(x)
    out_lines = output.strip().splitlines()
    if len(out_lines) != n:
        return
    for i in range(n):
        a = int(lines_in[i+1].strip())
        if a <= THRESHOLD:
            expected = simulate(x_val, y_val, a)
            assert out_lines[i].strip() == expected

