    if len(header) < 3:
        return
    n = int(header[0])
    x_val = int(header[1])
    y_val = int(header[2])
    s = x_val + y_val
    output = run(x)
    out_lines = output.strip().splitlines()
    if len(out_lines) != n:
        return
    for i in range(n):
        a = int(lines_in[i+1].strip())
        if a == s:
            assert out_lines[i].strip() == "Both"

