        output = run(x)
        lines = output.strip().splitlines()
        expected = ["Vanya", "Vova", "Vanya", "Both"]
        assert len(lines) == 4
        for i in range(4):
            assert lines[i].strip() == expected[i]

def test_multiple_of_period_is_both(run, x):
    import math
    lines_in = x.strip().splitlines()
    if len(lines_in) < 2:
        return
    header = lines_in[0].split()
    if len(header) < 3:
        return
    n = int(header[0])
    x_val = int(header[1])
    y_val = int(header[2])
    g = math.gcd(x_val, y_val)
    d = (x_val + y_val) // g
    output = run(x)
    out_lines = output.strip().splitlines()
    if len(out_lines) != n:
        return
    for i in range(n):
        a = int(lines_in[i+1].strip())
        if a % d == 0:
            assert out_lines[i].strip() == "Both"

