tests_src:
def test_output_format(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_non_negative(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    assert val >= 0

def test_not_exceed_total(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    total = b - a + 1
    assert val <= total

def test_k_eq_1(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    if k != 1:
        return
    expected = b - a + 1
    assert val == expected

def test_single_point(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    if a != b:
        return
    if a % k == 0:
        assert val == 1
    else:
        assert val == 0

def test_contains_zero(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    if a <= 0 <= b:
        assert val >= 1

def test_both_divisible(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    if a % k == 0 and b % k == 0:
        expected = (b - a) // k + 1
        assert val == expected

def test_left_divisible(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    if a % k == 0:
        expected = b // k - a // k + 1
        assert val == expected

def test_full_oracle_small(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    n = b - a + 1
    if n > 8:
        return
    count = 0
    for x in range(a, b + 1):
        if x % k == 0:
            count += 1
    assert val == count

def test_formula_consistency(run, x):
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        assert False
    parts = x.strip().split()
    if len(parts) < 3:
        return
    k, a, b = map(int, parts[:3])
    import math
    # ceil(a/k) for integers: (a + k - 1) // k if a>0 else a // k
    if a > 0:
        first = (a + k - 1) // k
    else:
        first = a // k  # floor division works for negative
    last = b // k  # floor division
    expected = max(0, last - first + 1)
    assert val == expected

