    k, a, b = map(int, tokens)
    if not (1 <= k <= 10**18 and -10**18 <= a <= b <= 10**18):
        return
    out = run(x)
    try:
        n = int(out.strip())
    except ValueError:
        assert False
    assert n >= 0

def test_upper_bound(run, x):
    tokens = x.strip().split()
