def test_exact_oracle_small(run, x):
    tokens = x.strip().split()
    if len(tokens) != 3:
        return
    k, a, b = map(int, tokens)
    if not (1 <= k <= 10**18 and -10**18 <= a <= b <= 10**18):
        return
    if b - a > 10**6:
        return
    count = 0
    for x_val in range(a, b + 1):
        if x_val % k == 0:
            count += 1
    out = run(x)
    try:
        n = int(out.strip())
    except ValueError:
        assert False
    assert n == count

def test_exact_oracle_formula(run, x):
    tokens = x.strip().split()
    if len(tokens) != 3:
        return
    k, a, b = map(int, tokens)
    if not (1 <= k <= 10**18 and -10**18 <= a <= b <= 10**18):
        return
    expected = b // k - (a - 1) // k
    out = run(x)
    try:
        n = int(out.strip())
    except ValueError:
        assert False
    assert n == expected

