def test_sorted(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        return
    k = int(lines[0])
    pairs = []
    for i in range(1, k+1):
        s, t = map(int, lines[i].split())
        pairs.append((s, t))
    for i in range(1, len(pairs)):
        assert pairs[i][0] > pairs[i-1][0] or (pairs[i][0] == pairs[i-1][0] and pairs[i][1] > pairs[i-1][1]), "pairs not sorted correctly"


def test_no_duplicates(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        return
    k = int(lines[0])
    pairs = set()
    for i in range(1, k+1):
        s, t = map(int, lines[i].split())
        assert (s, t) not in pairs, f"duplicate pair ({s}, {t})"
        pairs.add((s, t))


def test_bounds(run, x):
    n = int(x.strip().split('\n')[0])
    out = run(x)
    lines = out.strip().split('\n')
    if not lines:
        return
    k = int(lines[0])
    for i in range(1, k+1):
        s, t = map(int, lines[i].split())
        assert 1 <= s <= n, f"s={s} out of bounds"
        assert 1 <= t <= n, f"t={t} out of bounds"


def test_each_pair_valid(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    out = run(x)
    lines_out = out.strip().split('\n')
    if not lines_out:
        return
    k = int(lines_out[0])
    for i in range(1, k+1):
        s, t = map(int, lines_out[i].split())
