def test_t1_condition(run, x):
    lines_in = x.strip().split('\n')
    a = list(map(int, lines_in[1].split()))
    c1 = a.count(1)
    c2 = a.count(2)
    last = a[-1]
    out = run(x)
    lines_out = out.strip().split('\n')
    if not lines_out:
        return
    k = int(lines_out[0])
    t1_pairs = []
    for i in range(1, k+1):
        s, t = map(int, lines_out[i].split())
        if t == 1:
            t1_pairs.append((s, t))
    if last == 1:
        c_last = c1
        other = c2
    else:
        c_last = c2
        other = c1
    if c_last > other:
        assert len(t1_pairs) == 1, f"expected exactly one t=1 pair, got {len(t1_pairs)}"
        assert t1_pairs[0] == (c_last, 1), f"expected ({c_last},1), got {t1_pairs[0]}"
    else:
        assert len(t1_pairs) == 0, f"expected no t=1 pairs, got {len(t1_pairs)}"


def test_tn_condition(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    all_same = all(x == a[0] for x in a)
    out = run(x)
    lines_out = out.strip().split('\n')
    if not lines_out:
        return
    k = int(lines_out[0])
    tn_pairs = []
    for i in range(1, k+1):
        s, t = map(int, lines_out[i].split())
        if t == n:
            tn_pairs.append((s, t))
    if all_same:
        assert len(tn_pairs) == 1, f"expected exactly one t=n pair, got {len(tn_pairs)}"
        assert tn_pairs[0] == (1, n), f"expected (1,{n}), got {tn_pairs[0]}"
    else:
        assert len(tn_pairs) == 0, f"expected no t=n pairs, got {len(tn_pairs)}"


def test_number_of_sets(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    out = run(x)
    lines_out = out.strip().split('\n')
    if not lines_out:
        return
    k = int(lines_out[0])
    for i in range(1, k+1):
        s, t = map(int, lines_out[i].split())
        points1 = points2 = 0
        sets1 = sets2 = 0
        valid = False
        for idx, winner in enumerate(a):
            if winner == 1:
                points1 += 1
            else:
                points2 += 1
            if points1 == t:
                sets1 += 1
                points1 = points2 = 0
            elif points2 == t:
                sets2 += 1
                points1 = points2 = 0
            if sets1 == s or sets2 == s:
                if idx == n-1:
                    valid = True
                    break
                else:
