def test_all_same_sequence(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    if not all(v == a[0] for v in a):
        return
    expected = []
    for s in range(1, n+1):
        if n % s == 0:
            t = n // s
            if 1 <= t <= n:
                expected.append((s, t))
    expected.sort(key=lambda p: (p[0], p[1]))
    out = run(x)
    lines_out = out.strip().split('\n')
    k = int(lines_out[0])
    out_pairs = []
    for i in range(1, k+1):
        s, t = map(int, lines_out[i].split())
        out_pairs.append((s, t))
    assert expected == out_pairs, f"for all-same sequence, expected {expected}, got {out_pairs}"


def test_brute_force(run, x):
    lines_in = x.strip().split('\n')
    n = int(lines_in[0])
    a = list(map(int, lines_in[1].split()))
    valid_pairs = []
    for t in range(1, n+1):
        for s in range(1, n+1):
            points1 = points2 = 0
            sets1 = sets2 = 0
            ok = True
            for idx, winner in enumerate(a):
                if winner == 1:
                    points1 += 1
                else:
                    points2 += 1
                if points1 == t:
                    sets1 += 1
                    points1 = points2 = 0
                elif points2 == t:
                    sets2 += 1
                    points1 = points2 = 0
                if sets1 == s or sets2 == s:
                    if idx != n-1:
                        ok = False
                        break
                    else:
                        pass
            if ok and (sets1 == s or sets2 == s):
                valid_pairs.append((s, t))
    valid_pairs.sort(key=lambda p: (p[0], p[1]))
    out = run(x)
    lines_out = out.strip().split('\n')
    if not lines_out:
        assert False, "output empty"
    k_out = int(lines_out[0])
    out_pairs = []
    for i in range(1, k_out+1):
        s, t = map(int, lines_out[i].split())
        out_pairs.append((s, t))
    assert valid_pairs == out_pairs, f"mismatch: expected {valid_pairs}, got {out_pairs}"

