        assert len(pairs) == k, 'output line count mismatch'
        return k, pairs
    n, a = parse_input(x)
    out = run(x)
    k, pairs = parse_output(out)
    for s, t in pairs:
        sets1 = sets2 = 0
        p1 = p2 = 0
        match_end = None
        for i, serve in enumerate(a, start=1):
            if serve == 1:
                p1 += 1
            else:
                p2 += 1
            if p1 == t or p2 == t:
                if p1 == t:
                    sets1 += 1
                else:
                    sets2 += 1
                if sets1 == s and sets2 < s and match_end is None:
                    match_end = i
                elif sets2 == s and sets1 < s and match_end is None:
                    match_end = i
                p1 = p2 = 0
        if match_end is None or match_end != len(a) or p1 != 0 or p2 != 0:
            assert False, f'Pair ({s},{t}) invalid: match did not end exactly at last point'
        winner = 1 if sets1 > sets2 else 2
        assert winner == a[-1], f'Pair ({s},{t}): winner does not match last point winner'

def test_all_same_player_divisor_pairs(run, x):
    def parse_input(x):
        lines = x.strip().splitlines()
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
        return n, a
    def parse_output(out):
        lines = out.strip().splitlines()
        if not lines:
            return 0, []
        k = int(lines[0])
        pairs = []
        for i in range(1, k+1):
            if i >= len(lines):
                break
            s, t = map(int, lines[i].split())
            pairs.append((s, t))
        assert len(pairs) == k, 'output line count mismatch'
        return k, pairs
    n, a = parse_input(x)
    if n > 1000:   # guard: O(n) loop, skip for very large n
        return
    if all(v == a[0] for v in a):
        out = run(x)
        k, pairs = parse_output(out)
        expected = []
        for s in range(1, n+1):
            if n % s == 0:
                expected.append((s, n // s))
        assert k == len(expected), 'wrong number of pairs for uniform sequence'
        assert pairs == expected, 'pairs do not match divisor pairs for uniform sequence'

