        lines = out.strip().splitlines()
        if not lines:
            return 0, []
        k = int(lines[0])
        pairs = []
        for i in range(1, k+1):
            if i >= len(lines):
                break
            s, t = map(int, lines[i].split())
            pairs.append((s, t))
        assert len(pairs) == k, 'output line count mismatch'
        return k, pairs
