def test_examples_match(run, x):
    output = run(x).strip()
    examples = [
        ("5 7 6 11\n3\n5 3 8\n6 7 11\n5 2 5\n", "4"),
        ("3 4 3 10\n3\n3 1 4\n4 5 9\n3 10 10\n", "6"),
