    output = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) < 4:
        return
    x0, y0, x1, y1 = map(int, first[:4])
    if x0 != x1:
        return
    n = int(lines[1].strip())
    intervals = []
    for i in range(2, 2 + n):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 3:
            continue
        r, a, b = map(int, parts[:3])
        if r == x0:
            intervals.append((a, b))
    intervals.sort()
    merged = []
    for a, b in intervals:
        if not merged or a > merged[-1][1] + 1:
            merged.append([a, b])
        else:
            merged[-1][1] = max(merged[-1][1], b)
    low = min(y0, y1)
    high = max(y0, y1)
