def test_diagonal_path_allowed(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) < 4:
        return
    x0, y0, x1, y1 = map(int, first[:4])
    dx = x1 - x0
    dy = y1 - y0
    adx = abs(dx)
    ady = abs(dy)
    d = max(adx, ady)
    if d > 1000:
        return
    n = int(lines[1].strip())
    row_intervals = {}
    for i in range(2, 2 + n):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 3:
            continue
        r, a, b = map(int, parts[:3])
        row_intervals.setdefault(r, []).append((a, b))
    def is_allowed(r, c):
        if r not in row_intervals:
            return False
        for a, b in row_intervals[r]:
            if a <= c <= b:
                return True
        return False
    cells = []
    cx, cy = x0, y0
    while (cx, cy) != (x1, y1):
        cells.append((cx, cy))
        if cx < x1:
            cx += 1
        elif cx > x1:
            cx -= 1
        if cy < y1:
            cy += 1
        elif cy > y1:
            cy -= 1
    cells.append((x1, y1))
    for r, c in cells:
        if not is_allowed(r, c):
            return
    if output == "-1":
        assert False, f"Diagonal path fully allowed, expected {d}, got -1"
    else:
        val = int(output)
        assert val == d, f"Diagonal path fully allowed, expected {d}, got {val}"

