def test_formula(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    from collections import Counter
    freq = Counter(a)
    maxf = max(freq.values())
    expected = n - maxf
    out = int(run(x).strip())
    assert out == expected

def test_brute_small(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    if n > 8:
        return
    a = list(map(int, parts[1:]))
    import itertools
    perms = set(itertools.permutations(a))
    best = 0
    for perm in perms:
        happy = sum(1 for i in range(n-1) if perm[i] < perm[i+1])
        if happy > best:
            best = happy
    out = int(run(x).strip())
    assert out == best

def test_all_equal(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if len(set(a)) == 1:
        out = int(run(x).strip())
        assert out == 0

def test_all_distinct(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    a = list(map(int, parts[1:]))
    if len(set(a)) == n:
        out = int(run(x).strip())
        assert out == n-1

def test_example1(run, x):
    if x == "5\n20 30 10 50 40\n":
        out = int(run(x).strip())
        assert out == 4

def test_example2(run, x):
    if x == "4\n200 100 100 200\n":
        out = int(run(x).strip())
        assert out == 2

def test_buggy1(run, x):
    if x == "3\n1 2 2\n":
        out = int(run(x).strip())
        assert out == 1

def test_buggy2(run, x):
    if x == "5\n1000 1 1 1 1\n":
        out = int(run(x).strip())
        assert out == 1

def test_buggy3(run, x):
    if x == "3\n5 5 6\n":
        out = int(run(x).strip())
        assert out == 1

def test_bounds(run, x):
    parts = x.strip().split()
    if not parts:
        return
    n = int(parts[0])
    out = int(run(x).strip())
    assert 0 <= out <= n-1

