    if not (1 <= t[0] and all(t[i-1] < t[i] for i in range(1, n)) and t[-1] <= 10**9):
        return
    out = run(x)
    try:
        ans = int(out.strip())
    except:
        assert False, "Output not an integer"
    cnt = 1
    for i in range(1, n):
