def test_bruteforce_small(run, x):
    a, k = x.strip().split()
    k = int(k)
    n = len(a)
    total = n * k
    if total > 12:
        return
    s = a * k
    MOD = 10**9 + 7
    count = 0
    for mask in range(1, 1 << total):
        max_idx = -1
        for i in range(total):
            if mask & (1 << i):
                max_idx = i
        if s[max_idx] in '05':
            count += 1
    count %= MOD
    out = run(x).strip()
    assert int(out) == count

def test_no_eligible_digit(run, x):
    a, k = x.strip().split()
    if not any(c in '05' for c in a):
        out = run(x).strip()
        assert out == '0'

def test_all_eligible_digit(run, x):
    a, k = x.strip().split()
    k = int(k)
    n = len(a)
    if all(c in '05' for c in a):
        MOD = 10**9 + 7
        expected = (pow(2, n * k, MOD) - 1) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_k1(run, x):
    a, k = x.strip().split()
    k = int(k)
    if k == 1:
        MOD = 10**9 + 7
        n = len(a)
        s = 0
        for i, c in enumerate(a):
            if c in '05':
                s = (s + pow(2, i, MOD)) % MOD
        out = run(x).strip()
        assert int(out) == s

def test_k2(run, x):
    a, k = x.strip().split()
    k = int(k)
    if k == 2:
        MOD = 10**9 + 7
        n = len(a)
        s = 0
        for i, c in enumerate(a):
            if c in '05':
                s = (s + pow(2, i, MOD)) % MOD
        expected = (1 + pow(2, n, MOD)) * s % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_k3(run, x):
    a, k = x.strip().split()
    k = int(k)
    if k == 3:
        MOD = 10**9 + 7
        n = len(a)
        s = 0
        for i, c in enumerate(a):
            if c in '05':
                s = (s + pow(2, i, MOD)) % MOD
        expected = (1 + pow(2, n, MOD) + pow(2, 2 * n, MOD)) * s % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_output_format(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD

def test_examples(run, x):
    if x == "1256\n1\n":
        expected = "4"
    elif x == "13990\n2\n":
        expected = "528"
    elif x == "555\n2\n":
        expected = "63"
    else:
        return
    out = run(x).strip()
    assert out == expected

def test_single_digit_0(run, x):
    a, k = x.strip().split()
