    if a == "0":
        MOD = 10**9 + 7
        expected = (pow(2, k, MOD) - 1) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_single_digit_5(run, x):
    a, k = x.strip().split()
    k = int(k)
    if a == "5":
        MOD = 10**9 + 7
        expected = (pow(2, k, MOD) - 1) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_output_range(run, x):
    out = run(x).strip()
    ans = int(out)
    assert 0 <= ans < 512

def test_lower_bound(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    L = 0
    for ai in a:
        and_all = (1 << 9) - 1
        for bj in b:
            and_all &= (ai & bj)
        L |= and_all
    ans = int(run(x).strip())
    assert ans >= L

def test_upper_bound_min_j(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    best = None
    for bj in b:
        cur = 0
        for ai in a:
            cur |= (ai & bj)
        if best is None or cur < best:
            best = cur
    ans = int(run(x).strip())
    assert ans <= best

def test_upper_bound_min_per_i(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    U = 0
    for ai in a:
        min_val = min(ai & bj for bj in b)
        U |= min_val
    ans = int(run(x).strip())
