def test_upper_bound_and_of_or(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    or_a = 0
    for ai in a:
        or_a |= ai
    or_b = 0
    for bj in b:
        or_b |= bj
    U = or_a & or_b
    ans = int(run(x).strip())
    assert ans <= U

def test_feasibility(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    for ai in a:
        ok = False
        for bj in b:
            if ((ai & bj) & ~ans) == 0:
                ok = True
                break
        assert ok, f"No feasible choice for a={ai}"

def test_minimal_bit_removal(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    def feasible(cand):
        for ai in a:
            ok = False
            for bj in b:
                if ((ai & bj) & ~cand) == 0:
                    ok = True
                    break
            if not ok:
                return False
        return True
    for k in range(9):
        if ans & (1 << k):
            cand = ans ^ (1 << k)
            assert not feasible(cand), f"Bit {k} removable"

def test_minimal_all_smaller(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    ans = int(run(x).strip())
    def feasible(cand):
        for ai in a:
            ok = False
            for bj in b:
                if ((ai & bj) & ~cand) == 0:
                    ok = True
                    break
            if not ok:
                return False
        return True
    assert feasible(ans), f"Answer {ans} is not feasible"
    for k in range(ans):
        assert not feasible(k), f"Smaller candidate {k} is feasible"

def test_brute_force(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    if n > 5 or m > 5:
        return
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    from itertools import product
    min_or = None
    for choice in product(range(m), repeat=n):
        cur = 0
        for i in range(n):
            cur |= (a[i] & b[choice[i]])
        if min_or is None or cur < min_or:
            min_or = cur
    ans = int(run(x).strip())
    assert ans == min_or

def test_zero_feasibility(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    zero_feasible = True
    for ai in a:
        ok = False
        for bj in b:
            if (ai & bj) == 0:
                ok = True
                break
        if not ok:
            zero_feasible = False
            break
    ans = int(run(x).strip())
    if zero_feasible:
        assert ans == 0, "Zero feasible so answer must be 0"

