def test_small_brute_force(run, x):
    N, M = map(int, x.strip().split())
    if N <= 20 and M <= 20:
        counts = [[0]*M for _ in range(N)]
        for i in range(N):
            for j in range(M):
                for di in (-1,0,1):
                    for dj in (-1,0,1):
                        ni, nj = i+di, j+dj
                        if 0 <= ni < N and 0 <= nj < M:
                            counts[ni][nj] += 1
        odd = sum(1 for i in range(N) for j in range(M) if counts[i][j] % 2 == 1)
        ans = int(run(x).strip())
        assert ans == odd, f"Brute force says {odd}, got {ans}"

