        for val in out[first_zero:]:
            assert val == 0, f'Non-zero after first zero'

def test_number_of_positives(run, x):
    out = list(map(int, run(x).strip().split()))
    nk = list(map(int, x.strip().split('\n')[0].split()))
    if len(nk) < 2:
        return
    n = nk[0]
    pos_count = sum(1 for val in out if val > 0)
    assert pos_count <= n, f'Positive outputs {pos_count} exceed n {n}'

def test_prefix_sums_match_distinct(run, x):
    out = list(map(int, run(x).strip().split()))
    a = list(map(int, x.strip().split('\n')[1].split()))
    pos = []
    for val in out:
        if val == 0:
            break
        pos.append(val)
    if not pos:
        return
    distinct_a = sorted(set(a))
    assert len(pos) <= len(distinct_a), f'More positive outputs than distinct values'
    pref = []
    s = 0
    for p in pos:
        s += p
        pref.append(s)
    for i, s_val in enumerate(pref):
        assert i < len(distinct_a), f'Not enough distinct values'
        assert s_val == distinct_a[i], f'Prefix sum {s_val} != distinct_a[{i}]={distinct_a[i]}'
    for i, p in enumerate(pos):
        if i == 0:
            assert p == distinct_a[0], f'First output {p} != first distinct {distinct_a[0]}'
        else:
            assert p == distinct_a[i] - distinct_a[i-1], f'Output {p} != difference {distinct_a[i]-distinct_a[i-1]}'

def test_output_le_max(run, x):
    out = list(map(int, run(x).strip().split()))
    a = list(map(int, x.strip().split('\n')[1].split()))
    max_a = max(a)
    for val in out:
        assert val <= max_a, f'Output {val} > max(a) {max_a}'

def test_sum_outputs_le_sum_a(run, x):
