    for _ in range(k):
        mn = None
        for val in arr:
            if val > 0:
                if mn is None or val < mn:
                    mn = val
        if mn is None:
            mn = 0
        expected.append(mn)
        if mn > 0:
            for i in range(n):
                if arr[i] > 0:
                    arr[i] -= mn
