def test_direct_oracle(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a,b))
    happy = False
    for i in range(n):
        for j in range(n):
            if i == j: continue
            if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                happy = True
                break
        if happy:
            break
    assert output in ('Happy Alex\n', 'Poor Alex\n')
    assert (output == 'Happy Alex\n') == happy

def test_output_format(run, x):
    output = run(x)
    assert output in ('Happy Alex\n', 'Poor Alex\n')

def test_n1_case(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        assert output == 'Poor Alex\n'

def test_n2_case(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        pairs = []
        for i in range(1, 3):
            a, b = map(int, lines[i].split())
            pairs.append((a,b))
        pairs.sort(key=lambda x: x[0])
        a1,b1 = pairs[0]
        a2,b2 = pairs[1]
        happy = (b1 > b2)
        assert output in ('Happy Alex\n', 'Poor Alex\n')
        assert (output == 'Happy Alex\n') == happy

def test_consecutive_inversion_implies_happy(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a,b))
    pairs.sort(key=lambda x: x[0])
    for i in range(n-1):
        if pairs[i][1] > pairs[i+1][1]:
            assert output == 'Happy Alex\n'
            return

def test_strictly_increasing_implies_poor(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a,b))
    pairs.sort(key=lambda x: x[0])
    strictly_inc = all(pairs[i][1] < pairs[i+1][1] for i in range(n-1))
    if strictly_inc:
        assert output == 'Poor Alex\n'

def test_happy_implies_existence(run, x):
    output = run(x)
    if output.strip() == 'Happy Alex':
        lines = x.strip().split('\n')
        n = int(lines[0])
        pairs = []
        for i in range(1, n+1):
            a, b = map(int, lines[i].split())
            pairs.append((a,b))
        happy = False
        for i in range(n):
            for j in range(n):
                if i == j: continue
                if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                    happy = True
                    break
            if happy:
                break
        assert happy, 'Output says Happy Alex but no inversion found'

def test_poor_implies_no_inversion(run, x):
    output = run(x)
    if output.strip() == 'Poor Alex':
        lines = x.strip().split('\n')
        n = int(lines[0])
        pairs = []
        for i in range(1, n+1):
            a, b = map(int, lines[i].split())
            pairs.append((a,b))
        happy = False
        for i in range(n):
            for j in range(n):
                if i == j: continue
                if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                    happy = True
                    break
            if happy:
                break
        assert not happy, 'Output says Poor Alex but an inversion exists'

def test_sorted_linear_oracle(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    pairs.sort(key=lambda p: p[0])
    happy = False
    for i in range(n-1):
        if pairs[i][1] > pairs[i+1][1]:
            happy = True
            break
    assert output in ('Happy Alex\n', 'Poor Alex\n')
    assert (output == 'Happy Alex\n') == happy

def test_two_oracles_agree(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    # brute force oracle
    happy_bf = False
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if pairs[i][0] < pairs[j][0] and pairs[i][1] > pairs[j][1]:
                happy_bf = True
                break
        if happy_bf:
            break
    # sorted linear oracle
    pairs_sorted = sorted(pairs, key=lambda p: p[0])
    happy_sorted = False
    for i in range(n-1):
        if pairs_sorted[i][1] > pairs_sorted[i+1][1]:
            happy_sorted = True
            break
    assert happy_bf == happy_sorted
    assert output in ('Happy Alex\n', 'Poor Alex\n')
    assert (output == 'Happy Alex\n') == happy_bf

