    perms = [list(map(int, line.split())) for line in lines[1:1+k]]
    pos = [ {val: idx for idx, val in enumerate(perm)} for perm in perms ]
    minimal = []
    for i in range(1, n+1):
        is_minimal = True
        for j in range(1, n+1):
            if i == j:
                continue
            all_before = True
            for p in pos:
                if p[j] >= p[i]:
                    all_before = False
                    break
            if all_before:
                is_minimal = False
                break
