tests_src:
def test_output_is_integer(run, x):
    out = run(x)
    assert out.endswith('\n')
    num_str = out.strip()
    assert num_str.isdigit()

def test_output_nonnegative(run, x):
    out = run(x)
    num = int(out.strip())
    assert num >= 0

def test_output_at_most_len_t_minus_1(run, x):
    data = x.strip().split('\n')
    if len(data) < 2:
        t = ''
    else:
        t = data[1]
    out = run(x)
    num = int(out.strip())
    assert num <= len(t) - 1

def test_if_s_not_subsequence_then_zero(run, x):
    data = x.strip().split('\n')
    s = data[0]
    t = data[1] if len(data) > 1 else ''
    def is_subseq(s, t):
        i = 0
        for ch in t:
            if i < len(s) and ch == s[i]:
                i += 1
        return i == len(s)
    out = run(x)
    if not is_subseq(s, t):
        assert out.strip() == '0'

def test_brute_force_oracle(run, x):
    data = x.strip().split('\n')
    s = data[0]
    t = data[1] if len(data) > 1 else ''
    def is_subseq(s, part):
        i = 0
        for ch in part:
            if i < len(s) and ch == s[i]:
                i += 1
        return i == len(s)
    count = 0
    for k in range(1, len(t)):
        left = t[:k]
        right = t[k:]
        if is_subseq(s, left) and is_subseq(s, right):
            count += 1
    out = run(x)
    assert int(out.strip()) == count

def test_greedy_formula(run, x):
    data = x.strip().split('\n')
    s = data[0]
    t = data[1] if len(data) > 1 else ''
    pos = 0
    e = -1
    for i, ch in enumerate(t):
        if pos < len(s) and ch == s[pos]:
            pos += 1
            if pos == len(s):
                e = i
                break
    pos = len(s) - 1
    R = -1
    for i in range(len(t)-1, -1, -1):
        if pos >= 0 and t[i] == s[pos]:
            pos -= 1
            if pos == -1:
                R = i
                break
    expected = max(0, R - e) if e != -1 and R != -1 else 0
    out = run(x)
    assert int(out.strip()) == expected

def test_output_consistent_with_examples(run, x):
    out = run(x)
    if x == "aba\nbaobababbah\n":
        assert out == "2\n"
    elif x == "mars\nsunvenusearthmarsjupitersaturnuranusneptune\n":
        assert out == "0\n"

def test_output_no_extra_whitespace(run, x):
    out = run(x)
    assert out.endswith('\n')
    line = out.strip()
    assert line.isdigit()
    assert out == line + '\n'

def test_single_character_s(run, x):
    data = x.strip().split('\n')
    s = data[0]
    t = data[1] if len(data) > 1 else ''
    if len(s) == 1:
        first = t.find(s)
        last = t.rfind(s)
        if first == -1:
            expected = 0
        else:
            expected = max(0, last - first)
        out = run(x)
        assert int(out.strip()) == expected

def test_existence_of_valid_split_if_output_positive(run, x):
    out = run(x)
    num = int(out.strip())
    if num > 0:
        data = x.strip().split('\n')
        s = data[0]
        t = data[1] if len(data) > 1 else ''
        pos = 0
        e = -1
        for i, ch in enumerate(t):
            if pos < len(s) and ch == s[pos]:
                pos += 1
                if pos == len(s):
                    e = i
                    break
        pos = len(s) - 1
        R = -1
        for i in range(len(t)-1, -1, -1):
            if pos >= 0 and t[i] == s[pos]:
                pos -= 1
                if pos == -1:
                    R = i
                    break
        assert e != -1 and R != -1
        assert e < R
        k = e + 1
        left = t[:k]
        right = t[k:]
        def is_subseq(s, part):
            i = 0
            for ch in part:
                if i < len(s) and ch == s[i]:
                    i += 1
            return i == len(s)
        assert is_subseq(s, left)
        assert is_subseq(s, right)

def test_correct_via_cumulative(run, x):
    lines = x.strip().split()
    if not lines:
        return
    it = iter(lines)
    n = int(next(it))
    m = int(next(it))
    arr = [int(next(it)) for _ in range(n)]
    if not (1 <= n <= 200000 and 1 <= m <= 10**9 and all(1 <= ai <= 10**9 for ai in arr)):
        return
    output = run(x)
    out_tokens = output.split()
    if len(out_tokens) != n:
        assert False, f"Expected {n} numbers, got {len(out_tokens)}"
    t = list(map(int, out_tokens))
    cum = 0
    prev_turns = 0
    for i in range(n):
        cum += arr[i]
        expected_ti = cum // m - prev_turns
        prev_turns = cum // m
        if t[i] != expected_ti:
            assert False, f"Day {i+1}: expected {expected_ti}, got {t[i]}"


