def test_small_total_simulation(run, x):
    lines = x.strip().split()
    if not lines:
        return
    it = iter(lines)
    n = int(next(it))
    m = int(next(it))
    arr = [int(next(it)) for _ in range(n)]
    if not (1 <= n <= 200000 and 1 <= m <= 10**9 and all(1 <= ai <= 10**9 for ai in arr)):
        return
    total_names = sum(arr)
    if total_names > 2000:
        return
    output = run(x)
    t = list(map(int, output.split()))
    if len(t) != n:
        return
    current_page = 1
    remaining_on_page = m
    computed_t = []
    for day in range(n):
        turns_today = 0
        names_today = arr[day]
        while names_today > 0:
            if remaining_on_page == 0:
                current_page += 1
                remaining_on_page = m
            can_write = min(names_today, remaining_on_page)
            names_today -= can_write
            remaining_on_page -= can_write
            if remaining_on_page == 0:
                current_page += 1
                remaining_on_page = m
                turns_today += 1
        computed_t.append(turns_today)
    for i in range(n):
        if t[i] != computed_t[i]:
            assert False, f"Day {i+1}: simulated turns {computed_t[i]}, output {t[i]}"


