def test_n_lines(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    sizes = list(map(int, lines[1].split()))
    if len(sizes) != n or set(sizes) != set(range(1, n+1)):
        return
    out = run(x)
    out_lines = out.splitlines()
    assert len(out_lines) == n

def test_all_numbers(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    sizes = list(map(int, lines[1].split()))
    if len(sizes) != n or set(sizes) != set(range(1, n+1)):
        return
    out = run(x)
    numbers = []
    for line in out.splitlines():
        for token in line.split():
            numbers.append(int(token))
    numbers.sort()
    assert numbers == list(range(1, n+1))

def test_consecutive_placement(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    n = int(lines[0].strip())
    sizes = list(map(int, lines[1].split()))
    if len(sizes) != n or set(sizes) != set(range(1, n+1)):
        return
    out = run(x)
    out_lines = out.splitlines()
    for line in out_lines:
        tokens = line.split()
        if not tokens:
            continue
        nums = list(map(int, tokens))
        for i in range(len(nums)-1):
            assert nums[i] == nums[i+1] + 1

