def test_bruteforce(run, x):
    import sys
    MOD = 10**9+7
    data = x.strip().split()
    if not data:
        return
    n = int(data[0])
    if n > 10:
        return
    a = list(map(int, data[1:1+n]))
    total = 0
    for mask in range(1<<n):
        adj = [[] for _ in range(n)]
        for i in range(n):
            if mask & (1<<i):
                src = a[i]-1
                dst = i
            else:
                src = i
                dst = a[i]-1
            adj[src].append(dst)
        visited = [0]*n
        cycle = False
        def dfs(u):
            nonlocal cycle
            if cycle:
                return
            visited[u] = 1
            for v in adj[u]:
                if visited[v] == 1:
                    cycle = True
                    return
                elif visited[v] == 0:
                    dfs(v)
            visited[u] = 2
        for u in range(n):
            if visited[u] == 0:
                dfs(u)
                if cycle:
                    break
        if not cycle:
            total += 1
    expected = total % MOD
    out = run(x).strip()
    assert int(out) == expected

def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split()
    assert len(lines) == 1
    int(lines[0])

def test_mod_range(run, x):
    MOD = 10**9+7
    out = run(x).strip()
    ans = int(out)
    assert 0 <= ans < MOD

def test_example1(run, x):
    if x == "3\n2 3 1\n":
        out = run(x).strip()
        assert out == "6"

def test_example2(run, x):
    if x == "4\n2 1 1 1\n":
        out = run(x).strip()
        assert out == "8"

def test_example3(run, x):
    if x == "5\n2 4 2 5 3\n":
        out = run(x).strip()
        assert out == "28"

def test_single_cycle(run, x):
    MOD = 10**9+7
    data = x.strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if len(set(a)) != n:
        return
    visited = set()
    cur = 1
    while cur not in visited:
        visited.add(cur)
        cur = a[cur-1]
    if len(visited) == n and cur == 1:
        expected = (pow(2, n, MOD) - 2) % MOD
        out = run(x).strip()
        assert int(out) == expected

def test_permutation(run, x):
    MOD = 10**9+7
    data = x.strip().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))
    if len(set(a)) != n:
        return
    visited = [False]*n
    cycles = []
    for i in range(n):
        if not visited[i]:
            cnt = 0
            j = i
            while not visited[j]:
                visited[j] = True
                j = a[j]-1
                cnt += 1
            cycles.append(cnt)
    expected = 1
    for L in cycles:
