def test_small_dp(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    if not lines:
        return
    N = int(lines[0].strip())
    if N > 30:
        return
    prices = list(map(int, ' '.join(lines[1:]).split()))
    if len(prices) < N:
        prices += [0] * (N - len(prices))
    else:
        prices = prices[:N]
    INF_NEG = -10**18
    dp = [[INF_NEG] * (N + 1) for _ in range(N + 1)]
    dp[0][0] = 0
    for i in range(N):
        p = prices[i]
        for k in range(N + 1):
            cur = dp[i][k]
            if cur == INF_NEG:
                continue
            if dp[i + 1][k] < cur:
                dp[i + 1][k] = cur
            if k < N:
                buy = cur - p
                if dp[i + 1][k + 1] < buy:
                    dp[i + 1][k + 1] = buy
            if k > 0:
                sell = cur + p
                if dp[i + 1][k - 1] < sell:
                    dp[i + 1][k - 1] = sell
    optimal = dp[N][0]
    profit = int(out.strip())
    assert profit == optimal

