def test_lower_bound_unconstrained(run, x):
    out = run(x)
    out_lines = out.strip().split('\n')
    out_val = out_lines[0].strip() if out_lines else ''
    if out_val == "-1":
        return
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n, m = map(int, lines[0].split())
    x_val, k, y_val = map(int, lines[1].split())
    deletions = n - m
    cost_all_berserk = deletions * y_val
    f = deletions // k
    r = deletions % k
    cost_mix = f * x_val + r * y_val
    lower_bound = min(cost_all_berserk, cost_mix)
    ans = int(out_val)
    assert ans >= lower_bound, f"Answer {ans} is less than unconstrained lower bound {lower_bound}"


def test_small_bruteforce(run, x):
    out = run(x)
    out_lines = out.strip().split('\n')
    out_val = out_lines[0].strip() if out_lines else ''
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n, m = map(int, lines[0].split())
    x_val, k, y_val = map(int, lines[1].split())
    a = list(map(int, lines[2].split()))
    b = list(map(int, lines[3].split())) if m > 0 else []
    if n > 6:
        return
    import heapq
    def min_cost_brute(a, b, x_val, k, y_val):
        start = tuple(a)
        target = tuple(b)
        dist = {start: 0}
        pq = [(0, start)]
        while pq:
            d, state = heapq.heappop(pq)
            if d != dist[state]:
                continue
            if state == target:
                return d
            L = len(state)
            if L >= k:
                for i in range(L - k + 1):
                    new_state = state[:i] + state[i+k:]
                    nd = d + x_val
                    if new_state not in dist or nd < dist[new_state]:
                        dist[new_state] = nd
                        heapq.heappush(pq, (nd, new_state))
            if L >= 2:
                for i in range(L-1):
                    left = state[i]
                    right = state[i+1]
                    keep = left if left > right else right
                    new_state = state[:i] + (keep,) + state[i+2:]
                    nd = d + y_val
                    if new_state not in dist or nd < dist[new_state]:
                        dist[new_state] = nd
                        heapq.heappush(pq, (nd, new_state))
        return -1
    correct = min_cost_brute(a, b, x_val, k, y_val)
    assert out_val == str(correct), f"For small input, expected {correct}, got {out_val}"


