def test_impossible_segment(run, x):
    out = run(x)
    out_lines = out.strip().split('\n')
    out_val = out_lines[0].strip() if out_lines else ''
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n, m = map(int, lines[0].split())
    x_val, k, y_val = map(int, lines[1].split())
    a = list(map(int, lines[2].split()))
    b = list(map(int, lines[3].split())) if m > 0 else []
    i = 0
    for v in a:
        if i < len(b) and v == b[i]:
            i += 1
    if i != len(b):
        return
    idx = 0
    match_indices = []
    for v in b:
        while idx < n and a[idx] != v:
            idx += 1
        if idx == n:
            return
        match_indices.append(idx)
        idx += 1
    segments = []
    prev = -1
    for pos in match_indices:
        if prev + 1 <= pos - 1:
            segments.append((prev, pos))
        prev = pos
    if prev + 1 <= n - 1:
        segments.append((prev, n))
    impossible = False
    for left_idx, right_idx in segments:
        L = right_idx - left_idx - 1
        if L <= 0:
            continue
        segment_a = a[left_idx+1:right_idx]
        max_val = max(segment_a)
        left_boundary = a[left_idx] if left_idx >= 0 else 0
        right_boundary = a[right_idx] if right_idx < n else 0
        boundary_max = max(left_boundary, right_boundary)
        if max_val > boundary_max and L < k:
            impossible = True
            break
    if impossible:
        assert out_val == "-1", f"Segment impossible but output is {out_val}, expected -1"


def test_segment_lower_bound(run, x):
    out = run(x)
    out_lines = out.strip().split('\n')
    out_val = out_lines[0].strip() if out_lines else ''
    if out_val == "-1":
        return
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n, m = map(int, lines[0].split())
    x_val, k, y_val = map(int, lines[1].split())
    a = list(map(int, lines[2].split()))
    b = list(map(int, lines[3].split())) if m > 0 else []
    i = 0
    for v in a:
        if i < len(b) and v == b[i]:
            i += 1
    if i != len(b):
        return
    idx = 0
    match_indices = []
    for v in b:
        while idx < n and a[idx] != v:
            idx += 1
        if idx == n:
            return
        match_indices.append(idx)
        idx += 1
    segments = []
    prev = -1
    for pos in match_indices:
        if prev + 1 <= pos - 1:
            segments.append((prev, pos))
        prev = pos
    if prev + 1 <= n - 1:
        segments.append((prev, n))
    total_lower = 0
    for left_idx, right_idx in segments:
        L = right_idx - left_idx - 1
        if L == 0:
            continue
        segment_a = a[left_idx+1:right_idx]
        max_val = max(segment_a)
        left_boundary = a[left_idx] if left_idx >= 0 else 0
        right_boundary = a[right_idx] if right_idx < n else 0
        boundary_max = max(left_boundary, right_boundary)
        if max_val < boundary_max:
            lower = min(L * y_val, (L // k) * x_val + (L % k) * y_val)
        else:
            if L < k:
                lower = 0
            else:
                if x_val - k * y_val > 0:
                    lower = x_val + (L - k) * y_val
                else:
                    lower = (L // k) * x_val + (L % k) * y_val
        total_lower += lower
    ans = int(out_val)
    assert ans >= total_lower, f"Answer {ans} is less than segment lower bound {total_lower}"

