def test_upper_bound(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 4:
        return
    try:
        k1, k2, k3 = map(int, lines[0].split())
    except:
        return
    n = k1 + k2 + k3
    nums = []
    for i in range(1, 4):
        part = lines[i].strip()
        if part:
            nums.extend(map(int, part.split()))
    if len(nums) != n:
        return
    if set(nums) != set(range(1, n + 1)):
        return
    owner = [-1] * n
    if lines[1].strip():
        for num in map(int, lines[1].split()):
            owner[num - 1] = 0
    if lines[2].strip():
        for num in map(int, lines[2].split()):
            owner[num - 1] = 1
    if lines[3].strip():
        for num in map(int, lines[3].split()):
            owner[num - 1] = 2
    if -1 in owner:
        return
    from collections import Counter
    cnt = Counter(owner)
    maxcnt = max(cnt[0], cnt[1], cnt[2])
    out = run(x)
    ans = int(out.strip())
    assert ans <= n - maxcnt

