def test_brute_force_oracle(run, x):
    import itertools
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    if n > 8:
        return
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    total = 0
    for perm in itertools.permutations(range(n)):
        a_seq = [pairs[i][0] for i in perm]
        b_seq = [pairs[i][1] for i in perm]
        sorted_a = all(a_seq[i] <= a_seq[i+1] for i in range(n-1))
        sorted_b = all(b_seq[i] <= b_seq[i+1] for i in range(n-1))
        if not (sorted_a or sorted_b):
            total += 1
    total %= 998244353
    out = run(x).strip()
    assert int(out) == total

def test_answer_in_range(run, x):
    out = run(x).strip()
    val = int(out)
    assert 0 <= val < 998244353

def test_all_identical_zero(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    if all(p == pairs[0] for p in pairs):
        out = run(x).strip()
        assert out == '0'

def test_example1(run, x):
    if x == '3\n1 1\n2 2\n3 1\n':
        out = run(x).strip()
        assert out == '3'

def test_example2(run, x):
    if x == '4\n2 3\n2 2\n2 1\n2 4\n':
        out = run(x).strip()
        assert out == '0'

def test_example3(run, x):
    if x == '3\n1 1\n1 1\n2 3\n':
        out = run(x).strip()
        assert out == '4'

def test_n1_zero(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        out = run(x).strip()
        assert out == '0'

def test_all_a_equal_zero(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    if all(a == pairs[0][0] for a, _ in pairs):
        out = run(x).strip()
        assert out == '0'

def test_all_b_equal_zero(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    pairs = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        pairs.append((a, b))
    if all(b == pairs[0][1] for _, b in pairs):
        out = run(x).strip()
        assert out == '0'

def test_n2_exact(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 2:
        return
    a1, b1 = map(int, lines[1].split())
    a2, b2 = map(int, lines[2].split())
    original_good = (a1 > a2) and (b1 > b2)
    swapped_good = (a2 > a1) and (b2 > b1)
    count = 0
    if original_good:
        count += 1
    if swapped_good:
        count += 1
    out = run(x).strip()
    assert int(out) == count

