def test_bruteforce_small(run, x):
    import sys
    sys.setrecursionlimit(10000)
    data = list(map(int, x.split()))
    if not data:
        return
    t = data[0]
    pos = 1
    outputs = run(x).splitlines()
    for case in range(t):
        n = data[pos]; special = data[pos+1]; pos += 2
        if n > 13:  # skip large inputs (not present in given list)
            pos += 2*(n-1)
            continue
        adj = [[] for _ in range(n)]
        for i in range(n-1):
            u = data[pos]-1; v = data[pos+1]-1; pos += 2
            adj[u].append(v); adj[v].append(u)
        special_idx = special-1
        from functools import lru_cache
        @lru_cache(None)
        def win(mask, turn):
            if not (mask & (1<<special_idx)):
                return True  # shouldn't be called
            def is_leaf(mask, node):
                cnt = 0
                for nb in adj[node]:
                    if mask & (1<<nb):
                        cnt += 1
                        if cnt > 1:
                            return False
                return cnt <= 1
            if is_leaf(mask, special_idx):
                return (turn == 0)
            moves = []
            for i in range(n):
                if i == special_idx: continue
                if (mask>>i)&1 and is_leaf(mask, i):
                    moves.append(mask & ~(1<<i))
            if turn == 0:
                for newmask in moves:
                    if win(newmask, 1):
                        return True
                return False
            else:
                for newmask in moves:
                    if not win(newmask, 0):
                        return False
                return True
        start = (1<<n)-1
        expected = win(start, 0)
        expected_str = "Ayush" if expected else "Ashish"
        assert outputs[case] == expected_str, f"Case {case+1}: expected {expected_str}, got {outputs[case]}"

