def test_data_insufficient_iff_multi(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    if not lines:
        return
    hq = lines[0].split()
    if len(hq) < 2:
        return
    h = int(hq[0])
    q = int(hq[1])
    questions = []
    valid = True
    for j in range(1, q+1):
        if j >= len(lines):
            break
        parts = lines[j].split()
        if len(parts) < 4:
            valid = False
            break
        i, L, R, ans = map(int, parts)
        if not (1 <= i <= h):
            valid = False
            break
        if not (2**(i-1) <= L <= R <= 2**i - 1):
            valid = False
            break
        questions.append((i, L, R, ans))
    if not valid:
        return
    low_all = 2**(h-1)
    high_all = 2**h - 1
    intervals = [(low_all, high_all)]
    for i, L, R, ans in questions:
        offset = 1 << (h - i)
        cond_low = L * offset
        cond_high = (R + 1) * offset - 1
        new_intervals = []
        if ans == 1:
            for lo, hi in intervals:
                inter_lo = max(lo, cond_low)
                inter_hi = min(hi, cond_high)
                if inter_lo <= inter_hi:
                    new_intervals.append((inter_lo, inter_hi))
        else:
            for lo, hi in intervals:
                if hi < cond_low:
                    new_intervals.append((lo, hi))
                elif lo > cond_high:
