def test_correct_expansion(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    n = int(lines[0].strip())
    shorts = []
    for i in range(1, n + 1):
        shorts.append(lines[i].strip())
    output = run(x)
    out_lines = output.strip().splitlines()
    assert len(out_lines) >= n, f"Expected at least {n} lines, got {len(out_lines)}"
    for i in range(n):
        short = shorts[i]
        full = out_lines[i].strip()
        if "::" in short:
            left, right = short.split("::")
            left_blocks = [] if left == "" else left.split(":")
            right_blocks = [] if right == "" else right.split(":")
            num = len(left_blocks) + len(right_blocks)
            zero_needed = 8 - num
            blocks = []
            for b in left_blocks:
                blocks.append(b.zfill(4))
            for _ in range(zero_needed):
                blocks.append("0000")
            for b in right_blocks:
                blocks.append(b.zfill(4))
            expected = ":".join(blocks)
        else:
            blocks = short.split(":")
            blocks = [b.zfill(4) for b in blocks]
            expected = ":".join(blocks)
        assert full == expected, f"Line {i+1}: expected {expected}, got {full}"

def test_block_count(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        blocks = line.split(':')
        assert len(blocks) == 8, f"Block count is {len(blocks)}, expected 8 in line: {line}"

def test_block_length(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        blocks = line.split(':')
        for b in blocks:
            assert len(b) == 4, f"Block length is {len(b)}, expected 4 in block: {b}"

def test_hex_digits(run, x):
    hex_digits = set('0123456789abcdefABCDEF')
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        blocks = line.split(':')
        for b in blocks:
            for ch in b:
                assert ch in hex_digits, f"Invalid character {ch} in block {b}"

def test_colon_count(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        assert line.count(':') == 7, f"Colon count is {line.count(':')}, expected 7 in line: {line}"

def test_no_empty_blocks(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        blocks = line.split(':')
        for b in blocks:
            assert b != "", f"Empty block in line: {line}"

def test_no_double_colon(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        assert "::" not in line, f"Double colon found in line: {line}"

def test_output_lines_count(run, x):
    lines_input = x.strip().splitlines()
    if not lines_input:
        return
    n = int(lines_input[0].strip())
    output = run(x)
    lines_output = output.strip().splitlines()
    lines_output = [l for l in lines_output if l.strip() != ""]
    assert len(lines_output) == n, f"Expected {n} output lines, got {len(lines_output)}"

def test_no_edge_colons(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        assert line[0] != ':' and line[-1] != ':', f"Line starts or ends with colon: {line}"

def test_total_hex_length(run, x):
    output = run(x)
    lines = output.strip().splitlines()
    for line in lines:
        hex_part = line.replace(':', '')
        assert len(hex_part) == 32, f"Total hex digits length is {len(hex_part)}, expected 32 in line: {line}"

