        def block_match(sb, fb):
            return fb == sb.zfill(4)
        if '::' in short:
            left_right = short.split('::', 1)
            left_str = left_right[0]
            right_str = left_right[1]
            left_blocks = left_str.split(':') if left_str else []
            right_blocks = right_str.split(':') if right_str else []
            present = left_blocks + right_blocks
            gap = 8 - len(present)
            assert gap >= 1
            full_blocks = full.split(':')
            assert len(full_blocks) == 8
            for i, sb in enumerate(left_blocks):
                assert block_match(sb, full_blocks[i])
            gap_start = len(left_blocks)
            for i in range(gap_start, gap_start + gap):
