def test_direct_oracle(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    first = lines[0].split()
    if len(first) < 2:
        return
    n = int(first[0]); m = int(first[1])
    a = [list(line.strip()) for line in lines[1:1+n]]
    count = [0]*m
    for i in range(n):
        for j in range(m):
            if a[i][j] == '1':
                count[j] += 1
    correct = "NO"
    for i in range(n):
        good = True
        for j in range(m):
            if count[j] == 1 and a[i][j] == '1':
                good = False
                break
        if good:
            correct = "YES"
            break
    output = run(x).strip()
    assert output == correct, f"Expected {correct}, got {output}"

