def test_format(run, x):
    output = run(x)
    assert output in ("Yes\n", "No\n")

def test_divisible_by_a_or_b(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if c % a == 0 or c % b == 0:
        assert output == "Yes\n"

def test_smaller_than_both(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if c < a and c < b:
        assert output == "No\n"

def test_gcd_not_divisible(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    g = math.gcd(a, b)
    output = run(x)
    if c % g != 0:
        assert output == "No\n"

def test_a1_or_b1(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if a == 1 or b == 1:
        assert output == "Yes\n"

def test_c_equals_a_or_b(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if c == a or c == b:
        assert output == "Yes\n"

def test_bruteforce_small(run, x):
    a, b, c = map(int, x.strip().split())
    if c > 200:
        return
    output = run(x)
    possible = False
    for xc in range(c // a + 1):
        if (c - a * xc) % b == 0:
            possible = True
            break
    expected = "Yes\n" if possible else "No\n"
    assert output == expected

def test_yes_implies_divisible(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if output == "Yes\n":
        g = math.gcd(a, b)
        assert c % g == 0

def test_a_equal_b(run, x):
    a, b, c = map(int, x.strip().split())
    output = run(x)
    if a == b:
        expected = "Yes\n" if c % a == 0 else "No\n"
        assert output == expected

def test_full_oracle(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    output = run(x)
    g = math.gcd(a, b)
    if c % g != 0:
        expected = False
    else:
        a1, b1, c1 = a // g, b // g, c // g
        if c1 > a1 * b1 - a1 - b1:
            expected = True
        else:
            found = False
            for xc in range(b1):
                if (c1 - a1 * xc) % b1 == 0 and c1 - a1 * xc >= 0:
                    found = True
                    break
            expected = found
    expected_output = "Yes\n" if expected else "No\n"
    assert output == expected_output

