def test_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), f'Invalid output format: {repr(out)}'

def test_divisible_by_a(run, x):
    a, b, c = map(int, x.split())
    out = run(x)
    if c % a == 0:
        assert out.strip() == 'Yes', f'c divisible by a={a}, expected Yes, got {out}'

def test_divisible_by_b(run, x):
    a, b, c = map(int, x.split())
    out = run(x)
    if c % b == 0:
        assert out.strip() == 'Yes', f'c divisible by b={b}, expected Yes, got {out}'

def test_yes_implies_gcd(run, x):
    import math
    a, b, c = map(int, x.split())
    out = run(x)
    if out.strip() == 'Yes':
        assert c % math.gcd(a, b) == 0, f'Output Yes but c not divisible by gcd({a},{b})'

def test_no_implies_not_divisible_by_a_or_b(run, x):
    a, b, c = map(int, x.split())
    out = run(x)
    if out.strip() == 'No':
        assert c % a != 0, f'Output No but c divisible by a={a}'
        assert c % b != 0, f'Output No but c divisible by b={b}'

def test_sufficient_frobenius(run, x):
    import math
    a, b, c = map(int, x.split())
    out = run(x)
    d = math.gcd(a, b)
    if c % d == 0:
        a1, b1, c1 = a // d, b // d, c // d
        if c1 >= (a1 - 1) * (b1 - 1):
            assert out.strip() == 'Yes', f'Frobenius sufficient condition requires Yes, got {out}'

def test_small_c(run, x):
    a, b, c = map(int, x.split())
    out = run(x)
    if 0 < c < min(a, b):
        assert out.strip() == 'No', f'c={c} < min(a,b)={min(a,b)}, expected No, got {out}'

def test_brute_force_yes(run, x):
    a, b, c = map(int, x.split())
    out = run(x)
    if out.strip() == 'Yes':
        found = False
        for x_val in range(c // a + 1):
            if (c - a * x_val) % b == 0:
                y_val = (c - a * x_val) // b
                if y_val >= 0:
                    found = True
                    break
        assert found, f'Output Yes but no non‑negative solution found for {a}*x + {b}*y = {c}'

def test_brute_force_no(run, x):
    a, b, c = map(int, x.split())
    out = run(x)
    if out.strip() == 'No':
        for x_val in range(c // a + 1):
            if (c - a * x_val) % b == 0:
                y_val = (c - a * x_val) // b
                if y_val >= 0:
                    assert False, f'Output No but solution exists: x={x_val}, y={y_val}'

def test_gcd_necessary(run, x):
    import math
    a, b, c = map(int, x.split())
    out = run(x)
    if c % math.gcd(a, b) != 0:
        assert out.strip() == 'No', f'c not divisible by gcd, expected No, got {out}'

