def test_format(run, x):
    out = run(x)
    out_stripped = out.strip()
    assert out_stripped in ("sjfnb", "cslnb"), f"Output must be 'sjfnb' or 'cslnb', got {out!r}"


def test_example1(run, x):
    if x == "1\n0\n":
        out = run(x).strip()
        assert out == "cslnb", f"For example 1, expected 'cslnb', got {out}"


def test_example2(run, x):
    if x == "2\n1 0\n":
        out = run(x).strip()
        assert out == "cslnb", f"For example 2, expected 'cslnb', got {out}"


def test_example3(run, x):
    if x == "2\n2 2\n":
        out = run(x).strip()
        assert out == "sjfnb", f"For example 3, expected 'sjfnb', got {out}"


def test_example4(run, x):
    if x == "3\n2 3 1\n":
        out = run(x).strip()
        assert out == "sjfnb", f"For example 4, expected 'sjfnb', got {out}"


def test_two_zeros_lose(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if a.count(0) >= 2:
        out = run(x).strip()
        assert out == "cslnb", f"Input has at least two zeros, must output 'cslnb', got {out}"


def test_duplicate_pair_with_minus_one_lose(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    from collections import Counter
    cnt = Counter(a)
    duplicate_values = [v for v, c in cnt.items() if c == 2]
    if len(duplicate_values) == 1:
        v = duplicate_values[0]
        if v > 0 and (v-1) in cnt:
            out = run(x).strip()
            assert out == "cslnb", f"Input has duplicate pair {v} and {v-1} present, must output 'cslnb', got {out}"


def test_sorted_0_to_n_minus_1_lose(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if sorted(a) != list(range(n)):
        return
    out = run(x).strip()
    assert out == "cslnb", f"For sorted 0..{n-1}, expected 'cslnb', got {out}"


def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n > 5 or max(a) > 5:
        return
    from functools import lru_cache
    @lru_cache(None)
    def win(state):
        if all(v == 0 for v in state):
            return False
        n_ = len(state)
        for i in range(n_):
            if state[i] == 0:
                continue
            new_list = list(state)
            new_list[i] -= 1
            new_state = tuple(sorted(new_list))
            if len(set(new_state)) == n_:
                if not win(new_state):
                    return True
        return False
    initial = tuple(sorted(a))
    expected = "sjfnb" if win(initial) else "cslnb"
    out = run(x).strip()
    assert out == expected, f"For input {x}, brute-force expects {expected}, got {out}"


def test_large_distinct_odd(run, x):
    if x != "3\n0 100000001 1\n":
        return
    out = run(x).strip()
    # Distinct values, minimal set [0,1,2]; extra stones odd => first player wins.
    assert out == "sjfnb", f"For input {x}, expected 'sjfnb', got {out}"

def test_output_format(run, x):
    out = run(x)
    assert out in ("YES\n", "NO\n"), f"Invalid output format: {repr(out)}"


def test_character_parity(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().splitlines()
        H, W = map(int, lines[0].split())
        from collections import Counter
        cnt = Counter()
        for line in lines[1:1+H]:
            cnt.update(line.strip())
        total = H*W
        odd_count = sum(1 for v in cnt.values() if v%2==1)
        if total % 2 == 0:
            assert odd_count == 0, f"Even total cells but odd character count: {odd_count}"
        else:
            assert odd_count <= 1, f"Odd total cells but odd character count >1: {odd_count}"


def test_row_multiset_pairing(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().splitlines()
        H, W = map(int, lines[0].split())
        from collections import Counter
        rows = [line.strip() for line in lines[1:1+H]]
        row_counters = [Counter(row) for row in rows]
        used = [False]*H
        for i in range(H):
            if used[i]: continue
            for j in range(i+1, H):
                if used[j]: continue
                if row_counters[i] == row_counters[j]:
                    used[i] = used[j] = True
                    break
        unpaired = sum(1 for u in used if not u)
        if H % 2 == 0:
            assert unpaired == 0, f"Even rows but {unpaired} unpaired rows"
        else:
            assert unpaired == 1, f"Odd rows but {unpaired} unpaired rows (expected 1)"
            unpaired_idx = next(i for i, u in enumerate(used) if not u)
            odd_counts = sum(1 for v in row_counters[unpaired_idx].values() if v % 2 == 1)
            assert odd_counts <= 1, f"Unpaired row {rows[unpaired_idx]} has {odd_counts} odd-count letters, cannot be palindrome"


def test_column_multiset_pairing(run, x):
    out = run(x).strip()
    if out == "YES":
        lines = x.strip().splitlines()
        H, W = map(int, lines[0].split())
        from collections import Counter
        grid = [list(line.strip()) for line in lines[1:1+H]]
        cols = [''.join(grid[i][j] for i in range(H)) for j in range(W)]
        col_counters = [Counter(col) for col in cols]
        used = [False]*W
        for i in range(W):
            if used[i]: continue
            for j in range(i+1, W):
                if used[j]: continue
                if col_counters[i] == col_counters[j]:
                    used[i] = used[j] = True
                    break
        unpaired = sum(1 for u in used if not u)
        if W % 2 == 0:
            assert unpaired == 0, f"Even columns but {unpaired} unpaired columns"
        else:
            assert unpaired == 1, f"Odd columns but {unpaired} unpaired columns (expected 1)"
            unpaired_idx = next(i for i, u in enumerate(used) if not u)
            odd_counts = sum(1 for v in col_counters[unpaired_idx].values() if v % 2 == 1)
            assert odd_counts <= 1, f"Unpaired column {cols[unpaired_idx]} has {odd_counts} odd-count letters, cannot be palindrome"


def test_all_same_grid(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    grid = [line.strip() for line in lines[1:1+H]]
    first = grid[0][0]
    all_same = all(cell == first for row in grid for cell in row)
    if all_same:
        out = run(x).strip()
        assert out == "YES", f"All letters same, expected YES but got {out}"


def test_single_row_or_column(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    grid = [line.strip() for line in lines[1:1+H]]
    out = run(x).strip()
    if H == 1 or W == 1:
        seq = ''.join(grid)
        from collections import Counter
        cnt = Counter(seq)
        odd_count = sum(1 for v in cnt.values() if v%2==1)
        can_palindrome = odd_count <= 1
        expected = "YES" if can_palindrome else "NO"
        assert out == expected, f"For 1-row/col grid, expected {expected} but got {out}"


def test_small_bruteforce(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:1+H]]
    out = run(x).strip()
    if H <= 6 and W <= 6:
        import itertools
        rows = list(range(H))
        cols = list(range(W))
        def is_symmetric(row_perm, col_perm):
            for i in range(H):
                for j in range(W):
                    a = grid[row_perm[i]][col_perm[j]]
                    b = grid[row_perm[H-1-i]][col_perm[W-1-j]]
                    if a != b:
                        return False
            return True
        found = False
        for rp in itertools.permutations(rows):
            for cp in itertools.permutations(cols):
                if is_symmetric(rp, cp):
                    found = True
                    break
            if found:
                break
        expected = "YES" if found else "NO"
        assert out == expected, f"Brute-force says {expected} but got {out}"


def test_already_symmetric(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:1+H]]
    symmetric = True
    for i in range(H):
        for j in range(W):
            if grid[i][j] != grid[H-1-i][W-1-j]:
                symmetric = False
                break
        if not symmetric:
            break
    if symmetric:
        out = run(x).strip()
        assert out == "YES", f"Grid is already symmetric, expected YES but got {out}"


def test_2x2_all_distinct(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    if H == 2 and W == 2:
        grid = [list(line.strip()) for line in lines[1:1+H]]
        chars = [grid[0][0], grid[0][1], grid[1][0], grid[1][1]]
        if len(set(chars)) == 4:
            out = run(x).strip()
            assert out == "NO", f"2x2 with all distinct letters must be NO, got {out}"


def test_h2_or_w2(run, x):
    lines = x.strip().splitlines()
    H, W = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:1+H]]
    out = run(x).strip()
    def check_two_rows(a, b):
        from collections import Counter
        pairs = [(a[j], b[j]) for j in range(W)]
        cnt = Counter(pairs)
        unpaired_used = False
        for (x,y), c in list(cnt.items()):
            if x == y:
                if c % 2 == 1:
                    if unpaired_used:
                        return False
                    unpaired_used = True
            else:
                if cnt.get((y,x), 0) != c:
                    return False
        if W % 2 == 0:
            return not unpaired_used
        else:
            return unpaired_used
    if H == 2:
        a = grid[0]
        b = grid[1]
        expected = "YES" if check_two_rows(a, b) else "NO"
        assert out == expected, f"For H=2, expected {expected} but got {out}"
    elif W == 2:
        a = [grid[i][0] for i in range(H)]
        b = [grid[i][1] for i in range(H)]
        expected = "YES" if check_two_rows(a, b) else "NO"
        assert out == expected, f"For W=2, expected {expected} but got {out}"

