def test_small_n_oracle(run, x):
    MOD = 1000000007
    n_str, k_str = x.strip().split()
    n = int(n_str)
    k = int(k_str)
    if n > 10**6:
        return
    def phi(m):
        res = m
        i = 2
        while i * i <= m:
            if m % i == 0:
                while m % i == 0:
                    m //= i
                res -= res // i
            i += 1 if i == 2 else 2
        if m > 1:
            res -= res // m
        return res
    s = (k + 1) // 2
    seq = []
    val = n
    while True:
        seq.append(val)
        if val <= 1:
            break
        val = phi(val)
    t = len(seq) - 1
    if s <= t:
        expected = seq[s]
    else:
        expected = 1
    expected_mod = expected % MOD
    out = run(x)
    assert int(out.strip()) == expected_mod

def test_n_equal_1(run, x):
    n_str, _ = x.strip().split()
    n = int(n_str)
    if n != 1:
        return
    out = run(x)
    assert int(out.strip()) == 1

def test_n_equal_2(run, x):
    n_str, _ = x.strip().split()
    n = int(n_str)
    if n != 2:
        return
    out = run(x)
    assert int(out.strip()) == 1

def test_prime_n_k1(run, x):
    MOD = 1000000007
    n_str, k_str = x.strip().split()
    n = int(n_str)
    k = int(k_str)
    if k != 1 or n > 10**6:
        return
    if n < 2:
        return
    i = 2
    while i * i <= n:
        if n % i == 0:
            return
        i += 1 if i == 2 else 2
    expected = (n - 1) % MOD
    out = run(x)
    assert int(out.strip()) == expected

def test_large_k_leads_to_1(run, x):
    n_str, k_str = x.strip().split()
    n = int(n_str)
    k = int(k_str)
    if n > 10**6:
        return
    def phi_correct(m):
        res = m
        i = 2
        while i * i <= m:
            if m % i == 0:
                while m % i == 0:
                    m //= i
                res -= res // i
            i += 1 if i == 2 else 2
        if m > 1:
            res -= res // m
        return res
    val = n
    t = 0
    while val > 1:
        val = phi_correct(val)
        t += 1
    steps_needed = (k + 1) // 2
    if steps_needed >= t:
        out = run(x)
        assert int(out.strip()) == 1

