        assert out == expected, f"when s=n, expected {expected} got {out}"

def test_digit_sum_matches(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    s = int(lines[1])
    out = run(x).strip()
    if out == "-1":
        return
    b = int(out)
    t = 0
    u = n
    while u:
        t += u % b
        u //= b
    assert t == s, f"digit sum for b={b} is {t}, expected {s}"

def test_b_upper_bound(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    s = int(lines[1])
    out = run(x).strip()
    if out == "-1":
        return
    b = int(out)
    if s != n:
        assert b <= n, f"when s != n, b={b} should be <= n={n}"

def test_minimality_small(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    s = int(lines[1])
    out = run(x).strip()
    if out == "-1":
        return
    b = int(out)
    if b > 1000:
        return
    for b_candidate in range(2, b):
        t = 0
        u = n
        while u:
            t += u % b_candidate
            u //= b_candidate
        if t == s:
            assert False, f"found smaller b={b_candidate} with digit sum {s}"

def test_two_digit_condition(run, x):
    import math
    lines = x.strip().split()
    n = int(lines[0])
    s = int(lines[1])
    out = run(x).strip()
    if out == "-1":
        return
    b = int(out)
    if s == n:
        return
    sqrt_n = math.isqrt(n)
    if b > sqrt_n:
        l = n - s
        if l % (b-1) != 0:
            assert False, f"b-1 does not divide n-s"
        a = l // (b-1)
        c = s - a
        if not (0 <= c < b and a < b):
            assert False, f"two-digit conditions not met: a={a}, c={c}, b={b}"
        if n != a * b + c:
            assert False, f"representation mismatch"

def test_small_n_bruteforce(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    s = int(lines[1])
    if n > 100000:
        return
    if s > n:
        correct = -1
    elif s == n:
        correct = n+1
    else:
        correct = -1
        for b in range(2, n+2):
            t = 0
            u = n
            while u:
                t += u % b
                u //= b
            if t == s:
                correct = b
                break
    out = run(x).strip()
    if out == "-1":
        out_val = -1
    else:
        out_val = int(out)
    assert out_val == correct, f"for n={n}, s={s}, expected {correct}, got {out_val}"

def test_full_correct(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    s = int(lines[1])
    if s > n:
        correct = -1
    elif s == n:
        correct = n+1
    else:
        import math
        sqrt_n = int(math.isqrt(n)) + 1
        ans = None
        for b in range(2, sqrt_n+1):
            t = 0
            u = n
            while u:
                t += u % b
                u //= b
            if t == s:
                ans = b
                break
        if ans is None:
            l = n - s
            for a in range(1, sqrt_n+1):
                if l % a == 0:
                    b_candidate = l // a + 1
                    if b_candidate > max(a, sqrt_n):
                        t = 0
                        u = n
                        while u:
                            t += u % b_candidate
                            u //= b_candidate
                        if t == s:
                            if ans is None or b_candidate < ans:
                                ans = b_candidate
        if ans is None:
            correct = -1
        else:
            correct = ans
    out = run(x).strip()
    if out == "-1":
        out_val = -1
    else:
        out_val = int(out)
    assert out_val == correct, f"correct answer is {correct}, got {out_val}"

def test_b_range(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    s = int(lines[1])
    out = run(x).strip()
    if out == "-1":
        return
    b = int(out)
    assert 2 <= b <= n+1, f"b={b} out of range [2, {n+1}]"

