tests_src:
def test_brute_force(run, x):
    from functools import lru_cache
    lines = x.strip().splitlines()
    if len(lines) < 2:
        n = int(lines[0])
        a = []
    else:
        n = int(lines[0])
        a = list(map(int, lines[1].split()))
    if n > 11:
        return
    vals = sorted(set(a))
    idx = {v: i for i, v in enumerate(vals)}
    freq = [0] * len(vals)
    for val in a:
        freq[idx[val]] += 1
    freq = tuple(freq)
    @lru_cache(None)
    def win(state):
        if sum(state) == 0:
            return False
        for i, cnt in enumerate(state):
            if cnt == 0:
                continue
            new = tuple(0 if j < i else (state[j] - 1 if j == i else state[j]) for j in range(len(state)))
            if not win(new):
                return True
        return False
    expected = "Conan" if win(freq) else "Agasa"
    output = run(x).strip()
    assert output == expected

def test_output_format(run, x):
    output = run(x).strip()
    assert output in {"Conan", "Agasa"}

def test_single_card(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 1:
        assert output == "Conan"

def test_two_equal(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 2:
        a = list(map(int, lines[1].split()))
        if a[0] == a[1]:
            assert output == "Agasa"

def test_three_distinct(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 3:
        a = list(map(int, lines[1].split()))
        if len(set(a)) == 3:
            assert output == "Conan"

def test_all_even_freq(run, x):
    from collections import Counter
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    freq = Counter(a)
    if all(cnt % 2 == 0 for cnt in freq.values()):
        assert output == "Agasa"

def test_any_odd_freq(run, x):
    from collections import Counter
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    freq = Counter(a)
    if any(cnt % 2 == 1 for cnt in freq.values()):
        assert output == "Conan"

def test_examples(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n == 3 and a == [4, 5, 7]:
        assert output == "Conan"
    if n == 2 and a == [1, 1]:
        assert output == "Agasa"

def test_four_equal(run, x):
    output = run(x).strip()
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n == 4:
        a = list(map(int, lines[1].split()))
        if len(set(a)) == 1:
            assert output == "Agasa"

def test_no_extra_output(run, x):
    output = run(x)
    out_stripped = output.strip()
    assert out_stripped in {"Conan", "Agasa"}
    assert output == out_stripped or output == out_stripped + "\n"

