def test_all_equal_odd(run, x):
    lines = x.strip().splitlines()
    nums = list(map(int, lines[1].split()))
    if len(set(nums)) == 1 and len(nums) % 2 == 1:
        out = run(x).strip()
        assert out == "Conan", "When all numbers equal and count odd, Conan must win"

def test_all_equal_even(run, x):
    lines = x.strip().splitlines()
    nums = list(map(int, lines[1].split()))
    if len(set(nums)) == 1 and len(nums) % 2 == 0:
        out = run(x).strip()
        assert out == "Agasa", "When all numbers equal and count even, Agasa must win"

def test_max_unique(run, x):
    lines = x.strip().splitlines()
    nums = list(map(int, lines[1].split()))
    from collections import Counter
    freq = Counter(nums)
    max_val = max(nums)
