def test_full_oracle(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    from functools import lru_cache
    @lru_cache(None)
    def g(m):
        if m == 0:
            return 0
        moves = {g(m-1)}
        if m % 2 == 0:
            if k % 2 == 0:
                moves.add(0)
            else:
                moves.add(g(m//2))
        mex = 0
        while mex in moves:
            mex += 1
        return mex
    xor = 0
    for size in a:
        xor ^= g(size)
    expected = "Kevin" if xor != 0 else "Nicky"
    assert output == expected

def test_output_format(run, x):
    output = run(x)
    stripped = output.strip()
    assert stripped in ("Kevin", "Nicky")

def test_odd_k_a2(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 1 and a[0] == 2:
        assert output == "Nicky"

def test_odd_k_a5(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 1 and a[0] == 5:
        assert output == "Nicky"

def test_odd_k_a1(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 1 and a[0] == 1:
        assert output == "Kevin"

def test_odd_k_a3(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 1 and a[0] == 3:
        assert output == "Kevin"

def test_odd_k_a4(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 1 and a[0] == 4:
        assert output == "Kevin"

def test_even_k_a1(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 0 and a[0] == 1:
        assert output == "Kevin"

def test_even_k_a2(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 0 and a[0] == 2:
        assert output == "Kevin"

def test_even_k_a3(run, x):
    output = run(x).strip()
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n == 1 and k % 2 == 0 and a[0] == 3:
        assert output == "Nicky"

