def test_symmetry(run, x):
    n, l, r = map(int, x.strip().split())
    if not (l >= 1 and r >= l and r - l <= 100000):
        return
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def length(m):
        if m <= 1:
            return 1
        return 2 * length(m // 2) + 1
    L = length(n)
    if r > L:
        return
    @lru_cache(maxsize=None)
    def val(m, pos):
        if m <= 1:
            return m
        half_len = length(m // 2)
        mid = half_len + 1
        if pos < mid:
            return val(m // 2, pos)
        elif pos > mid:
            return val(m // 2, pos - mid)
        else:
            return m % 2
    mirror_l = L - r + 1
    mirror_r = L - l + 1
    mirror_count = 0
    for i in range(mirror_l, mirror_r+1):
        mirror_count += val(n, i)
    output = run(x).strip()
    assert int(output) == mirror_count

