def test_bruteforce_small(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    nk = list(map(int, lines[0].split()))
    if len(nk) < 2:
        return
    n, k = nk[0], nk[1]
    a = list(map(int, lines[1].split()))
    if n > 5:
        return
    from collections import deque
    S = set(a)
    S.add(k)
    start = tuple(a)
    goal = tuple([k] * n)
    visited = set([start])
    q = deque([start])
    while q:
        state = q.popleft()
        if state == goal:
            expected = True
            break
        for l in range(n):
            for r in range(l, n):
                seg = state[l:r + 1]
                m = r - l + 1
                med_idx = (m + 1) // 2 - 1
                median = sorted(seg)[med_idx]
                new_state = state[:l] + (median,) * (m) + state[r + 1:]
                if new_state not in visited:
                    visited.add(new_state)
                    q.append(new_state)
    else:
        expected = False
    out = run(x).strip().lower()
    if expected:
        assert out == 'yes', f"Brute-force says yes but output is {out}"
    else:
        assert out == 'no', f"Brute-force says no but output is {out}"

