def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    if len(first) < 2:
        return
    n, m = map(int, first)
    if n > 8 or m > 8:
        return
    arr = list(map(int, lines[1].split()))
    switches = []
    for i in range(2, 2 + m):
        parts = list(map(int, lines[i].split()))
        switches.append(parts[1:])
    possible = False
    for mask in range(1 << m):
        door_state = arr[:]
        for switch in range(m):
            if mask & (1 << switch):
                for room in switches[switch]:
                    door_state[room - 1] ^= 1
        if all(d == 1 for d in door_state):
            possible = True
            break
    expected = 'YES' if possible else 'NO'
    output = run(x).strip()
    assert output == expected, f'Brute force says {expected}, got {output}'

def test_output_yes_no(run, x):
    output = run(x).strip()
    assert output in ('YES', 'NO'), f'Output must be YES or NO, got {output}'

def test_all_unlocked_implies_yes(run, x):
    lines = x.strip().split('\n')
    arr = list(map(int, lines[1].split()))
    output = run(x).strip()
    if all(v == 1 for v in arr):
        assert output == 'YES', f'All doors initially unlocked, must be YES, got {output}'

def test_inconsistent_duplicate_implies_no(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))
    L = [[] for _ in range(n)]
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        for room in parts[1:]:
            L[room - 1].append(i)
    pair_to_status = {}
    inconsistent = False
    for i in range(n):
        u, v = sorted(L[i])
        key = (u, v)
        if key in pair_to_status:
            if pair_to_status[key] != arr[i]:
                inconsistent = True
                break
        else:
            pair_to_status[key] = arr[i]
    output = run(x).strip()
    if inconsistent:
        assert output == 'NO', f'Inconsistent duplicate pair, must be NO, got {output}'

def test_example1(run, x):
    example1 = '3 3\n1 0 1\n2 1 3\n2 1 2\n2 2 3\n'
    output = run(x).strip()
    if x == example1:
        assert output == 'NO', f'Example1 must be NO, got {output}'

def test_example2(run, x):
    example2 = '3 3\n1 0 1\n3 1 2 3\n1 2\n2 1 3\n'
