    assert len(lines) == 1, f'Output must be exactly one line, got {len(lines)}'

def test_simple_pair(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    if len(first) < 2:
        return
    n, m = map(int, first)
    if n == 2 and m == 2:
        arr = list(map(int, lines[1].split()))
        s1 = list(map(int, lines[2].split()))[1:]
        s2 = list(map(int, lines[3].split()))[1:]
        if set(s1) == {1, 2} and set(s2) == {1, 2}:
            expected = 'YES' if arr[0] == arr[1] else 'NO'
            output = run(x).strip()
            assert output == expected, f'For 2 rooms both controlled by 2 switches, answer should be {expected}, got {output}'

def test_consistency_dfs(run, x):
    lines = x.strip().split('\n')
    first = lines[0].split()
    if len(first) < 2:
        return
    n, m = map(int, first)
    r = list(map(int, lines[1].split()))
    switches_per_door = [[] for _ in range(n)]
    for switch_idx in range(m):
        parts = list(map(int, lines[2 + switch_idx].split()))
        for room in parts[1:]:
            switches_per_door[room - 1].append(switch_idx)
    adj = [[] for _ in range(m)]
    for i in range(n):
        if len(switches_per_door[i]) != 2:
            return
        a, b = switches_per_door[i]
        c = 1 - r[i]
        adj[a].append((b, c))
        adj[b].append((a, c))
    visited = [False] * m
    value = [0] * m
    consistent = True
    for start in range(m):
        if not visited[start]:
            stack = [start]
            visited[start] = True
            value[start] = 0
            while stack:
                u = stack.pop()
                for v, w in adj[u]:
                    expected = value[u] ^ w
                    if not visited[v]:
                        visited[v] = True
                        value[v] = expected
                        stack.append(v)
                    else:
                        if value[v] != expected:
                            consistent = False
                            break
                if not consistent:
                    break
        if not consistent:
            break
    expected = 'YES' if consistent else 'NO'
    output = run(x).strip()
    assert output == expected, f'Consistency DFS says {expected}, got {output}'

