def test_gcd_one(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    if g != 1:
        return
    ans = int(run(x).strip())
    assert ans == 1

def test_gcd_prime(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    if g < 2:
        return
    i = 2
    while i * i <= g:
        if g % i == 0:
            return
        i += 1
    ans = int(run(x).strip())
    assert ans == 2

def test_gcd_square_of_prime(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    if g < 4:
        return
    s = int(math.isqrt(g))
    if s * s != g:
        return
    if s < 2:
        return
    i = 2
    while i * i <= s:
        if s % i == 0:
            return
        i += 1
    ans = int(run(x).strip())
    assert ans == 3

def test_gcd_product_two_distinct_primes(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    if g < 6:
        return
    temp = g
    primes = []
    i = 2
    while i * i <= temp:
        if temp % i == 0:
            primes.append(i)
            while temp % i == 0:
                temp //= i
        i += 1
    if temp > 1:
        primes.append(temp)
    if len(primes) != 2:
        return
    if primes[0] * primes[1] != g:
        return
    ans = int(run(x).strip())
    assert ans == 4

def test_gcd_perfect_square_odd(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    if g <= 0:
        return
    s = int(math.isqrt(g))
    if s * s != g:
        return
    ans = int(run(x).strip())
    assert ans % 2 == 1

def test_gcd_power_of_two(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    if g <= 0:
        return
    if g & (g - 1) != 0:
        return
    k = g.bit_length() - 1
    ans = int(run(x).strip())
    assert ans == k + 1

def test_single_element(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n != 1:
        return
    a = list(map(int, lines[1].split()))
    v = a[0]
    cnt = 0
    i = 1
    while i * i <= v:
        if v % i == 0:
            if v // i == i:
                cnt += 1
            else:
                cnt += 2
        i += 1
    ans = int(run(x).strip())
    assert ans == cnt

def test_all_equal(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n == 0:
        return
    first = a[0]
    for val in a[1:]:
        if val != first:
            return
    v = first
    cnt = 0
    i = 1
    while i * i <= v:
        if v % i == 0:
            if v // i == i:
                cnt += 1
            else:
                cnt += 2
        i += 1
    ans = int(run(x).strip())
    assert ans == cnt

def test_large_numbers(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if not any(v >= 10**9 for v in a):
        return
    g = a[0]
    for v in a[1:]:
        g = math.gcd(g, v)
    cnt = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            if g // i == i:
                cnt += 1
            else:
                cnt += 2
        i += 1
    ans = int(run(x).strip())
    assert ans == cnt

def test_bounds(run, x):
    import math
    lines = x.strip().splitlines()
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    mn = min(a)
