def test_exact_oracle(run, x):
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        best = 1
        i = 1
        while i * i <= n:
            if n % i == 0:
                if i <= k:
                    best = max(best, i)
                if n // i <= k:
                    best = max(best, n // i)
            i += 1
        expected = n // best
        assert p == expected, f"Expected {expected}, got {p}"

