def test_special_prime(run, x):
    def is_prime(num):
        if num < 2:
            return False
        if num % 2 == 0:
            return num == 2
        if num % 3 == 0:
            return num == 3
        i = 5
        w = 2
        while i * i <= num:
            if num % i == 0:
                return False
            i += w
            w = 6 - w
        return True
    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        if is_prime(n) and k < n:
            assert p == n, f"For prime n={n} and k<n, expected {n}, got {p}"

