    lines = x.strip().split()
    if not lines:
        return
    t = int(lines[0])
    pairs = []
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); k = int(lines[idx+1]); idx += 2
        pairs.append((n,k))
    out = run(x)
    outputs = []
    for line in out.strip().split():
        outputs.append(int(line))
    assert len(outputs) == len(pairs)
    for (n,k), p in zip(pairs, outputs):
        if n <= 1000000:
            limit = min(k, n)
            best = 1
            for i in range(limit, 0, -1):
                if n % i == 0:
                    best = i
                    break
            expected = n // best
            assert p == expected, f"For small n, expected {expected}, got {p}"

def test_output_format(run, x):
    tokens_in = x.strip().split()
    if not tokens_in:
        return
    t = int(tokens_in[0])
    out = run(x)
    tokens_out = out.strip().split()
    assert len(tokens_out) == t, f"Expected {t} output numbers, got {len(tokens_out)}"
    for tok in tokens_out:
        assert tok.isdigit(), f"Output token not all digits: {tok}"
        if len(tok) > 1:
            assert tok[0] != '0', f"Leading zero in output token: {tok}"

