    if n > 30:
        return
    best = 0
    for l in range(n):
        for r in range(l, n):
            s2 = s[:l] + s[r+1:]
            i = 0
            for ch in s2:
                if i < len(t) and ch == t[i]:
                    i += 1
            if i == len(t):
                best = max(best, r - l + 1)
    out = run(x).strip()
    val = int(out)
    assert val == best, f'Brute-force expects {best}, got {val}'

def test_achievable_length(run, x):
    s, t = x.strip().split('\n')[:2]
    n = len(s)
    if n > 30:
        return
    out = run(x).strip()
    L = int(out)
    found = False
    for l in range(n):
        for r in range(l, n):
            if r - l + 1 == L:
                s2 = s[:l] + s[r+1:]
                i = 0
                for ch in s2:
                    if i < len(t) and ch == t[i]:
                        i += 1
                if i == len(t):
                    found = True
                    break
        if found:
            break
    assert found, f'No removable substring of length {L} found'

def test_output_format(run, x):
    out = run(x)
    lines = [line for line in out.split('\n') if line.strip() != '']
    assert len(lines) == 1, 'Output must be exactly one line'
    line = lines[0].strip()
    if line.startswith('-'):
        assert line[1:].isdigit(), 'Output must be an integer'
    else:
        assert line.isdigit(), 'Output must be a nonnegative integer'

def test_nonnegative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0, 'Output must be nonnegative'

def test_upper_bound(run, x):
    s, t = x.strip().split('\n')[:2]
    out = run(x).strip()
    val = int(out)
    assert val <= len(s) - len(t), f'Output {val} exceeds maximum possible removal length {len(s)-len(t)}'

def test_lower_bound_greedy_left(run, x):
    s, t = x.strip().split('\n')[:2]
    n = len(s)
    m = len(t)
    pos = []
    j = 0
    for i in range(m):
        while j < n and s[j] != t[i]:
            j += 1
        if j == n:
            break
        pos.append(j)
        j += 1
    if len(pos) == m:
        gaps = [pos[0]]
        for i in range(1, m):
            gaps.append(pos[i] - pos[i-1] - 1)
        gaps.append(n - 1 - pos[-1])
        max_gap = max(gaps)
        out = run(x).strip()
        val = int(out)
        assert val >= max_gap, f'Output {val} below greedy left lower bound {max_gap}'

def test_lower_bound_greedy_right(run, x):
    s, t = x.strip().split('\n')[:2]
    n = len(s)
    m = len(t)
    pos = []
    j = n - 1
    for i in range(m-1, -1, -1):
        while j >= 0 and s[j] != t[i]:
            j -= 1
        if j < 0:
            break
        pos.append(j)
        j -= 1
    pos.reverse()
    if len(pos) == m:
        gaps = [pos[0]]
        for i in range(1, m):
            gaps.append(pos[i] - pos[i-1] - 1)
        gaps.append(n - 1 - pos[-1])
        max_gap = max(gaps)
        out = run(x).strip()
        val = int(out)
        assert val >= max_gap, f'Output {val} below greedy right lower bound {max_gap}'

def test_s_equal_t_zero(run, x):
    s, t = x.strip().split('\n')[:2]
    if s == t:
        out = run(x).strip()
        val = int(out)
        assert val == 0, f'When s equals t, answer must be 0, got {val}'

def test_examples_hardcoded(run, x):
    examples = {
        'bbaba\nbb\n': 3,
        'baaba\nab\n': 2,
        'abcde\nabcde\n': 0,
    }
    if x in examples:
        out = run(x).strip()
        val = int(out)
        assert val == examples[x], f'Example expects {examples[x]}, got {val}'

def test_single_char_t(run, x):
    s, t = x.strip().split('\n')[:2]
    if len(t) == 1:
        n = len(s)
        first = None
        last = None
        for i, ch in enumerate(s):
            if ch == t[0]:
                if first is None:
                    first = i
                last = i
        expected = max(n - first - 1, last)
        out = run(x).strip()
        val = int(out)
        assert val == expected, f'For single-char t, answer must be {expected}, got {val}'

