def test_oracle(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    output = int(run(x).strip())
    best = n
    d = 1
    while d * d <= n:
        if n % d == 0:
            if d <= k:
                best = min(best, n // d)
            other = n // d
            if other <= k:
                best = min(best, n // other)
        d += 1
    assert output == best

def test_lower_bound(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    output = int(run(x).strip())
    import math
    assert output >= (n + k - 1) // k

def test_feasible(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    output = int(run(x).strip())
    package_size = n // output
    assert package_size * output == n and 1 <= package_size <= k

def test_k_ge_n_output_1(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    if k >= n:
        output = int(run(x).strip())
        assert output == 1

def test_prime_n_k_lt_n_output_n(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    if k < n and n > 1:
        is_prime = True
        d = 2
        while d * d <= n:
            if n % d == 0:
                is_prime = False
                break
            d += 1
        if is_prime:
            output = int(run(x).strip())
            assert output == n

