    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    if n == 1:
        output = int(run(x).strip())
        assert output == 1

def test_specific_cases(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    cases = {(16,4):4, (32,4):8, (64,4):16, (400000000,4):100000000, (16,5):4}
    if (n,k) in cases:
        output = int(run(x).strip())
        assert output == cases[(n,k)]

def test_exhaustive_small_k(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    if k <= 1000:
        output = int(run(x).strip())
        best = n
        for d in range(1, k+1):
            if n % d == 0:
                best = min(best, n // d)
        assert output == best

def test_output_positive(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    if t != 1:
        return
    nk = lines[1].strip().split()
    n = int(nk[0])
    k = int(nk[1])
    output = int(run(x).strip())
    assert output >= 1

