def test_correct_answer(run, x):
    data = x.strip().splitlines()
    first = data[0].split()
    n, m, s = map(int, first)
    s -= 1
    edges = []
    for line in data[1:1+m]:
        u, v = map(int, line.split())
        u -= 1
        v -= 1
        edges.append((u, v))
    adj = [[] for _ in range(n)]
    radj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        radj[v].append(u)
    visited = [False] * n
    order = []
    for i in range(n):
        if not visited[i]:
            stack = [i]
            while stack:
                u = stack[-1]
                if not visited[u]:
                    visited[u] = True
                    for v in adj[u]:
                        if not visited[v]:
                            stack.append(v)
                else:
                    stack.pop()
                    order.append(u)
    comp = [-1] * n
    cid = 0
    for u in reversed(order):
        if comp[u] == -1:
            stack = [u]
            comp[u] = cid
            while stack:
                u = stack.pop()
                for v in radj[u]:
                    if comp[v] == -1:
                        comp[v] = cid
                        stack.append(v)
            cid += 1
    indeg = [0] * cid
    for u, v in edges:
        cu, cv = comp[u], comp[v]
        if cu != cv:
            indeg[cv] += 1
    zero = sum(1 for i in range(cid) if indeg[i] == 0)
    s_comp = comp[s]
    if indeg[s_comp] == 0:
        ans = zero - 1
    else:
        ans = zero
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) == ans

def test_bounds(run, x):
    first_line = x.split('\n')[0]
    n = int(first_line.split()[0])
    output = run(x).strip()
    assert output.isdigit()
    ans = int(output)
    assert 0 <= ans <= n - 1

def test_no_roads(run, x):
    lines = x.strip().split('\n')
    n, m, s = map(int, lines[0].split())
    if m == 0:
        output = run(x).strip()
        assert output.isdigit()
        ans = int(output)
        assert ans == n - 1

def test_all_reachable(run, x):
    lines = x.strip().split('\n')
    n, m, s = map(int, lines[0].split())
    s -= 1
    adj = [[] for _ in range(n)]
    for line in lines[1:1+m]:
        u, v = map(int, line.split())
        u -= 1
        v -= 1
        adj[u].append(v)
    visited = [False] * n
    stack = [s]
    visited[s] = True
    while stack:
        u = stack.pop()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                stack.append(v)
    if all(visited):
        output = run(x).strip()
        assert output == '0'

