def test_direct_oracle(run, x):
    import sys
    D, T, S = map(int, x.split())
    expected = 'Yes\n' if D <= T * S else 'No\n'
    assert run(x) == expected

def test_output_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n')

def test_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    assert stripped in ('Yes', 'No')
    assert out == stripped + '\n'

def test_yes_implies_D_le_TS(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if out.rstrip('\n') == 'Yes':
        assert D <= T * S

def test_no_implies_D_gt_TS(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if out.rstrip('\n') == 'No':
        assert D > T * S

def test_equality_case(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if D == T * S:
        assert out == 'Yes\n'

def test_off_by_one_above(run, x):
    D, T, S = map(int, x.split())
    out = run(x)
    if D == T * S + 1:
        assert out == 'No\n'

def test_min_values(run, x):
    D, T, S = map(int, x.split())
    if D == 1 and T == 1 and S == 1:
        assert run(x) == 'Yes\n'

def test_max_values_true(run, x):
    D, T, S = map(int, x.split())
    if D == 10000 and T == 10000 and S == 1:
        assert run(x) == 'Yes\n'

def test_max_values_false(run, x):
    D, T, S = map(int, x.split())
    if D == 10000 and T == 1 and S == 1:
        assert run(x) == 'No\n'

