tests_src:
def test_brute_force_oracle(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
    except:
        return
    if not (2 <= N <= 50):
        return
    parts = lines[1].split()
    if len(parts) != N:
        return
    try:
        p = [int(part) for part in parts]
    except:
        return
    if set(p) != set(range(1, N+1)):
        return
    sorted_p = list(range(1, N+1))
    if p == sorted_p:
        correct = 'YES'
    else:
        sortable = False
        for i in range(N):
            for j in range(i+1, N):
                p[i], p[j] = p[j], p[i]
                if p == sorted_p:
                    sortable = True
                    p[i], p[j] = p[j], p[i]
                    break
                p[i], p[j] = p[j], p[i]
            if sortable:
                break
        correct = 'YES' if sortable else 'NO'
    output = run(x)
    if output.strip() != correct.strip():
        assert False

def test_output_format(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
    except:
        return
    if not (2 <= N <= 50):
        return
    parts = lines[1].split()
    if len(parts) != N:
        return
    try:
        p = [int(part) for part in parts]
    except:
        return
    if set(p) != set(range(1, N+1)):
        return
    output = run(x)
    stripped = output.strip()
    assert stripped == 'YES' or stripped == 'NO'

def test_equivalence(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
    except:
        return
    if not (2 <= N <= 50):
        return
    parts = lines[1].split()
    if len(parts) != N:
        return
    try:
        p = [int(part) for part in parts]
    except:
        return
    if set(p) != set(range(1, N+1)):
        return
    z = sum(1 for i in range(N) if p[i] != i+1)
    output = run(x)
    ans = output.strip()
    assert (ans == 'YES') == (z <= 2)

def test_sorted_input(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
    except:
        return
    if not (2 <= N <= 50):
        return
    parts = lines[1].split()
    if len(parts) != N:
        return
    try:
        p = [int(part) for part in parts]
    except:
        return
    if set(p) != set(range(1, N+1)):
        return
    if p == list(range(1, N+1)):
        output = run(x)
        assert output.strip() == 'YES'

