tests_src:
def test_exact_by_counting(run, x):
    n = int(x.strip())
    cnt = sum(1 for i in range(1, n+1) if i % 2 == 1)
    exact = cnt / n
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    assert abs(val - exact) <= 1e-6

def test_output_float_range(run, x):
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    assert 0 <= val <= 1

def test_even_half(run, x):
    n = int(x.strip())
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    if n % 2 == 0:
        assert abs(val - 0.5) <= 1e-6

def test_odd_greater_than_half(run, x):
    n = int(x.strip())
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    if n % 2 == 1:
        assert val > 0.5

def test_odd_formula(run, x):
    n = int(x.strip())
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    if n % 2 == 1:
        expected = (n + 1) / (2 * n)
        assert abs(val - expected) <= 1e-6

def test_smallest(run, x):
    n = int(x.strip())
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    if n == 1:
        assert abs(val - 1.0) <= 1e-6

def test_largest(run, x):
    n = int(x.strip())
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    if n == 100:
        assert abs(val - 0.5) <= 1e-6

def test_odd_count_integer(run, x):
    n = int(x.strip())
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    exact_count = (n + 1) // 2
    assert abs(val * n - exact_count) <= n * 1e-6 + 1e-12

def test_sample_io(run, x):
    n = int(x.strip())
    samples = {1: 1.0, 4: 0.5, 5: 0.6}
    out = run(x)
    try:
        val = float(out)
    except ValueError:
        assert False, "Output cannot be parsed as float"
    if n in samples:
        expected = samples[n]
        diff = abs(val - expected)
        rel = diff / expected if expected != 0 else float('inf')
        assert diff <= 1e-6 or rel <= 1e-6

def test_output_parsable(run, x):
    out = run(x)
    try:
        float(out)
        convertible = True
    except ValueError:
        convertible = False
    assert convertible, "Output must be a valid float representation"

