    N = int(x.strip())
    odd_count = (N + 1) // 2
    out = run(x)
    val = float(out.strip())
    product = val * N
    assert abs(product - odd_count) <= N * 1e-6, f'For N={N}, expected product close to {odd_count}, got {product}'

