    lines = x.strip().split()
    A = list(map(int, lines[1:]))
    N = len(A)
    ans = int(run(x).strip())
    for i in range(N):
        for j in range(i+1, N):
            assert abs(A[i] - A[j]) <= ans

def test_global_upper_bound(run, x):
    ans = int(run(x).strip())
    assert ans <= 10**9 - 1

