def test_oracle(run, x):
    s = x.strip()
    hard = any(s[i] == s[i+1] for i in range(3))
    expected = 'Bad\n' if hard else 'Good\n'
    out = run(x)
    assert out == expected

def test_output_format(run, x):
    out = run(x)
    assert out in ('Bad\n', 'Good\n')

def test_bad_implies_consecutive(run, x):
    out = run(x)
    if out == 'Bad\n':
        s = x.strip()
        assert any(s[i] == s[i+1] for i in range(3))

def test_good_implies_no_consecutive(run, x):
    out = run(x)
    if out == 'Good\n':
        s = x.strip()
        assert all(s[i] != s[i+1] for i in range(3))

def test_pair01_equal_implies_bad(run, x):
    out = run(x)
    s = x.strip()
    if s[0] == s[1]:
        assert out == 'Bad\n'

def test_pair12_equal_implies_bad(run, x):
    out = run(x)
    s = x.strip()
    if s[1] == s[2]:
        assert out == 'Bad\n'

def test_pair23_equal_implies_bad(run, x):
    out = run(x)
    s = x.strip()
    if s[2] == s[3]:
        assert out == 'Bad\n'

def test_no_equal_implies_good(run, x):
    out = run(x)
    s = x.strip()
    if all(s[i] != s[i+1] for i in range(3)):
        assert out == 'Good\n'

def test_all_equal_implies_bad(run, x):
    out = run(x)
    s = x.strip()
    if s[0] == s[1] == s[2] == s[3]:
        assert out == 'Bad\n'

def test_no_digits_in_output(run, x):
    out = run(x)
    assert not any(c.isdigit() for c in out)

