tests_src:
def test_valid_output(run, x):
    out = run(x)
    assert out == 'Bad\n' or out == 'Good\n'

def test_first_pair_implies_bad(run, x):
    s = x.strip()
    out = run(x)
    if s[0] == s[1]:
        assert out == 'Bad\n'

def test_second_pair_implies_bad(run, x):
    s = x.strip()
    out = run(x)
    if s[1] == s[2]:
        assert out == 'Bad\n'

def test_third_pair_implies_bad(run, x):
    s = x.strip()
    out = run(x)
    if s[2] == s[3]:
        assert out == 'Bad\n'

def test_no_consecutive_equal_implies_good(run, x):
    s = x.strip()
    out = run(x)
    if s[0] != s[1] and s[1] != s[2] and s[2] != s[3]:
        assert out == 'Good\n'

def test_good_implies_no_consecutive_equal(run, x):
    s = x.strip()
    out = run(x)
    if out == 'Good\n':
        assert not (s[0] == s[1] or s[1] == s[2] or s[2] == s[3])

def test_correct_answer(run, x):
    s = x.strip()
    out = run(x)
    if s[0] == s[1] or s[1] == s[2] or s[2] == s[3]:
        correct = 'Bad\n'
    else:
        correct = 'Good\n'
    assert out == correct

def test_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n')

def test_starts_with_B_or_G(run, x):
    out = run(x)
    assert len(out) >= 1 and out[0] in ('B', 'G')

def test_stripped_output_valid(run, x):
    out = run(x)
    assert out.strip() in ('Bad', 'Good')

