      "name": "test_brute_force_mst",
      "source": "def test_brute_force_mst(run, x):
    out = run(x)
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 8:
        return
    a = list(map(int, lines[1].split()))
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((i, j, a[i] + a[j]))
    if m > 0:
        for k in range(m):
            x_line = lines[2 + k].split()
            u = int(x_line[0]) - 1
            v = int(x_line[1]) - 1
            w = int(x_line[2])
            edges.append((u, v, w))
    edges.sort(key=lambda e: e[2])
    parent = list(range(n))
    rank = [0] * n
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru == rv:
            return False
        if rank[ru] < rank[rv]:
            ru, rv = rv, ru
        parent[rv] = ru
        if rank[ru] == rank[rv]:
            rank[ru] += 1
        return True
    total = 0
    cnt = 0
    for u, v, w in edges:
