def test_exact_kruskal(run, x):
    out = run(x).strip()
    lines = x.strip().split('\n')
    first = lines[0].split()
    n = int(first[0])
    if n > 10:
        return
    m = int(first[1])
    a = list(map(int, lines[1].split()))
    offers = []
    for i in range(m):
        parts = lines[2 + i].split()
        offers.append((int(parts[0]), int(parts[1]), int(parts[2])))
    offer_min = {}
    for x_, y_, w in offers:
        u, v = min(x_, y_), max(x_, y_)
        key = (u, v)
        if key not in offer_min or w < offer_min[key]:
            offer_min[key] = w
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            cost = a[i] + a[j]
            key = (i + 1, j + 1)
            if key in offer_min:
                cost = min(cost, offer_min[key])
            edges.append((cost, i, j))
    edges.sort()
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
            return True
        return False
    total = 0
    used = 0
    for cost, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            total += cost
            used += 1
            if used == n - 1:
                break
    assert int(out) == total, f"Expected {total}, got {out}"

def test_exact_prim(run, x):
    out = run(x).strip()
    lines = x.strip().split('\n')
    first = lines[0].split()
    n = int(first[0])
    if n > 10:
        return
    m = int(first[1])
    a = list(map(int, lines[1].split()))
    offers = []
    for i in range(m):
        parts = lines[2 + i].split()
        offers.append((int(parts[0]), int(parts[1]), int(parts[2])))
    INF = 10**30
    adj = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            adj[i][j] = adj[j][i] = a[i] + a[j]
    for x_, y_, w in offers:
        i, j = x_ - 1, y_ - 1
        if w < adj[i][j]:
            adj[i][j] = adj[j][i] = w
    import heapq
    visited = [False] * n
    min_edge = [INF] * n
    min_edge[0] = 0
    heap = [(0, 0)]
    total = 0
    while heap:
        cost, u = heapq.heappop(heap)
        if visited[u]:
            continue
        visited[u] = True
        total += cost
        for v in range(n):
            if not visited[v] and adj[u][v] < min_edge[v]:
                min_edge[v] = adj[u][v]
                heapq.heappush(heap, (adj[u][v], v))
    assert int(out) == total, f"Prim expected {total}, got {out}"

