    for i in range(m):
        parts = lines[2 + i].split()
        offers.append((int(parts[0]), int(parts[1]), int(parts[2])))
    if m == 0:
        return
    useless = True
    for x_, y_, w in offers:
        i, j = x_ - 1, y_ - 1
        if w < a[i] + a[j]:
            useless = False
            break
    if useless:
        min_a = min(a)
