tests_src:
def test_output_integer(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()
    m = int(s)

def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()
    assert out == s or out == s + '\n'

def test_output_range(run, x):
    out = run(x)
    m = int(out.strip())
    assert 4 <= m <= 1000000

def test_samples(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    if s_val == 1:
        assert m == 4
    elif s_val == 2:
        assert m == 4
    elif s_val == 8:
        assert m == 5

def test_sequence_repeats_at_m(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    seen = {s_val: 1}
    a = s_val
    for i in range(2, m+1):
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
        if i == m:
            assert a in seen, f"Repeat not found at index {m}"
        else:
            assert a not in seen, f"Early repeat at index {i}"
            seen[a] = i

def test_minimal_m(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    seen = {s_val: 1}
    a = s_val
    i = 2
    while True:
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
        if a in seen:
            first = i
            break
        seen[a] = i
        i += 1
    assert m == first

def test_specific_values(run, x):
    s_val = int(x.strip())
    if s_val not in (3, 4, 27, 100):
        return
    out = run(x)
    m = int(out.strip())
    seen = {s_val: 1}
    a = s_val
    i = 2
    while True:
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
        if a in seen:
            expected = i
            break
        seen[a] = i
        i += 1
    assert m == expected

def test_sequence_elements_bound(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    a = s_val
    if a > 1000000:
        assert False, f"Initial value {a} > 1000000"
    for i in range(2, m+1):
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
        if a > 1000000:
            assert False, f"Value {a} at step {i} > 1000000"

def test_bound_by_first_4(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    a = s_val
    k = None
    for step in range(1, 1000001):
        if a == 4:
            k = step
            break
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
    if k is not None:
        assert m <= k + 3

def test_sequence_positive(run, x):
    s_val = int(x.strip())
    out = run(x)
    m = int(out.strip())
    a = s_val
    assert a > 0
    for i in range(2, m+1):
        if a % 2 == 0:
            a = a // 2
        else:
            a = 3 * a + 1
        assert a > 0, f"Non-positive value {a} at step {i}"

