def test_brute_force_small(run, x):
    data = x.strip().split()
    if not data:
        return
    t = int(data[0])
    queries = []
    idx = 1
    for _ in range(t):
        L = int(data[idx]); v = int(data[idx+1]); l = int(data[idx+2]); r = int(data[idx+3])
        idx += 4
        queries.append((L, v, l, r))
    total_multiples = sum(L // v for (L, v, _, _) in queries)
    if total_multiples > 10000:
        return
    output = run(x).strip().split()
    if len(output) != t:
        assert False, "Wrong number of output lines"
    out_vals = list(map(int, output))
    for i, (L, v, l, r) in enumerate(queries):
        count = 0
        p = v
        while p <= L:
            if not (l <= p <= r):
                count += 1
            p += v
        assert out_vals[i] == count, f"Query {i}: expected {count}, got {out_vals[i]}"

