def test_direct_oracle(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    valid_a = 1 <= a <= 12
    valid_b = 1 <= b <= 12
    if valid_a and valid_b:
        expected = 'AMBIGUOUS'
    elif valid_a and not valid_b:
        expected = 'MMYY'
    elif not valid_a and valid_b:
        expected = 'YYMM'
    else:
        expected = 'NA'
    assert run(x).strip() == expected

def test_both_valid_ambiguous(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    if 1 <= a <= 12 and 1 <= b <= 12:
        assert run(x).strip() == 'AMBIGUOUS'

def test_only_first_valid_mmyy(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    if 1 <= a <= 12 and not (1 <= b <= 12):
        assert run(x).strip() == 'MMYY'

def test_only_second_valid_yymm(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    if not (1 <= a <= 12) and 1 <= b <= 12:
        assert run(x).strip() == 'YYMM'

def test_neither_valid_na(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    if not (1 <= a <= 12) and not (1 <= b <= 12):
        assert run(x).strip() == 'NA'

def test_output_in_set(run, x):
    output = run(x).strip()
    assert output in {'YYMM', 'MMYY', 'AMBIGUOUS', 'NA'}

def test_ambiguous_implies_both_valid(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    output = run(x).strip()
    if output == 'AMBIGUOUS':
        assert 1 <= a <= 12 and 1 <= b <= 12

def test_yymm_implies_second_valid_first_invalid(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    output = run(x).strip()
    if output == 'YYMM':
        assert 1 <= b <= 12 and not (1 <= a <= 12)

def test_mmyy_implies_first_valid_second_invalid(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    output = run(x).strip()
    if output == 'MMYY':
        assert 1 <= a <= 12 and not (1 <= b <= 12)

def test_na_implies_both_invalid(run, x):
    S = x.strip()
    a = int(S[:2])
    b = int(S[2:])
    output = run(x).strip()
    if output == 'NA':
        assert not (1 <= a <= 12) and not (1 <= b <= 12)

