tests_src:
def test_output_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False

def test_output_nonnegative(run, x):
    k, s = map(int, x.strip().split())
    ans = int(run(x).strip())
    assert ans >= 0

def test_upper_bound(run, x):
    k, s = map(int, x.strip().split())
    ans = int(run(x).strip())
    assert ans <= (k + 1) ** 3

def test_small_S(run, x):
    k, s = map(int, x.strip().split())
    if s <= k:
        ans = int(run(x).strip())
        expected = (s + 2) * (s + 1) // 2
        assert ans == expected

def test_large_S(run, x):
    k, s = map(int, x.strip().split())
    if s >= 2 * k:
        ans = int(run(x).strip())
        t = 3 * k - s
        expected = (t + 2) * (t + 1) // 2
        assert ans == expected

def test_S0(run, x):
    k, s = map(int, x.strip().split())
    if s == 0:
        ans = int(run(x).strip())
        assert ans == 1

def test_S3K(run, x):
    k, s = map(int, x.strip().split())
    if s == 3 * k:
        ans = int(run(x).strip())
        assert ans == 1

def test_S2K(run, x):
    k, s = map(int, x.strip().split())
    if s == 2 * k:
        ans = int(run(x).strip())
        expected = (k + 2) * (k + 1) // 2
        assert ans == expected

def test_S2K_minus_1(run, x):
    k, s = map(int, x.strip().split())
    if s == 2 * k - 1:
        ans = int(run(x).strip())
        expected = k * (k + 5) // 2
        assert ans == expected

def test_small_K_brute_force(run, x):
    k, s = map(int, x.strip().split())
    if k <= 15:
        ans = int(run(x).strip())
        count = 0
        for xv in range(k + 1):
            for yv in range(k + 1):
                for zv in range(k + 1):
                    if xv + yv + zv == s:
                        count += 1
        assert ans == count

