tests_src:
def test_output_in_range(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert 0 <= val <= 3

def test_no_R_gives_zero(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    if 'R' not in s:
        assert out.isdigit() and int(out) == 0

def test_all_R_gives_three(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    if s == 'RRR':
        assert out == '3'

def test_all_S_gives_zero(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    if s == 'SSS':
        assert out == '0'

def test_one_R_gives_one(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    if s.count('R') == 1:
        assert out == '1'

def test_two_consecutive_R_gives_two(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    if s.count('R') == 2 and 'RR' in s:
        assert out == '2'

def test_two_non_consecutive_R_gives_one(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    if s.count('R') == 2 and 'RR' not in s:
        assert out == '1'

def test_at_least_one_R_output_ge_one(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    if 'R' in s:
        assert out.isdigit() and int(out) >= 1

def test_output_le_total_R(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    out = run(x).strip()
    r_count = s.count('R')
    assert out.isdigit() and int(out) <= r_count

def test_direct_oracle(run, x):
    s = x.strip()
    if any(c not in 'RS' for c in s):
        return
    max_run = 0
    cur = 0
    for ch in s:
        if ch == 'R':
            cur += 1
            if cur > max_run:
                max_run = cur
        else:
            cur = 0
    expected = str(max_run)
    out = run(x).strip()
    assert out == expected

