    ans = int(out.strip())
    assert 0 <= ans <= n

def test_output_mod6(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    ans = int(out.strip())
    assert (n - ans) % 6 == 0

def test_small_n_removal(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 6:
        out = run(x)
        ans = int(out.strip())
        assert ans == n

def test_lower_bound_min_count(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    mapping = {4:0, 8:1, 15:2, 16:3, 23:4, 42:5}
    counts = [0]*6
    for val in a:
        counts[mapping[val]] += 1
    min_count = min(counts)
    out = run(x)
    ans = int(out.strip())
    assert ans >= n - 6 * min_count

def test_statement_examples(run, x):
    examples = {
        "5\n4 8 15 16 23\n": 5,
        "12\n4 8 4 15 16 8 23 15 16 42 23 42\n": 0,
        "15\n4 8 4 8 15 16 8 16 23 15 16 4 42 23 42\n": 3
    }
    if x in examples:
        out = run(x)
        ans = int(out.strip())
        assert ans == examples[x]

def test_full_sequence(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 6:
        a = list(map(int, lines[1].split()))
        if a == [4, 8, 15, 16, 23, 42]:
            out = run(x)
            ans = int(out.strip())
            assert ans == 0

def test_all_same(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if len(set(a)) == 1:
        n = int(lines[0])
        out = run(x)
        ans = int(out.strip())
        assert ans == n

def test_brute_force_small_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 12:
        return
    a = list(map(int, lines[1].split()))
    max_kept = 0
    for mask in range(1 << n):
        kept = []
        for i in range(n):
            if mask & (1 << i):
                kept.append(a[i])
        cnt = [0,0,0,0,0]
        ok = True
        for val in kept:
            if val == 4:
                cnt[0] += 1
            elif val == 8:
                if cnt[0] == 0:
                    ok = False
                    break
                cnt[0] -= 1
                cnt[1] += 1
            elif val == 15:
                if cnt[1] == 0:
                    ok = False
                    break
                cnt[1] -= 1
                cnt[2] += 1
            elif val == 16:
                if cnt[2] == 0:
                    ok = False
                    break
                cnt[2] -= 1
                cnt[3] += 1
            elif val == 23:
                if cnt[3] == 0:
                    ok = False
                    break
                cnt[3] -= 1
                cnt[4] += 1
            elif val == 42:
                if cnt[4] == 0:
                    ok = False
                    break
                cnt[4] -= 1
            else:
                ok = False
                break
        if ok and all(c == 0 for c in cnt):
            kept_len = len(kept)
            if kept_len > max_kept:
                max_kept = kept_len
    out = run(x)
    ans = int(out.strip())
    assert ans == n - max_kept

def test_missing_number(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    required = {4, 8, 15, 16, 23, 42}
    if not required.issubset(set(a)):
        n = int(lines[0])
        out = run(x)
        ans = int(out.strip())
        assert ans == n

