tests_src:
def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit()
    if s != '0':
        assert s[0] != '0'

def test_non_negative(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0

def test_upper_bound(run, x):
    n, _ = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    assert ans <= n

def test_x_gt_n2_zero(run, x):
    n, x_val = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if x_val > n * n:
        assert ans == 0

def test_x_le_n_at_least_one(run, x):
    n, x_val = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if x_val <= n:
        assert ans >= 1

def test_parity(run, x):
    import math
    n, x_val = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    sqrt_x = math.isqrt(x_val)
    perfect = sqrt_x * sqrt_x == x_val
    if perfect and sqrt_x <= n:
        assert ans % 2 == 1
    else:
        assert ans % 2 == 0

def test_prime(run, x):
    import math
    n, x_val = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if x_val <= n:
        if x_val < 2:
            return
        is_prime = True
        limit = int(math.isqrt(x_val))
        for d in range(2, limit + 1):
            if x_val % d == 0:
                is_prime = False
                break
        if is_prime:
            assert ans == 2

def test_small_n_brute_force(run, x):
    n, x_val = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if n <= 100:
        count = 0
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if i * j == x_val:
                    count += 1
        assert ans == count

def test_divisor_oracle(run, x):
    import math
    n, x_val = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    count = 0
    limit = int(math.isqrt(x_val))
    for d in range(1, limit + 1):
        if x_val % d == 0:
            other = x_val // d
            if d <= n and other <= n:
                count += 1
            if other != d and other <= n and d <= n:
                count += 1
    assert ans == count

def test_max_product(run, x):
    n, x_val = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if x_val == n * n:
        assert ans == 1

