def test_equals_min_adjacent(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    z = list(map(int, lines[2].split()))
    output = run(x).strip()
    t = int(output)
    best_adj = None
    for i in range(n-1):
        if s[i] == 'R' and s[i+1] == 'L':
            d = z[i+1] - z[i]
            time = d // 2
            if best_adj is None or time < best_adj:
                best_adj = time
    if best_adj is None:
        assert t == -1
    else:
