def test_output_is_integer(run, x):
    output = run(x).strip()
    try:
        int(output)
    except ValueError:
        assert False, f"Output '{output}' is not an integer"

def test_arithmetic_progression_correct_next(run, x):
    a,b,c,d = map(int, x.strip().split())
    if b - a == c - b == d - c:
        expected = d + (b - a)
        output = run(x).strip()
        assert output == str(expected), f"Arithmetic progression expected {expected}, got {output}"

def test_geometric_progression_integer_next_correct(run, x):
    a,b,c,d = map(int, x.strip().split())
    if b != a and a * c == b * b and b * d == c * c:
        if (d * b) % a == 0:
            expected = d * b // a
            output = run(x).strip()
            assert output == str(expected), f"Geometric progression expected {expected}, got {output}"

def test_neither_or_non_integer_next_yields_42(run, x):
    a,b,c,d = map(int, x.strip().split())
    is_arith = (b - a == c - b == d - c)
    is_geom_int = False
    if not is_arith and b != a and a * c == b * b and b * d == c * c:
        if (d * b) % a == 0:
            is_geom_int = True
    if not is_arith and not is_geom_int:
        output = run(x).strip()
        assert output == "42", f"Expected 42 for neither progression or non-integer next term, got {output}"

def test_geometric_non_integer_next_yields_42(run, x):
    a,b,c,d = map(int, x.strip().split())
    if b != a and a * c == b * b and b * d == c * c:
        if (d * b) % a != 0:
            output = run(x).strip()
            assert output == "42", f"Geometric progression with non-integer next term expected 42, got {output}"

def test_constant_sequence_output(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == b == c == d:
        output = run(x).strip()
        assert output == str(a), f"Constant sequence expected {a}, got {output}"

def test_output_extends_progression_if_not_42(run, x):
    output = run(x).strip()
    if output == "42":
        return
    try:
        out = int(output)
    except ValueError:
        assert False, f"Output '{output}' is not an integer"
    a,b,c,d = map(int, x.strip().split())
    if b - a == c - b == d - c == out - d:
        return
    if b != a and a * c == b * b and b * d == c * c and c * out == d * d:
        return
    assert False, f"Output {out} does not extend the sequence as either arithmetic or geometric progression"

def test_geometric_next_term_different(run, x):
    a,b,c,d = map(int, x.strip().split())
    if b != a and a * c == b * b and b * d == c * c:
        if (d * b) % a == 0:
            output = run(x).strip()
            out = int(output)
            assert out != d, f"Geometric progression with q != 1 should have next term different from last term, got {out}"

def test_correct_answer_by_oracle(run, x):
    def solve(a,b,c,d):
        if b - a == c - b == d - c:
            return d + (b - a)
        if b != a and a * c == b * b and b * d == c * c:
            if (d * b) % a == 0:
                return d * b // a
            else:
                return 42
        return 42
    a,b,c,d = map(int, x.strip().split())
    expected = solve(a,b,c,d)
    output = run(x).strip()
    assert output == str(expected), f"Expected {expected}, got {output}"

def test_42_implies_not_progression_or_non_integer(run, x):
    output = run(x).strip()
    if output != "42":
        return
    a,b,c,d = map(int, x.strip().split())
    if b - a == c - b == d - c:
        assert False, "Output is 42 but sequence is arithmetic"
    if b != a and a * c == b * b and b * d == c * c:
        if (d * b) % a == 0:
            assert False, "Output is 42 but sequence is geometric with integer next term"

