        int(out)
    except ValueError:
        assert False, "Output is not an integer"

def test_arithmetic_correct(run, x):
    a,b,c,d = map(int, x.strip().split())
    if b - a == c - b == d - c:
        next_term = d + (b - a)
        out = run(x).strip()
        assert out == str(next_term), f"Arithmetic progression next term should be {next_term}, got {out}"

def test_geometric_correct(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == 0 or b == 0 or b == a:
        return
    if a * c != b * b or a * a * d != b * b * b:
        return
    num = b * b * b * b
    den = a * a * a
    if num % den != 0:
        return
    next_term = num // den
    out = run(x).strip()
    assert out == str(next_term), f"Geometric progression next term should be {next_term}, got {out}"

def test_neither_42(run, x):
    a,b,c,d = map(int, x.strip().split())
    is_arith = (b - a == c - b == d - c)
    is_geom = False
    if a != 0 and b != 0 and b != a:
        if a * c == b * b and a * a * d == b * b * b:
            is_geom = True
    if not is_arith and not is_geom:
        out = run(x).strip()
        assert out == "42", f"Sequence is neither arithmetic nor geometric, should output 42, got {out}"

def test_not42_implies_valid(run, x):
    out = run(x).strip()
    if out == "42":
        return
    a,b,c,d = map(int, x.strip().split())
    is_arith = (b - a == c - b == d - c)
    if is_arith:
        return
    if a == 0 or b == 0 or b == a:
        assert False, "Output not 42 but sequence is not arithmetic and not geometric with integer next"
    if a * c != b * b or a * a * d != b * b * b:
        assert False, "Output not 42 but sequence is not arithmetic and not geometric with integer next"
    num = b * b * b * b
    den = a * a * a
    if num % den != 0:
        assert False, "Output not 42 but geometric next term is not integer"

