    a,b,c,d = map(int, x.strip().split())
    if a == 0 or b == 0 or b == a:
        return
    if a * c != b * b or a * a * d != b * b * b:
        return
    num = b * b * b * b
    den = a * a * a
    if num % den != 0:
        return
    if a * b > 0:
        return
    out = run(x).strip()
    out_val = int(out)
    assert out_val * d < 0, f"Geometric with negative ratio: next term should have opposite sign to last term"

