        return
    if a * c != b * b or a * a * d != b * b * b:
        return
    num = b * b * b * b
    den = a * a * a
    if num % den != 0:
        return
    out = run(x).strip()
    out_val = int(out)
    assert out_val * a == d * b, f"Geometric progression: next * a should equal d * b"

def test_geometric_sign_consistent(run, x):
    a,b,c,d = map(int, x.strip().split())
    if a == 0 or b == 0 or b == a:
        return
    if a * c != b * b or a * a * d != b * b * b:
        return
    num = b * b * b * b
    den = a * a * a
