        return
    out = run(x).strip()
    out_val = int(out)
    cond1 = (out_val * d > 0)
    cond2 = (a * b > 0)
    assert cond1 == cond2, f"Geometric progression: sign of next/d should match sign of ratio b/a"

def test_geometric_non_integer_42(run, x):
