def test_lexicographic_minimality_by_enumeration(run, x):
    lines = x.strip().splitlines()
    first = lines[0].split()
    n, m, k = int(first[0]), int(first[1]), int(first[2])
    if n * m > 6 or k > 6:
        return  # skip enumeration for larger inputs
    grid = [list(line.strip()) for line in lines[1:1+n]]
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    dirs = [('D',1,0), ('L',0,-1), ('R',0,1), ('U',-1,0)]
    all_paths = []
    stack = [(start[0], start[1], 0, '')]
    while stack:
        i, j, steps, path = stack.pop()
        if steps == k:
            if (i, j) == start:
                all_paths.append(path)
            continue
        for dir_char, di, dj in dirs:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] != '*':
                stack.append((ni, nj, steps + 1, path + dir_char))
    if not all_paths:
        correct = 'IMPOSSIBLE'
    else:
        correct = min(all_paths)  # lexicographically smallest
    out = run(x).strip()
    assert out == correct

