def test_bfs_oracle(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    from collections import deque
    max_b = [-1] * (m+1)
    for a, b in teleports:
        if a <= m:
            max_b[a] = max(max_b[a], b)
    reachable = [False] * (m+1)
    reachable[0] = True
    q = deque([0])
    while q:
        p = q.popleft()
        if max_b[p] != -1:
            for np in range(p, max_b[p]+1):
                if np <= m and not reachable[np]:
                    reachable[np] = True
                    q.append(np)
    correct = 'YES' if reachable[m] else 'NO'
    output = run(x).strip().upper()
    assert output == correct.upper()

def test_greedy_oracle(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    k = 0
    for a, b in teleports:
        if a <= k:
            k = max(k, b)
    correct = 'YES' if k == m else 'NO'
    output = run(x).strip().upper()
    assert output == correct.upper()

def test_linear_scan_oracle(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    max_b = [-1] * (m+1)
    for a, b in teleports:
        if a <= m:
            max_b[a] = max(max_b[a], b)
    reachable = [False] * (m+1)
    reachable[0] = True
    for p in range(m+1):
        if reachable[p] and max_b[p] != -1:
            for q in range(p, max_b[p]+1):
                if q <= m:
                    reachable[q] = True
    correct = 'YES' if reachable[m] else 'NO'
    output = run(x).strip().upper()
    assert output == correct.upper()

def test_output_format(run, x):
    output = run(x)
    s = output.strip()
    assert s.upper() in {'YES', 'NO'}

def test_no_start_teleport(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    if all(a > 0 for a, _ in teleports):
        output = run(x).strip().upper()
        assert output == 'NO'

def test_direct_cover_from_zero(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    if any(a == 0 and b >= m for a, b in teleports):
        output = run(x).strip().upper()
        assert output == 'YES'

def test_max_b_less_than_m_implies_no(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    max_b = max(b for _, b in teleports)
    if max_b < m:
        output = run(x).strip().upper()
        assert output == 'NO'

def test_yes_requires_max_b_ge_m(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    output = run(x).strip().upper()
    if output == 'YES':
        max_b = max(b for _, b in teleports)
        assert max_b >= m

def test_output_no_extra_whitespace(run, x):
    output = run(x)
    if output.endswith('\n'):
        s = output[:-1]
    else:
        s = output
    assert s == s.strip()
    assert s.upper() in {'YES', 'NO'}

def test_useless_teleports(run, x):
    lines = x.strip().splitlines()
    n, m = map(int, lines[0].split())
    teleports = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        teleports.append((a, b))
    if all(a == b for a, b in teleports):
        output = run(x).strip().upper()
        assert output == 'NO'

def test_exact_dp(run, x):
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    a = int(lines[1])
    b = int(lines[2])
    sizes = [a]*4 + [b]*2
    from itertools import product
    found = False
    for k in range(1, 7):
        for assignment in product(range(k), repeat=6):
            bins = [0]*k
            ok = True
            for idx, bin_idx in enumerate(assignment):
                bins[bin_idx] += sizes[idx]
                if bins[bin_idx] > n:
                    ok = False
                    break
            if ok:
                found = True
                break
        if found:
            break
    optimal = k if found else 6
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == optimal


def test_lower_bound(run, x):
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    a = int(lines[1])
    b = int(lines[2])
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    total = 4*a + 2*b
    import math
    lower = (total + n - 1) // n
    assert ans >= lower


def test_upper_bound(run, x):
    out = run(x).strip()
    assert out.isdigit()
    ans = int(out)
    assert ans <= 6


def test_total_length_fits_one_bar(run, x):
    lines = x.strip().split()
    if len(lines) < 3:
        return
    n = int(lines[0])
    a = int(lines[1])
    b = int(lines[2])
    if n >= 4*a + 2*b:
        out = run(x).strip()
        assert out == '1'


def test_example1(run, x):
    if x == '8\n1\n2\n':
        out = run(x).strip()
        assert out == '1'


def test_example2(run, x):
    if x == '5\n3\n4\n':
        out = run(x).strip()
        assert out == '6'


def test_example3(run, x):
    if x == '6\n4\n2\n':
        out = run(x).strip()
        assert out == '4'


def test_example4(run, x):
    if x == '20\n5\n6\n':
        out = run(x).strip()
        assert out == '2'


def test_specific_1_1_1(run, x):
    if x == '1\n1\n1\n':
        out = run(x).strip()
        assert out == '6'


def test_specific_1000_1000_1000(run, x):
    if x == '1000\n1000\n1000\n':
        out = run(x).strip()
        assert out == '6'

def test_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, "Output must be an integer"


def test_positive(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 1, "Output must be at least 1"


def test_single_cell(run, x):
    x1, y1, x2, y2 = map(int, x.split())
    if x1 == x2 and y1 == y2:
        out = run(x).strip()
        val = int(out)
        assert val == 1, "For a single cell, output must be 1"


def test_single_row(run, x):
    x1, y1, x2, y2 = map(int, x.split())
    if y1 == y2 and (x1 % 2) == (y1 % 2):
        expected = (x2 - x1) // 2 + 1
        out = run(x).strip()
        val = int(out)
        assert val == expected, f"For a single row, expected {expected} but got {val}"


def test_single_column(run, x):
    x1, y1, x2, y2 = map(int, x.split())
    if x1 == x2 and (x1 % 2) == (y1 % 2):
        expected = (y2 - y1) // 2 + 1
        out = run(x).strip()
        val = int(out)
        assert val == expected, f"For a single column, expected {expected} but got {val}"


def test_small_bruteforce(run, x):
    x1, y1, x2, y2 = map(int, x.split())
    if (x1 % 2) != (y1 % 2) or (x2 % 2) != (y2 % 2):
        return
    total_points = (x2 - x1 + 1) * (y2 - y1 + 1)
    if total_points > 10000:
        return
    count = 0
    for xx in range(x1, x2 + 1):
        for yy in range(y1, y2 + 1):
            if (xx % 2) == (yy % 2):
                count += 1
    out = run(x).strip()
    val = int(out)
    assert val == count, f"Brute force count is {count} but got {val}"


def test_specific_row(run, x):
    if x.strip() == "1 1 5 1":
        out = run(x).strip()
        val = int(out)
        assert val == 3, f"For input '1 1 5 1', expected 3, got {val}"


def test_not_exceed_total(run, x):
    x1, y1, x2, y2 = map(int, x.split())
    total = (x2 - x1 + 1) * (y2 - y1 + 1)
    out = run(x).strip()
    val = int(out)
    assert val <= total, f"Output {val} exceeds total integer points {total}"


def test_formula(run, x):
    x1, y1, x2, y2 = map(int, x.split())
    if (x1 % 2) != (y1 % 2) or (x2 % 2) != (y2 % 2):
        return
    total = (x2 - x1 + 1) * (y2 - y1 + 1)
    expected = (total + 1) // 2
    out = run(x).strip()
    val = int(out)
    assert val == expected, f"Expected {expected} from formula, got {val}"


def test_specific_rectangle(run, x):
    if x.strip() == "0 0 4 2":
        out = run(x).strip()
        val = int(out)
        assert val == 8, f"For input '0 0 4 2', expected 8, got {val}"

