tests_src:
def test_output_has_exactly_t_lines(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    out = run(x)
    out_lines = out.splitlines()
    assert len(out_lines) == t

def test_each_output_line_is_yes_or_no(run, x):
    out = run(x)
    out_lines = out.splitlines()
    for line in out_lines:
        assert line in ("YES", "NO")

def test_no_extra_whitespace_in_lines(run, x):
    out = run(x)
    out_lines = out.splitlines()
    for line in out_lines:
        assert line.strip() == line
        assert line != ""

def test_oracle_exact_match(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    idx = 1
    expected = []
    for _ in range(t):
        if idx >= len(lines):
            break
        n, m = map(int, lines[idx].strip().split()[:2])
        idx += 1
        if idx >= len(lines):
            break
        a = list(map(int, lines[idx].strip().split()))
        idx += 1
        s = sum(a)
        expected.append("YES" if s == m else "NO")
    out = run(x)
    out_lines = out.splitlines()
    assert out_lines == expected

def test_first_test_case_sum_eq_m_implies_yes(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    t = int(lines[0].strip())
    if t < 1:
        return
    n_m = list(map(int, lines[1].strip().split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    a = list(map(int, lines[2].strip().split()))
    s = sum(a)
    if s == m:
        out = run(x)
        out_lines = out.splitlines()
        if out_lines:
            assert out_lines[0] == "YES"

def test_first_test_case_sum_ne_m_implies_no(run, x):
    lines = x.strip().splitlines()
    if len(lines) < 3:
        return
    t = int(lines[0].strip())
    if t < 1:
        return
    n_m = list(map(int, lines[1].strip().split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    a = list(map(int, lines[2].strip().split()))
    s = sum(a)
    if s != m:
        out = run(x)
        out_lines = out.splitlines()
        if out_lines:
            assert out_lines[0] == "NO"

def test_all_zeros_case(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    idx = 1
    zero_cases = []
    for i in range(t):
        if idx >= len(lines):
            break
        n_m = list(map(int, lines[idx].strip().split()))
        if len(n_m) < 2:
            break
        n, m = n_m[0], n_m[1]
        idx += 1
        if idx >= len(lines):
            break
        a = list(map(int, lines[idx].strip().split()))
        idx += 1
        if all(v == 0 for v in a):
            zero_cases.append((i, m))
    if not zero_cases:
        return
    out = run(x)
    out_lines = out.splitlines()
    for i, m in zero_cases:
        if i < len(out_lines):
            if m == 0:
                assert out_lines[i] == "YES"
            else:
                assert out_lines[i] == "NO"

def test_m_zero_case(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    idx = 1
    mzero_cases = []
    for i in range(t):
        if idx >= len(lines):
            break
        n_m = list(map(int, lines[idx].strip().split()))
        if len(n_m) < 2:
            break
        n, m = n_m[0], n_m[1]
        idx += 1
        if idx >= len(lines):
            break
        a = list(map(int, lines[idx].strip().split()))
        idx += 1
        if m == 0:
            s = sum(a)
            mzero_cases.append((i, s))
    if not mzero_cases:
        return
    out = run(x)
    out_lines = out.splitlines()
    for i, s in mzero_cases:
        if i < len(out_lines):
            if s == 0:
                assert out_lines[i] == "YES"
            else:
                assert out_lines[i] == "NO"

def test_single_element_case(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    t = int(lines[0].strip())
    idx = 1
    single_cases = []
    for i in range(t):
        if idx >= len(lines):
            break
        n_m = list(map(int, lines[idx].strip().split()))
        if len(n_m) < 2:
            break
        n, m = n_m[0], n_m[1]
        idx += 1
        if idx >= len(lines):
            break
        a = list(map(int, lines[idx].strip().split()))
        idx += 1
        if n == 1 and len(a) >= 1:
            single_cases.append((i, a[0], m))
    if not single_cases:
        return
    out = run(x)
    out_lines = out.splitlines()
    for i, a0, m in single_cases:
        if i < len(out_lines):
            if a0 == m:
                assert out_lines[i] == "YES"
            else:
                assert out_lines[i] == "NO"

def test_output_characters_are_valid(run, x):
    out = run(x)
    allowed = set("YESNO\n")
    for c in out:
        assert c in allowed

