def test_bruteforce_small(run, x):
    n, m = map(int, x.split())
    if n + m > 20:
        return
    import itertools
    total = 0
    L = n + m
    for ones in itertools.combinations(range(L), n):
        arr = [1 if i in ones else -1 for i in range(L)]
        max_pref = 0
        pref = 0
        for val in arr:
            pref += val
            if pref > max_pref:
                max_pref = pref
        total += max_pref
    total %= 998244853
    out = run(x).strip()
    assert int(out) == total

def test_n_zero(run, x):
    n, m = map(int, x.split())
    if n != 0:
        return
    out = run(x).strip()
    assert out == "0"

