def test_example1(run, x):
    output = run(x)
    example_input = "A.VFleaKing_is_the_author_of_this_problem\nB.Picks_is_the_author_of_this_problem\nC.Picking_is_the_author_of_this_problem\nD.Ftiasch_is_cute\n"
    if x == example_input:
        assert output == "D\n", f'Expected D\\n, got {output}'

def test_example2(run, x):
    output = run(x)
    example_input = "A.ab\nB.abcde\nC.ab\nD.abc\n"
    if x == example_input:
        assert output == "C\n", f'Expected C\\n, got {output}'

def test_example3(run, x):
    output = run(x)
    example_input = "A.c\nB.cc\nC.c\nD.c\n"
    if x == example_input:
        assert output == "B\n", f'Expected B\\n, got {output}'

def test_valid_output(run, x):
    output = run(x)
    assert output in {"A\n", "B\n", "C\n", "D\n"}, f'Invalid output {output}'

def test_unique_great(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = []
    for line in lines:
        desc = line[2:]
        lengths.append(len(desc))
    great = []
    for i in range(4):
        cond1 = all(lengths[j] >= 2*lengths[i] for j in range(4) if j != i)
        cond2 = all(lengths[i] >= 2*lengths[j] for j in range(4) if j != i)
        if cond1 or cond2:
            great.append(i)
    if len(great) == 1:
        expected = chr(ord('A') + great[0])
        assert output.strip() == expected, f'Expected {expected}, got {output.strip()}'

def test_zero_great(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = []
    for line in lines:
        desc = line[2:]
        lengths.append(len(desc))
    great = []
    for i in range(4):
        cond1 = all(lengths[j] >= 2*lengths[i] for j in range(4) if j != i)
        cond2 = all(lengths[i] >= 2*lengths[j] for j in range(4) if j != i)
        if cond1 or cond2:
            great.append(i)
    if len(great) == 0:
        assert output.strip() == "C", f'Expected C, got {output.strip()}'

def test_multiple_great(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = []
    for line in lines:
        desc = line[2:]
        lengths.append(len(desc))
    great = []
    for i in range(4):
        cond1 = all(lengths[j] >= 2*lengths[i] for j in range(4) if j != i)
        cond2 = all(lengths[i] >= 2*lengths[j] for j in range(4) if j != i)
        if cond1 or cond2:
            great.append(i)
    if len(great) >= 2:
        assert output.strip() == "C", f'Expected C, got {output.strip()}'

def test_all_equal(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = []
    for line in lines:
        desc = line[2:]
        lengths.append(len(desc))
    if len(set(lengths)) == 1:
        assert output.strip() == "C", f'Expected C, got {output.strip()}'

def test_non_C_must_be_great(run, x):
    output = run(x)
    letter = output.strip()
    if letter not in ['A','B','C','D']:
        return
    if letter == 'C':
        return
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = []
    for line in lines:
        desc = line[2:]
        lengths.append(len(desc))
    idx = ord(letter) - ord('A')
    cond1 = all(lengths[j] >= 2*lengths[idx] for j in range(4) if j != idx)
    cond2 = all(lengths[idx] >= 2*lengths[j] for j in range(4) if j != idx)
    assert cond1 or cond2, f'Choice {letter} is not great but was output'

def test_oracle(run, x):
    output = run(x)
    lines = x.strip().split('\n')
    if len(lines) != 4:
        return
    lengths = []
    for line in lines:
        desc = line[2:]
        lengths.append(len(desc))
    great = []
    for i in range(4):
        cond1 = all(lengths[j] >= 2*lengths[i] for j in range(4) if j != i)
        cond2 = all(lengths[i] >= 2*lengths[j] for j in range(4) if j != i)
        if cond1 or cond2:
            great.append(i)
    if len(great) == 1:
        expected = chr(ord('A') + great[0])
    else:
        expected = "C"
    assert output.strip() == expected, f'Expected {expected}, got {output.strip()}'

def test_exact_match(run, x):
    y, k, n = map(int, x.strip().split())
    out_str = run(x)
    s = out_str.strip()
    assert s != '', 'Empty output'
    if s == '-1':
        out_vals = []
    else:
        parts = s.split()
        out_vals = list(map(int, parts))
    lo = (y + k) // k          # ceil((y+1)/k)
    hi = n // k
    expected = []
    for m in range(lo, hi + 1):
        expected.append(m * k - y)
    if not expected:
        assert out_vals == [], f'Expected -1 but got {out_vals}'
    else:
        assert out_vals == expected, f'Expected {expected}, got {out_vals}'

def test_ascending_unique(run, x):
    y, k, n = map(int, x.strip().split())
    out_str = run(x)
    s = out_str.strip()
    if s == '-1':
        return
    parts = s.split()
    nums = list(map(int, parts))
    for i in range(len(nums) - 1):
        assert nums[i] < nums[i + 1], f'Not strictly ascending: {nums[i]} >= {nums[i+1]}'

def test_each_satisfies_conditions(run, x):
    y, k, n = map(int, x.strip().split())
    out_str = run(x)
    s = out_str.strip()
    if s == '-1':
        return
    parts = s.split()
    for part in parts:
        x_val = int(part)
        assert 1 <= x_val <= n - y, f'x={x_val} out of range'
        assert (x_val + y) % k == 0, f'x={x_val} does not satisfy (x+y)%k==0'

def test_output_format(run, x):
    out_str = run(x)
    s = out_str.strip()
    assert s != '', 'Empty output'
    parts = s.split()
    for part in parts:
        if part[0] == '-':
            assert part == '-1' and len(parts) == 1, f'Invalid negative number: {part}'
        else:
            assert part.isdigit(), f'Non-digit character in number: {part}'
    if len(parts) > 1:
        for part in parts:
            assert int(part) > 0, f'Non-positive number in list: {part}'

def test_existence_consistency(run, x):
    y, k, n = map(int, x.strip().split())
    lo = (y + k) // k
    hi = n // k
    exists = lo <= hi
    out_str = run(x)
    s = out_str.strip()
    if exists:
        assert s != '-1', f'Solutions exist but output is -1'
    else:
        assert s == '-1', f'No solutions but output is not -1: {s}'

def test_minimal_x_present(run, x):
    y, k, n = map(int, x.strip().split())
    lo = (y + k) // k
    hi = n // k
    if lo > hi:
        return
    smallest = lo * k - y
    out_str = run(x)
    s = out_str.strip()
    if s == '-1':
        assert False, f'Expected at least one solution (smallest {smallest}) but got -1'
    parts = s.split()
    nums = list(map(int, parts))
    assert smallest in nums, f'Smallest possible x {smallest} not in output'

def test_maximal_x_present(run, x):
    y, k, n = map(int, x.strip().split())
    lo = (y + k) // k
    hi = n // k
    if lo > hi:
        return
    largest = hi * k - y
    out_str = run(x)
    s = out_str.strip()
    if s == '-1':
        assert False, f'Expected at least one solution (largest {largest}) but got -1'
    parts = s.split()
    nums = list(map(int, parts))
    assert largest in nums, f'Largest possible x {largest} not in output'

def test_count_matches(run, x):
    y, k, n = map(int, x.strip().split())
    lo = (y + k) // k
    hi = n // k
    expected_count = max(0, hi - lo + 1)
    out_str = run(x)
    s = out_str.strip()
    if s == '-1':
        actual_count = 0
    else:
        parts = s.split()
        actual_count = len(parts)
    assert actual_count == expected_count, f'Expected {expected_count} numbers, got {actual_count}'

def test_brute_force_small_n(run, x):
    y, k, n = map(int, x.strip().split())
    if n > 10000:
        return
    out_str = run(x)
    s = out_str.strip()
    if s == '-1':
        out_vals = []
    else:
        parts = s.split()
        out_vals = list(map(int, parts))
    expected = []
    for x_candidate in range(1, n - y + 1):
        if (x_candidate + y) % k == 0:
            expected.append(x_candidate)
    if not expected:
        assert out_vals == [], f'Expected -1 but got {out_vals}'
    else:
        assert out_vals == expected, f'Expected {expected}, got {out_vals}'

def test_arithmetic_progression(run, x):
    y, k, n = map(int, x.strip().split())
    out_str = run(x)
    s = out_str.strip()
    if s == '-1':
        return
    parts = s.split()
    nums = list(map(int, parts))
    if len(nums) < 2:
        return
    step = nums[1] - nums[0]
    assert step > 0, f'Step must be positive, got {step}'
    for i in range(1, len(nums)):
        assert nums[i] - nums[i-1] == step, f'Difference not constant at position {i}: {nums[i-1]}, {nums[i]}'
    assert step == k, f'Step {step} does not equal k={k}'

