def test_output_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, f"Output '{out}' is not an integer"

def test_answer_nonnegative_if_not_minus1(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    val = int(out)
    assert val >= 0, f"Answer {val} must be nonnegative when not -1"

def test_answer_not_exceed_n(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    val = int(out)
    data = x.strip().split()
    n = int(data[0])
    assert val <= n, f"Answer {val} exceeds number of days {n}"

def test_minus1_when_max_pref_gt_d(run, x):
    out = run(x).strip()
    data = x.strip().split()
    n = int(data[0])
    d = int(data[1])
    a = list(map(int, data[2:2 + n]))
    pref = 0
    max_pref = 0
    for v in a:
        pref += v
        if pref > max_pref:
            max_pref = pref
    if max_pref > d:
        assert out == '-1', f"max prefix {max_pref} > d {d}, must output -1"

def test_zero_when_no_negative_check_and_max_pref_le_d(run, x):
    out = run(x).strip()
    data = x.strip().split()
    n = int(data[0])
    d = int(data[1])
    a = list(map(int, data[2:2 + n]))
    pref = 0
    max_pref = 0
    check_negative = False
    for v in a:
        pref += v
        if pref > max_pref:
            max_pref = pref
        if v == 0 and pref < 0:
            check_negative = True
    if max_pref <= d and not check_negative:
        assert out == '0', f"Should output 0, got {out}"

def test_example1(run, x):
    out = run(x).strip()
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    d = int(data[1])
    a = list(map(int, data[2:2 + n]))
    if n == 5 and d == 10 and a == [-1, 5, 0, -5, 3]:
        assert out == '0', f"Example 1 must output 0, got {out}"

def test_example3(run, x):
    out = run(x).strip()
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    d = int(data[1])
    a = list(map(int, data[2:2 + n]))
    if n == 5 and d == 10 and a == [-5, 0, 10, -11, 0]:
        assert out == '2', f"Example 3 must output 2, got {out}"

def test_no_check_days(run, x):
    out = run(x).strip()
    data = x.strip().split()
    n = int(data[0])
    d = int(data[1])
    a = list(map(int, data[2:2 + n]))
    if 0 in a:
        return
    pref = 0
    max_pref = 0
    for v in a:
        pref += v
        if pref > max_pref:
            max_pref = pref
    if max_pref <= d:
        assert out == '0', f"No check days, max_pref {max_pref} <= d {d}, expected 0"
    else:
        assert out == '-1', f"No check days, max_pref {max_pref} > d {d}, expected -1"

def test_n1_simple(run, x):
    out = run(x).strip()
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n != 1:
        return
    d = int(data[1])
    a = list(map(int, data[2:]))
    if a[0] > d:
        assert out == '-1', f"n=1, a={a[0]} > d={d}, must output -1"
    else:
        assert out == '0', f"n=1, a={a[0]} <= d={d}, must output 0"

def test_brute_force_small_correct(run, x):
    out = run(x).strip()
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[0])
    if n > 8:
        return
    d = int(data[1])
    a = list(map(int, data[2:2 + n]))
    pref = [0] * n
    s = 0
    for i in range(n):
        s += a[i]
        pref[i] = s
    U = [d - p for p in pref]
    INF = n + 1
    best = INF
    for mask in range(1 << n):
        y = 0
        feasible = True
        for i in range(n):
            min_y = y
            if (mask >> i) & 1:
                min_y = y + 1
            if a[i] == 0:
                min_y = max(min_y, -pref[i])
            if min_y > U[i]:
                feasible = False
                break
            y = min_y
        if feasible:
            best = min(best, bin(mask).count('1'))
    correct = -1 if best == INF else best
    assert out == str(correct), f"Brute force (n<=8) expects {correct}, got {out}"

