def test_oracle_constraints(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    for i in range(1, n+1):
        parts = lines[i].split()
        c.append(int(parts[0]))
        d.append(int(parts[1]))
    S = [0]*(n+1)
    total = 0
    for i in range(1, n+1):
        S[i] = total
        total += c[i-1]
    L0 = -10**18
    U0 = 10**18
    has_lower = False
    has_upper = False
    for i in range(1, n+1):
        if d[i-1] == 1:
            L0 = max(L0, 1900 - S[i])
            has_lower = True
        else:
            U0 = min(U0, 1899 - S[i])
            has_upper = True
    if not has_lower:
        L0 = -10**18
    if not has_upper:
        U0 = 10**18
    if L0 > U0:
        correct = "Impossible"
    elif not has_upper:
        correct = "Infinity"
    else:
        correct = str(U0 + total)
    output = run(x).strip()
    assert output == correct

def test_feasibility(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
