    if output == "Infinity" or output == "Impossible":
        return
    try:
        final = int(output)
    except ValueError:
        assert False, "Output not integer"
    r0 = final - total
    for i in range(1, n+1):
        rating_before = r0 + S[i]
        if d[i-1] == 1:
            if rating_before < 1900:
                assert False, "Feasibility violated"
        else:
            if rating_before > 1899:
                assert False, "Feasibility violated"

