def test_brute_force(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return
    c = []
    d = []
    for i in range(1, n+1):
        parts = lines[i].split()
        c.append(int(parts[0]))
        d.append(int(parts[1]))
    total = sum(c)
    S = [0]*(n+1)
    pref = 0
    for i in range(1, n+1):
        S[i] = pref
        pref += c[i-1]
    points = []
    for i in range(1, n+1):
        if d[i-1] == 1:
            points.append(1900 - S[i])
        else:
            points.append(1899 - S[i])
    candidates = set()
    for p in points:
        for delta in range(-2, 3):
            candidates.add(p + delta)
    if not candidates:
        candidates = {0}
    low = min(candidates) - 1000
    high = max(candidates) + 1000
    best = None
    for r0 in range(low, high+1):
        ok = True
        for i in range(1, n+1):
            rating_before = r0 + S[i]
            if d[i-1] == 1 and rating_before < 1900:
                ok = False
                break
            if d[i-1] == 2 and rating_before > 1899:
                ok = False
                break
        if ok:
            final = r0 + total
            if best is None or final > best:
                best = final
    has_upper = any(di == 2 for di in d)
    output = run(x).strip()
    if best is None:
        assert output == "Impossible", "Brute force found no solution but output not Impossible"
    else:
        if not has_upper:
            assert output == "Infinity", "No upper bound, should be Infinity"
        else:
            if output == "Infinity":
                assert False, "Should not be Infinity when there is upper bound"
            elif output == "Impossible":
                assert False, "Should not be Impossible when brute force found solution"
            else:
                assert int(output) == best, f"Brute force maximum {best} differs from output {output}"

