def test_format(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    MOD = 10**9 + 7
    assert output.endswith('\n'), 'output must end with newline'
    line = output[:-1]
    assert line.isdigit() or (line.startswith('-') and line[1:].isdigit()), 'output must be an integer'
    val = int(line)
    assert 0 <= val < MOD, 'output must be between 0 and MOD-1'
    assert output == f'{val}\n', 'output must be exactly the integer followed by newline'

def test_zero_iff_unreachable(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    ans = int(output.strip())
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        reachable = a >= 0 and b >= 0
    else:
        reachable = False
    assert (ans == 0) == (not reachable), 'answer should be zero iff unreachable'

def test_one_if_zero_moves(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    ans = int(output.strip())
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a >= 0 and b >= 0 and (a == 0 or b == 0):
            assert ans == 1, 'if one move type count is zero, there is exactly one way'

def test_small_exact(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    MOD = 10**9 + 7
    ans = int(output.strip())
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a >= 0 and b >= 0:
            n = a + b
            if n <= 1000:
                k = min(a, b)
                res = 1
                for i in range(1, k+1):
                    res = res * (n - k + i) % MOD
                    res = res * pow(i, MOD-2, MOD) % MOD
                assert ans == res, f'for small total moves, answer should be C({n},{a}) mod MOD'

def test_nonzero_implies_nonnegative(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    ans = int(output.strip())
    if ans != 0:
        assert (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0, 'nonzero implies divisibility'
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        assert a >= 0 and b >= 0, 'nonzero implies nonnegative a,b'

def test_sample(run, x):
    output = run(x)
    if x.strip() == '3 3':
        assert output.strip() == '2', 'sample input 3 3 must output 2'

def test_positive_if_reachable(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    ans = int(output.strip())
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X) // 3
        b = (2*X - Y) // 3
        if a >= 0 and b >= 0:
            assert ans > 0, 'reachable position must have positive number of ways'

def test_small_dp(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    if X <= 20 and Y <= 20:
        MOD = 10**9 + 7
        ans = int(output.strip())
        dp = [[0]*(Y+1) for _ in range(X+1)]
        dp[0][0] = 1
        for i in range(X+1):
            for j in range(Y+1):
                if i >= 1 and j >= 2:
                    dp[i][j] = (dp[i][j] + dp[i-1][j-2]) % MOD
                if i >= 2 and j >= 1:
                    dp[i][j] = (dp[i][j] + dp[i-2][j-1]) % MOD
        expected = dp[X][Y]
        assert ans == expected, f'DP for small coordinates gives {expected}'

def test_sum_divisible_by_3(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    ans = int(output.strip())
    if (X + Y) % 3 != 0:
        assert ans == 0, 'if (X+Y) not divisible by 3, answer must be 0'

def test_specific_cases(run, x):
    output = run(x)
    parts = x.strip().split()
    if len(parts) != 2:
        return
    try:
        X = int(parts[0])
        Y = int(parts[1])
    except:
        return
    if not (1 <= X <= 10**6 and 1 <= Y <= 10**6):
        return
    cases = {
        "2 4": 1,
        "4 2": 1,
        "5 1": 0,
        "3 6": 1,
        "7 7": 0,
        "10 10": 0,
        "3 3": 2,
        "1 1": 0,
        "2 2": 0,
        "5 7": 4,
        "4 5": 3,
        "6 9": 5,
        "8 10": 15,
        "12 12": 70,
        "15 15": 252,
    }
    key = x.strip()
    if key in cases:
        ans = int(output.strip())
        assert ans == cases[key], f"Expected {cases[key]}, got {ans}"

