tests_src:
def test_output_integer(run, x):
    output = run(x)
    try:
        int(output.strip())
    except ValueError:
        assert False, "Output is not an integer"

def test_output_nonnegative(run, x):
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        return
    assert val >= 0

def test_exact_volume(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    words = text.split()
    if not words:
        return
    def volume(word):
        return sum(1 for ch in word if 'A' <= ch <= 'Z')
    expected = max(volume(w) for w in words)
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        assert False, "Output not integer"
    assert val == expected, f"Expected {expected}, got {val}"

def test_output_at_most_max_word_length(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    words = text.split()
    if not words:
        return
    max_len = max(len(w) for w in words)
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        return
    assert val <= max_len

def test_output_at_least_each_word_volume(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    words = text.split()
    if not words:
        return
    def volume(word):
        return sum(1 for ch in word if 'A' <= ch <= 'Z')
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        return
    for w in words:
        assert val >= volume(w)

def test_all_lowercase_zero(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    words = text.split()
    if not words:
        return
    if any('A' <= ch <= 'Z' for ch in text):
        return
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        return
    assert val == 0

def test_single_word_volume(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    if ' ' in text:
        return
    def volume(word):
        return sum(1 for ch in word if 'A' <= ch <= 'Z')
    expected = volume(text)
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        return
    assert val == expected

def test_output_at_most_total_capitals(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    total = sum(1 for ch in text if 'A' <= ch <= 'Z')
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        return
    assert val <= total

def test_output_at_most_n(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        return
    assert val <= n

def test_any_uppercase_output_positive(run, x):
    lines = x.splitlines()
    if len(lines) < 2:
        return
    try:
        n = int(lines[0].strip())
    except ValueError:
        return
    if n < 1 or n > 200:
        return
    text = lines[1]
    if len(text) != n:
        return
    if any('A' <= ch <= 'Z' for ch in text):
        output = run(x)
        try:
            val = int(output.strip())
        except ValueError:
            return
        assert val >= 1

