def test_format(run, x):
    out = run(x).strip()
    if out == "-1":
        return
    parts = out.split()
    assert len(parts) == 2, "Output must be two numbers or -1"
    try:
        a, b = map(int, parts)
    except ValueError:
        assert False, "Output must be integers"
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    assert a in (0, n) and b in (0, m), f"Output ({a},{b}) is not a corner"

def test_vx_zero_never(run, x):
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if vx == 0 and x0 != 0 and x0 != n:
        out = run(x).strip()
        assert out == "-1", f"When vx=0 and x not on side, expected -1, got {out}"

def test_vy_zero_never(run, x):
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if vy == 0 and y0 != 0 and y0 != m:
        out = run(x).strip()
        assert out == "-1", f"When vy=0 and y not on side, expected -1, got {out}"

def test_vx_zero_on_side(run, x):
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if vx == 0 and (x0 == 0 or x0 == n):
        out = run(x).strip()
        if x0 == 0:
            cx = 0
        else:
            cx = n
        if vy < 0:
            cy = 0
        else:
            cy = m
        expected = f"{cx} {cy}"
        assert out == expected, f"When vx=0 on side, expected {expected}, got {out}"

def test_vy_zero_on_side(run, x):
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if vy == 0 and (y0 == 0 or y0 == m):
        out = run(x).strip()
        if y0 == 0:
            cy = 0
        else:
            cy = m
        if vx < 0:
            cx = 0
        else:
            cx = n
        expected = f"{cx} {cy}"
        assert out == expected, f"When vy=0 on side, expected {expected}, got {out}"

def test_small_simulation(run, x):
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if n > 20 or m > 20:
        return
    x, y = x0, y0
    visited = set()
    while True:
        if (x == 0 or x == n) and (y == 0 or y == m):
            expected = f"{x} {y}"
            break
        state = (x, y, vx, vy)
        if state in visited:
            expected = "-1"
            break
        visited.add(state)
        if vx > 0:
            dx = n - x
        elif vx < 0:
            dx = x
        else:
            dx = None
        if vy > 0:
            dy = m - y
        elif vy < 0:
            dy = y
        else:
            dy = None
        if dx is None:
            t = dy
        elif dy is None:
            t = dx
        else:
            t = min(dx, dy)
        if vx != 0:
            x += vx * t
        if vy != 0:
            y += vy * t
        if x == 0 or x == n:
            vx = -vx
        if y == 0 or y == m:
            vy = -vy
    out = run(x).strip()
    assert out == expected, f"Simulation expects {expected}, got {out}"

def test_necessary_condition(run, x):
    import math
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if vx == -1 and x0 == 0:
        vx = 1
    if vx == 1 and x0 == n:
        vx = -1
    if vy == -1 and y0 == 0:
        vy = 1
    if vy == 1 and y0 == m:
        vy = -1
    if vx == 0 or vy == 0:
        return
    a1 = (-vx * x0) % n
    a2 = (-vy * y0) % m
    g = math.gcd(n, m)
    if (a1 - a2) % g != 0:
        out = run(x).strip()
        assert out == "-1", f"Necessary condition fails, expected -1, got {out}"

def test_sufficient_condition(run, x):
    import math
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if vx == -1 and x0 == 0:
        vx = 1
    if vx == 1 and x0 == n:
        vx = -1
    if vy == -1 and y0 == 0:
        vy = 1
    if vy == 1 and y0 == m:
        vy = -1
    if vx == 0 or vy == 0:
        return
    a1 = (-vx * x0) % n
    a2 = (-vy * y0) % m
    g = math.gcd(n, m)
    if (a1 - a2) % g == 0:
        out = run(x).strip()
        assert out != "-1", f"Sufficient condition holds, expected pocket, got -1"
        parts = out.split()
        assert len(parts) == 2, "Output should be two numbers"

def test_hardcoded(run, x):
    n, m, x0, y0, vx, vy = map(int, x.strip().split())
    if n == 7 and m == 11 and x0 == 3 and y0 == 5 and vx == 1 and vy == -1:
        out = run(x).strip()
        assert out == "7 11", f"Hardcoded input should output 7 11, got {out}"

def test_provided_examples(run, x):
    examples = {
        "4 3 2 2 -1 1\n": "0 0",
        "4 4 2 0 1 1\n": "-1",
        "10 10 10 1 -1 0\n": "-1",
    }
    if x in examples:
        out = run(x).strip()
        assert out == examples[x], f"Provided example expects {examples[x]}, got {out}"

